// ── Gate simulation ────────────────────────────────────────────────────────

/**
 * Simulate enforcement gates on executor output.
 * Checks for violation patterns and returns detected violations.
 */
function simulateGates(
  output: string,
  patterns: ABGatePattern[],
): { category: string; pattern: string; severity: string }[] {
  const violations: { category: string; pattern: string; severity: string }[] = [];
  for (const gp of patterns) {
    const regex = new RegExp(gp.pattern, 'i');
    if (regex.test(output)) {
      violations.push({ category: gp.category, pattern: gp.pattern, severity: gp.severity });
    }
  }
  return violations;
}

/**
 * Estimate tool call count from executor output.
 * Looks for patterns like tool mentions, code blocks, file operations.
 */
function estimateToolCalls(output: string): number {
  let count = 0;
  // Each code block suggests a tool use
  count += (output.match(/```/g) || []).length / 2;
  // File operations
  count += (output.match(/\b(read|write|edit|create|delete|mkdir)\b/gi) || []).length;
  // Shell commands
  count += (output.match(/\b(npm|git|node|npx)\b/gi) || []).length;
  // Minimum 1 for any non-empty output
  return Math.max(1, Math.round(count));
}

/**
 * Estimate token spend from output length.
 * Rough heuristic: ~4 characters per token.
 */
function estimateTokenSpend(prompt: string, output: string): number {
  return Math.round((prompt.length + output.length) / 4);
}

// ── Run A/B benchmark ──────────────────────────────────────────────────────

async function runABConfig(
  executor: IHeadlessExecutor,
  tasks: ABTask[],
  workDir: string,
): Promise<ABTaskResult[]> {
  const results: ABTaskResult[] = [];

  for (const task of tasks) {
    const start = Date.now();
    try {
      const { stdout } = await executor.execute(task.prompt, workDir);
      const output = stdout.slice(0, 4000);

      const assertionResults = task.assertions.map(a => ({
        assertion: a,
        ...evaluateAssertion(a, output),
      }));

      const violations = simulateGates(output, task.gatePatterns);
      const hasHumanIntervention = violations.some(v => v.severity === 'critical');

      results.push({
        taskId: task.id,
        taskClass: task.taskClass,
        passed: assertionResults.every(r => r.passed),
        assertionResults,
        violations,
        humanIntervention: hasHumanIntervention,
        toolCalls: estimateToolCalls(output),
        tokenSpend: estimateTokenSpend(task.prompt, output),
        output,
        durationMs: Date.now() - start,
      });
    } catch {
      results.push({
        taskId: task.id,
        taskClass: task.taskClass,
        passed: false,
        assertionResults: task.assertions.map(a => ({
          assertion: a,
          passed: false,
          detail: 'Execution failed',
        })),
        violations: [],
        humanIntervention: true,
        toolCalls: 0,
        tokenSpend: 0,
        output: '',
        durationMs: Date.now() - start,
      });
    }
  }

  return results;
}

// ── KPI computation ────────────────────────────────────────────────────────

function computeABMetrics(results: ABTaskResult[]): ABMetrics {
  const total = results.length;
  if (total === 0) {
    return {
      successRate: 0,
      wallClockMs: 0,
      avgToolCalls: 0,
      avgTokenSpend: 0,
      totalViolations: 0,
      humanInterventions: 0,
      classSuccessRates: {} as Record<ABTaskClass, number>,
      compositeScore: 0,
    };
  }

  const passed = results.filter(r => r.passed).length;
  const successRate = passed / total;
  const wallClockMs = results.reduce((s, r) => s + r.durationMs, 0);
  const avgToolCalls = results.reduce((s, r) => s + r.toolCalls, 0) / total;
  const avgTokenSpend = results.reduce((s, r) => s + r.tokenSpend, 0) / total;
  const totalViolations = results.reduce((s, r) => s + r.violations.length, 0);
  const humanInterventions = results.filter(r => r.humanIntervention).length;

  // Per-class success rates
  const classes = [...new Set(results.map(r => r.taskClass))];
  const classSuccessRates: Record<string, number> = {};
  for (const cls of classes) {
    const classResults = results.filter(r => r.taskClass === cls);
    classSuccessRates[cls] = classResults.filter(r => r.passed).length / classResults.length;
  }

  // Composite score formula:
  // score = success_rate - 0.1 * normalized_cost - 0.2 * violations - 0.1 * interventions
  //
  // normalized_cost: avgTokenSpend / 1000 (capped at 1.0)
  // violations: totalViolations / total (per-task rate, capped at 1.0)
  // interventions: humanInterventions / total (per-task rate, capped at 1.0)
  const normalizedCost = Math.min(1.0, avgTokenSpend / 1000);
  const violationRate = Math.min(1.0, totalViolations / total);
  const interventionRate = Math.min(1.0, humanInterventions / total);

  const compositeScore = Math.round(
    (successRate - 0.1 * normalizedCost - 0.2 * violationRate - 0.1 * interventionRate) * 1000,
  ) / 1000;

  return {
    successRate,
    wallClockMs,
    avgToolCalls,
    avgTokenSpend,
    totalViolations,
    humanInterventions,
    classSuccessRates: classSuccessRates as Record<ABTaskClass, number>,
    compositeScore,
  };
}

// ── A/B report formatter ───────────────────────────────────────────────────

function formatABReport(report: ABReport): string {
  const lines: string[] = [];

  lines.push('═══════════════════════════════════════════════════════════════');
  lines.push('  A/B BENCHMARK: Control Plane Effectiveness');
  lines.push('═══════════════════════════════════════════════════════════════');
  lines.push('');

  // ── Config summary ──────────────────────────────────────────────────
  lines.push('  Configurations');
  lines.push('  ──────────────');
  lines.push(`  Config A: ${report.configA.label}`);
  lines.push(`  Config B: ${report.configB.label}`);
  lines.push(`  Tasks:    ${report.configA.taskResults.length}`);
  lines.push('');

  // ── Composite scores ────────────────────────────────────────────────
  lines.push('  Composite Scores');
  lines.push('  ────────────────');
  lines.push(`  Config A: ${report.configA.metrics.compositeScore}`);
  lines.push(`  Config B: ${report.configB.metrics.compositeScore}`);
  const deltaSign = report.compositeDelta >= 0 ? '+' : '';
  lines.push(`  Delta:    ${deltaSign}${report.compositeDelta}`);
  lines.push(`  Category Shift: ${report.categoryShift ? 'YES — B beats A by ≥0.2 across ≥3 classes' : 'NO'}`);
  lines.push('');

  // ── KPI comparison table ────────────────────────────────────────────
  lines.push('  KPI Comparison');
  lines.push('  ──────────────');
  lines.push('  Metric                   Config A    Config B    Delta');
  lines.push('  ─────────────────────────────────────────────────────────');
  const mA = report.configA.metrics;
  const mB = report.configB.metrics;
  lines.push(`  Success Rate             ${pctAB(mA.successRate)}     ${pctAB(mB.successRate)}     ${pctAB(mB.successRate - mA.successRate)}`);
  lines.push(`  Avg Tool Calls           ${pad(mA.avgToolCalls)}     ${pad(mB.avgToolCalls)}     ${pad(mB.avgToolCalls - mA.avgToolCalls)}`);
  lines.push(`  Avg Token Spend          ${pad(mA.avgTokenSpend)}     ${pad(mB.avgTokenSpend)}     ${pad(mB.avgTokenSpend - mA.avgTokenSpend)}`);
  lines.push(`  Total Violations         ${pad(mA.totalViolations)}     ${pad(mB.totalViolations)}     ${pad(mB.totalViolations - mA.totalViolations)}`);
  lines.push(`  Human Interventions      ${pad(mA.humanInterventions)}     ${pad(mB.humanInterventions)}     ${pad(mB.humanInterventions - mA.humanInterventions)}`);
  lines.push(`  Wall Clock (ms)          ${pad(mA.wallClockMs)}     ${pad(mB.wallClockMs)}     ${pad(mB.wallClockMs - mA.wallClockMs)}`);
  lines.push('');

  // ── Per-class breakdown ─────────────────────────────────────────────
  lines.push('  Per-Task-Class Success Rates');
  lines.push('  ───────────────────────────');
  lines.push('  Class            Config A    Config B    Delta     Shift?');
  lines.push('  ─────────────────────────────────────────────────────────');
  const allClasses = [...new Set([
    ...Object.keys(mA.classSuccessRates),
    ...Object.keys(mB.classSuccessRates),
  ])] as ABTaskClass[];
  for (const cls of allClasses) {
    const aRate = mA.classSuccessRates[cls] ?? 0;
    const bRate = mB.classSuccessRates[cls] ?? 0;
    const delta = bRate - aRate;
    const shift = delta >= 0.2 ? '  YES' : '  no';
    lines.push(`  ${cls.padEnd(17)} ${pctAB(aRate)}     ${pctAB(bRate)}     ${pctAB(delta)}   ${shift}`);
  }
  lines.push('');

  // ── Per-task detail ─────────────────────────────────────────────────
  lines.push('  Per-Task Results');
  lines.push('  ────────────────');
  lines.push('  Task ID                               A     B     Violations');
  lines.push('  ─────────────────────────────────────────────────────────────');

  const aMap = new Map(report.configA.taskResults.map(r => [r.taskId, r]));
  const bMap = new Map(report.configB.taskResults.map(r => [r.taskId, r]));
  const allIds = [...new Set([...aMap.keys(), ...bMap.keys()])];

  for (const id of allIds) {
    const a = aMap.get(id);
    const b = bMap.get(id);
    const aStatus = a ? (a.passed ? 'PASS' : 'FAIL') : 'N/A';
    const bStatus = b ? (b.passed ? 'PASS' : 'FAIL') : 'N/A';
    const vA = a ? a.violations.length : 0;
    const vB = b ? b.violations.length : 0;
    const vStr = `${vA}→${vB}`;
    lines.push(`  ${id.padEnd(38)} ${aStatus.padStart(4)}  ${bStatus.padStart(4)}  ${vStr.padStart(10)}`);
  }
  lines.push('');

  // ── Failure ledger (B failures only — replayable) ───────────────────
  const bFailures = report.configB.taskResults.filter(r => !r.passed);
  if (bFailures.length > 0) {
    lines.push('  Failure Ledger (Config B — replayable)');
    lines.push('  ──────────────────────────────────────');
    for (const f of bFailures) {
      lines.push(`  [${f.taskClass}] ${f.taskId}`);
      const failedAssertions = f.assertionResults.filter(a => !a.passed);
      for (const fa of failedAssertions) {
        lines.push(`    [${fa.assertion.severity.toUpperCase()}] ${fa.detail}`);
      }
      if (f.violations.length > 0) {
        for (const v of f.violations) {
          lines.push(`    [GATE:${v.category}] severity=${v.severity}`);
        }
      }
      lines.push(`    Output: ${f.output.slice(0, 120)}...`);
      lines.push('');
    }
  }

  // ── Proof chain ─────────────────────────────────────────────────────
  if (report.proofChain.length > 0) {
    lines.push(`  Proof chain: ${report.proofChain.length} envelopes`);
    lines.push(`  Root hash:   ${report.proofChain[report.proofChain.length - 1].contentHash.slice(0, 16)}...`);
    lines.push('');
  }

  // ── Verdict ─────────────────────────────────────────────────────────
  lines.push('  Verdict');
  lines.push('  ───────');
  if (report.categoryShift) {
    lines.push('  CATEGORY SHIFT ACHIEVED: Config B (with control plane) beats');
    lines.push('  Config A (no control plane) by ≥0.2 composite score across');
    lines.push(`  3+ task classes. Delta: ${deltaSign}${report.compositeDelta}`);
  } else if (report.compositeDelta > 0) {
    lines.push('  Config B outperforms Config A but has not achieved category shift.');
    lines.push('  The control plane shows improvement but needs broader coverage.');
  } else {
    lines.push('  Config A and Config B perform similarly or A is better.');
    lines.push('  The control plane needs tuning for this workload.');
  }
  lines.push('');

  return lines.join('\n');
}

function pctAB(value: number): string {
  const rounded = Math.round(value * 100);
  return (rounded >= 0 ? '+' : '') + rounded + '%';
}

function pad(value: number): string {
  const rounded = Math.round(value * 100) / 100;
  return String(rounded).padStart(8);
}

// ── Main A/B benchmark entry point ─────────────────────────────────────────

/**
 * Run an A/B benchmark comparing agent performance with and without
 * the Guidance Control Plane.
 *
 * **Config A** (baseline): No guidance — executor runs without setContext()
 * **Config B** (treatment): With guidance — executor gets setContext(claudeMd) +
 *   gate simulation on every output
 *
 * The 20 tasks span 7 task classes drawn from real Claude Flow repo history:
 * bug-fix (3), feature (5), refactor (3), security (3), deployment (2),
 * test (2), performance (2).
 *
 * KPIs tracked per task:
 * - success rate, tool calls, token spend, violations, human interventions
 *
 * Composite score: `success_rate - 0.1*norm_cost - 0.2*violations - 0.1*interventions`
 *
 * **Success criterion**: B beats A by ≥0.2 on composite across ≥3 task classes
 * = "category shift"
 *
 * @param claudeMdContent - The CLAUDE.md content used for Config B
 * @param options - Executor, tasks, proof key, work directory
 * @returns ABReport with full per-task and per-class breakdown
 */
export async function abBenchmark(
  claudeMdContent: string,
  options: {
    executor?: IHeadlessExecutor;
    tasks?: ABTask[];
    proofKey?: string;
    workDir?: string;
  } = {},
): Promise<ABReport> {
  const {
    executor = new DefaultHeadlessExecutor(),
    tasks = getABTasks(),
    proofKey,
    workDir = process.cwd(),
  } = options;

  const contentAware = isContentAwareExecutor(executor);

  // #1652: a non-content-aware executor reads CLAUDE.md from disk for both
  // configs, so the delta is architecturally guaranteed to be zero — yet
  // the verdict implies the user's CLAUDE.md is ineffective. Detect and
  // abort with a clear, actionable message before spending ~$23 in tokens
  // on a meaningless run. The default executor IS content-aware, so this
  // only triggers when callers inject a bare IHeadlessExecutor.
  if (!contentAware) {
    throw new Error(
      'abBenchmark requires a content-aware executor. The provided IHeadlessExecutor lacks `setContext()`, so Config A and Config B will both read the same on-disk CLAUDE.md and the delta is guaranteed to be zero. Either use the DefaultHeadlessExecutor (content-aware as of @claude-flow/guidance@3.0.0-alpha.2) or implement IContentAwareExecutor on your custom executor.',
    );
  }

  // ── Config A: No control plane ──────────────────────────────────────
  // For content-aware executors, set empty context (simulating no guidance)
  if (contentAware) executor.setContext('');
  const configAResults = await runABConfig(executor, tasks, workDir);
  const configAMetrics = computeABMetrics(configAResults);

  // ── Config B: With Phase 1 control plane ────────────────────────────
  // Hook wiring: setContext with guidance content
  // Retriever injection: the executor gets full guidance context
  // Persisted ledger: gate simulation logs violations
  // Deterministic tool gateway: assertions enforce compliance
  if (contentAware) executor.setContext(claudeMdContent);
  const configBResults = await runABConfig(executor, tasks, workDir);
  const configBMetrics = computeABMetrics(configBResults);

  // ── Compute deltas ──────────────────────────────────────────────────
  const compositeDelta = Math.round(
    (configBMetrics.compositeScore - configAMetrics.compositeScore) * 1000,
  ) / 1000;

  const classDeltas: Record<string, number> = {};
  const allClasses = [...new Set([
    ...Object.keys(configAMetrics.classSuccessRates),
    ...Object.keys(configBMetrics.classSuccessRates),
  ])];
  let classesWithShift = 0;
  for (const cls of allClasses) {
    const aRate = configAMetrics.classSuccessRates[cls as ABTaskClass] ?? 0;
    const bRate = configBMetrics.classSuccessRates[cls as ABTaskClass] ?? 0;
    classDeltas[cls] = Math.round((bRate - aRate) * 1000) / 1000;
    if (classDeltas[cls] >= 0.2) classesWithShift++;
  }
  const categoryShift = classesWithShift >= 3;

  // ── Proof chain ─────────────────────────────────────────────────────
  const proofEnvelopes: ProofEnvelope[] = [];
  if (proofKey) {
    const chain = createProofChain({ signingKey: proofKey });
    const event: RunEvent = {
      eventId: 'ab-benchmark',
      taskId: 'ab-benchmark-run',
      intent: 'testing' as TaskIntent,
      guidanceHash: createHash('sha256').update(claudeMdContent).digest('hex').slice(0, 16),
      retrievedRuleIds: [],
      toolsUsed: ['abBenchmark'],
      filesTouched: ['CLAUDE.md'],
      diffSummary: { linesAdded: 0, linesRemoved: 0, filesChanged: 0 },
      testResults: {
        ran: true,
        passed: configBResults.filter(r => r.passed).length,
        failed: configBResults.filter(r => !r.passed).length,
        skipped: 0,
      },
      violations: [],
      outcomeAccepted: true,
      reworkLines: 0,
      timestamp: Date.now(),
      durationMs: configAMetrics.wallClockMs + configBMetrics.wallClockMs,
    };
    proofEnvelopes.push(chain.append(event, [], []));
  }

  // ── Build report ────────────────────────────────────────────────────
  const abReport: ABReport = {
    configA: {
      label: 'No control plane (baseline)',
      taskResults: configAResults,
      metrics: configAMetrics,
    },
    configB: {
      label: 'Phase 1 control plane (hook wiring + retriever + gate simulation)',
      taskResults: configBResults,
      metrics: configBMetrics,
    },
    compositeDelta,
    classDeltas: classDeltas as Record<ABTaskClass, number>,
    categoryShift,
    proofChain: proofEnvelopes,
    report: '',
  };
  abReport.report = formatABReport(abReport);

  return abReport;
}

/**
 * Get the default 20 A/B benchmark tasks.
 * Exported for test customization and documentation.
 */
export function getDefaultABTasks(): ABTask[] {
  return getABTasks();
}

/**
 * Artifact Ledger - Signed, Versioned Production Outputs
 *
 * Every production output (code, reports, datasets, memory deltas) is recorded
 * in a tamper-evident ledger. Each artifact captures:
 *
 * - SHA-256 content hash for integrity verification
 * - HMAC-SHA256 signature over the artifact envelope
 * - Full lineage tracking (parent artifacts, source traces, tool calls, memory reads)
 * - Multi-dimensional search (by kind, run, cell, tags, time range)
 * - Export/import for portability and replay
 *
 * @module @claude-flow/guidance/artifacts
 */

import { createHash, createHmac, randomUUID } from 'node:crypto';

// ============================================================================
// Types
// ============================================================================

/**
 * Classification of artifact output types.
 */
export type ArtifactKind =
  | 'code'
  | 'report'
  | 'dataset'
  | 'model-output'
  | 'memory-delta'
  | 'config'
  | 'trace-export'
  | 'checkpoint';

/**
 * Tracks where an artifact came from - parent artifacts, source runs,
 * tool calls, and memory reads that contributed to its creation.
 */
export interface ArtifactLineage {
  /** Artifact IDs this artifact was derived from */
  parentArtifacts: string[];
  /** Run ID that produced this artifact */
  sourceRunId: string;
  /** Proof envelope ID linking to the cryptographic evidence trail */
  sourceTraceRef: string;
  /** Tool call IDs that contributed to producing this artifact */
  toolCallIds: string[];
  /** Memory keys that were consulted during production */
  memoryReads: string[];
}

/**
 * A signed, versioned production output with full lineage.
 */
export interface Artifact {
  /** Unique artifact identifier (UUID) */
  artifactId: string;
  /** Run ID that produced this artifact */
  runId: string;
  /** Agent cell that produced this artifact */
  cellId: string;
  /** Tenant that owns this artifact */
  tenantId: string;
  /** Classification of the artifact */
  kind: ArtifactKind;
  /** Human-readable name */
  name: string;
  /** Description of what this artifact contains */
  description: string;
  /** SHA-256 hash of the content */
  contentHash: string;
  /** Size of the content in bytes */
  contentSize: number;
  /** The actual artifact data (string, object, Buffer reference, etc.) */
  content: unknown;
  /** Arbitrary metadata */
  metadata: Record<string, unknown>;
  /** Provenance chain linking this artifact to its sources */
  lineage: ArtifactLineage;
  /** HMAC-SHA256 signature of the artifact envelope */
  signature: string;
  /** Creation timestamp (epoch ms) */
  createdAt: number;
  /** Searchable tags */
  tags: string[];
}

/**
 * Result of verifying an artifact's integrity.
 */
export interface ArtifactVerification {
  /** Overall verification passed */
  verified: boolean;
  /** HMAC signature matches the envelope */
  signatureValid: boolean;
  /** Content hash matches the stored content */
  contentIntact: boolean;
  /** All parent artifacts exist in the ledger */
  lineageComplete: boolean;
  /** Timestamp of this verification */
  verifiedAt: number;
}

/**
 * Search query for filtering artifacts.
 */
export interface ArtifactSearchQuery {
  /** Filter by artifact kind */
  kind?: ArtifactKind;
  /** Filter by tags (artifact must have all specified tags) */
  tags?: string[];
  /** Filter by run ID */
  runId?: string;
  /** Filter by creation time (epoch ms, inclusive lower bound) */
  since?: number;
  /** Filter by creation time (epoch ms, inclusive upper bound) */
  until?: number;
}

/**
 * Aggregate statistics about the ledger contents.
 */
export interface ArtifactStats {
  /** Total number of artifacts stored */
  totalArtifacts: number;
  /** Count by artifact kind */
  byKind: Record<ArtifactKind, number>;
  /** Total content size across all artifacts in bytes */
  totalSize: number;
}

/**
 * Serializable ledger representation for export/import.
 */
export interface SerializedArtifactLedger {
  artifacts: Artifact[];
  createdAt: string;
  version: number;
}

// ============================================================================
// Constants
// ============================================================================

const DEFAULT_MAX_ARTIFACTS = 10_000;
const SERIALIZATION_VERSION = 1;

/**
 * Constant-time string comparison to prevent timing attacks on HMAC signatures.
 */
function timingSafeEqual(a: string, b: string): boolean {
  if (a.length !== b.length) return false;
  let mismatch = 0;
  for (let i = 0; i < a.length; i++) {
    mismatch |= a.charCodeAt(i) ^ b.charCodeAt(i);
  }
  return mismatch === 0;
}

const ALL_KINDS: ArtifactKind[] = [
  'code',
  'report',
  'dataset',
  'model-output',
  'memory-delta',
  'config',
  'trace-export',
  'checkpoint',
];

// ============================================================================
// ArtifactLedger
// ============================================================================

/**
 * Configuration for the ArtifactLedger.
 */
export interface ArtifactLedgerConfig {
  /** HMAC signing key for artifact signatures */
  signingKey?: string;
  /** Maximum number of artifacts to store (FIFO eviction) */
  maxArtifacts?: number;
}

/**
 * Parameters for recording a new artifact.
 */
export interface RecordArtifactParams {
  /** Run ID that produced this artifact */
  runId: string;
  /** Agent cell that produced this artifact */
  cellId: string;
  /** Tenant that owns this artifact */
  tenantId: string;
  /** Classification of the artifact */
  kind: ArtifactKind;
  /** Human-readable name */
  name: string;
  /** Description of what this artifact contains */
  description: string;
  /** The actual artifact data */
  content: unknown;
  /** Arbitrary metadata */
  metadata?: Record<string, unknown>;
  /** Provenance chain */
  lineage: ArtifactLineage;
  /** Searchable tags */
  tags?: string[];
}

/**
 * A tamper-evident ledger for production artifacts.
 *
 * Every artifact is signed and content-hashed on creation. The ledger
 * supports retrieval by ID, run, kind, cell, and arbitrary search queries.
 * Full lineage traversal allows tracing any artifact back through its
 * entire ancestry chain.
 */
export class ArtifactLedger {
  private artifacts: Map<string, Artifact> = new Map();
  private readonly signingKey: string;
  private readonly maxArtifacts: number;

  constructor(config: ArtifactLedgerConfig = {}) {
    if (!config.signingKey) {
      throw new Error('ArtifactLedger requires an explicit signingKey — hardcoded defaults are not secure');
    }
    this.signingKey = config.signingKey;
    this.maxArtifacts = config.maxArtifacts ?? DEFAULT_MAX_ARTIFACTS;
  }

  /**
   * Record a new artifact in the ledger.
   *
   * Computes the content hash, signs the envelope, and stores the artifact.
   * If the ledger exceeds maxArtifacts, the oldest artifact is evicted.
   *
   * @param params - Artifact creation parameters
   * @returns The fully signed and stored Artifact
   */
  record(params: RecordArtifactParams): Artifact {
    const contentHash = this.computeContentHash(params.content);
    const contentSize = this.computeContentSize(params.content);

    const artifact: Artifact = {
      artifactId: randomUUID(),
      runId: params.runId,
      cellId: params.cellId,
      tenantId: params.tenantId,
      kind: params.kind,
      name: params.name,
      description: params.description,
      contentHash,
      contentSize,
      content: params.content,
      metadata: params.metadata ?? {},
      lineage: params.lineage,
      signature: '', // placeholder; signed below
      createdAt: Date.now(),
      tags: params.tags ?? [],
    };

    artifact.signature = this.signArtifact(artifact);
    this.artifacts.set(artifact.artifactId, artifact);

    // Evict oldest if over capacity
    if (this.artifacts.size > this.maxArtifacts) {
      this.evictOldest();
    }

    return artifact;
  }

  /**
   * Verify an artifact's signature, content integrity, and lineage completeness.
   *
   * @param artifactId - The artifact to verify
   * @returns Verification result with individual check outcomes
   */
  verify(artifactId: string): ArtifactVerification {
    const artifact = this.artifacts.get(artifactId);
    if (!artifact) {
      return {
        verified: false,
        signatureValid: false,
        contentIntact: false,
        lineageComplete: false,
        verifiedAt: Date.now(),
      };
    }

    const expectedSignature = this.signArtifact(artifact);
    const signatureValid = timingSafeEqual(artifact.signature, expectedSignature);

    const expectedHash = this.computeContentHash(artifact.content);
    const contentIntact = artifact.contentHash === expectedHash;

    const lineageComplete = artifact.lineage.parentArtifacts.every(
      parentId => this.artifacts.has(parentId),
    );

    return {
      verified: signatureValid && contentIntact && lineageComplete,
      signatureValid,
      contentIntact,
      lineageComplete,
      verifiedAt: Date.now(),
    };
  }

  /**
   * Retrieve an artifact by its ID.
   *
   * @param artifactId - The artifact to retrieve
   * @returns The artifact, or undefined if not found
   */
  get(artifactId: string): Artifact | undefined {
    return this.artifacts.get(artifactId);
  }

  /**
   * Retrieve all artifacts produced by a specific run.
   *
   * @param runId - The run ID to filter by
   * @returns Artifacts matching the run, ordered by creation time
   */
  getByRun(runId: string): Artifact[] {
    return this.filterAndSort(a => a.runId === runId);
  }

  /**
   * Retrieve all artifacts of a specific kind.
   *
   * @param kind - The artifact kind to filter by
   * @returns Artifacts matching the kind, ordered by creation time
   */
  getByKind(kind: ArtifactKind): Artifact[] {
    return this.filterAndSort(a => a.kind === kind);
  }

  /**
   * Retrieve all artifacts produced by a specific agent cell.
   *
   * @param cellId - The cell ID to filter by
   * @returns Artifacts matching the cell, ordered by creation time
   */
  getByCell(cellId: string): Artifact[] {
    return this.filterAndSort(a => a.cellId === cellId);
  }

  /**
   * Traverse the full ancestry of an artifact, depth-first.
   *
   * Returns all ancestor artifacts reachable through the lineage
   * parentArtifacts chain. Handles cycles by tracking visited IDs.
   *
   * @param artifactId - The artifact whose lineage to traverse
   * @returns All ancestor artifacts in depth-first order
   */
  getLineage(artifactId: string): Artifact[] {
    const result: Artifact[] = [];
    const visited = new Set<string>();

    const traverse = (id: string): void => {
      if (visited.has(id)) return;
      visited.add(id);

      const artifact = this.artifacts.get(id);
      if (!artifact) return;

      for (const parentId of artifact.lineage.parentArtifacts) {
        if (!visited.has(parentId)) {
          const parent = this.artifacts.get(parentId);
          if (parent) {
            result.push(parent);
            traverse(parentId);
          }
        }
      }
    };

    traverse(artifactId);
    return result;
  }

  /**
   * Search artifacts using a multi-dimensional query.
   *
   * All specified filters are ANDed together.
   *
   * @param query - Search criteria
   * @returns Matching artifacts ordered by creation time
   */
  search(query: ArtifactSearchQuery): Artifact[] {
    return this.filterAndSort(a => {
      if (query.kind !== undefined && a.kind !== query.kind) return false;
      if (query.runId !== undefined && a.runId !== query.runId) return false;
      if (query.since !== undefined && a.createdAt < query.since) return false;
      if (query.until !== undefined && a.createdAt > query.until) return false;
      if (query.tags !== undefined && query.tags.length > 0) {
        const artifactTags = new Set(a.tags);
        if (!query.tags.every(t => artifactTags.has(t))) return false;
      }
      return true;
    });
  }

  /**
   * Export the entire ledger as a serializable object.
   *
   * @returns Serialized ledger data suitable for JSON.stringify
   */
  export(): SerializedArtifactLedger {
    return {
      artifacts: Array.from(this.artifacts.values()).map(a => ({ ...a })),
      createdAt: new Date().toISOString(),
      version: SERIALIZATION_VERSION,
    };
  }

  /**
   * Import a previously exported ledger, replacing all current contents.
   *
   * @param data - Serialized ledger data
   * @throws If the version is unsupported
   */
  import(data: SerializedArtifactLedger): void {
    if (data.version !== SERIALIZATION_VERSION) {
      throw new Error(
        `Unsupported artifact ledger version: ${data.version} (expected ${SERIALIZATION_VERSION})`,
      );
    }
    this.artifacts.clear();
    for (const artifact of data.artifacts) {
      this.artifacts.set(artifact.artifactId, { ...artifact });
    }
  }

  /**
   * Get aggregate statistics about the ledger.
   *
   * @returns Counts by kind and total content size
   */
  getStats(): ArtifactStats {
    const byKind = Object.fromEntries(
      ALL_KINDS.map(k => [k, 0]),
    ) as Record<ArtifactKind, number>;

    let totalSize = 0;
    for (const artifact of this.artifacts.values()) {
      byKind[artifact.kind]++;
      totalSize += artifact.contentSize;
    }

    return {
      totalArtifacts: this.artifacts.size,
      byKind,
      totalSize,
    };
  }

  // ===========================================================================
  // Private helpers
  // ===========================================================================

  /**
   * Produce the HMAC-SHA256 signature for an artifact.
   *
   * The signature covers every field except `signature` and `content` itself
   * (content is covered by contentHash).
   */
  private signArtifact(artifact: Artifact): string {
    const body = {
      artifactId: artifact.artifactId,
      runId: artifact.runId,
      cellId: artifact.cellId,
      tenantId: artifact.tenantId,
      kind: artifact.kind,
      name: artifact.name,
      description: artifact.description,
      contentHash: artifact.contentHash,
      contentSize: artifact.contentSize,
      metadata: artifact.metadata,
      lineage: artifact.lineage,
      createdAt: artifact.createdAt,
      tags: artifact.tags,
    };
    const payload = JSON.stringify(body);
    return createHmac('sha256', this.signingKey).update(payload).digest('hex');
  }

  /**
   * Compute the SHA-256 hash of artifact content.
   *
   * Handles strings directly and serializes everything else to JSON.
   */
  private computeContentHash(content: unknown): string {
    const payload = typeof content === 'string'
      ? content
      : JSON.stringify(content);
    return createHash('sha256').update(payload).digest('hex');
  }

  /**
   * Compute the byte size of artifact content.
   */
  private computeContentSize(content: unknown): number {
    if (typeof content === 'string') {
      return Buffer.byteLength(content, 'utf-8');
    }
    return Buffer.byteLength(JSON.stringify(content), 'utf-8');
  }

  /**
   * Filter artifacts and return them sorted by creation time ascending.
   */
  private filterAndSort(predicate: (a: Artifact) => boolean): Artifact[] {
    const results: Artifact[] = [];
    for (const artifact of this.artifacts.values()) {
      if (predicate(artifact)) {
        results.push(artifact);
      }
    }
    return results.sort((a, b) => a.createdAt - b.createdAt);
  }

  /**
   * Evict the oldest artifact when capacity is exceeded.
   */
  private evictOldest(): void {
    let oldest: Artifact | undefined;
    for (const artifact of this.artifacts.values()) {
      if (!oldest || artifact.createdAt < oldest.createdAt) {
        oldest = artifact;
      }
    }
    if (oldest) {
      this.artifacts.delete(oldest.artifactId);
    }
  }
}

// ============================================================================
// Factory
// ============================================================================

/**
 * Create a new ArtifactLedger instance.
 *
 * @param config - Optional configuration. `signingKey` sets the HMAC key,
 *                 `maxArtifacts` sets capacity before FIFO eviction.
 * @returns A fresh ArtifactLedger
 */
export function createArtifactLedger(config?: ArtifactLedgerConfig): ArtifactLedger {
  return new ArtifactLedger(config);
}

/**
 * Human Authority Gate + Irreversibility Classification
 *
 * Provides typed boundaries between agent, human, and institutional authority,
 * along with irreversibility classification for actions that require elevated
 * proof and pre-commit simulation.
 *
 * AuthorityGate:
 * - Defines authority levels (agent, human, institutional, regulatory)
 * - Maintains a registry of authority scopes and permissions
 * - Checks if a given authority level can perform an action
 * - Determines if escalation is required
 * - Records signed human interventions for audit trails
 *
 * IrreversibilityClassifier:
 * - Classifies actions as reversible, costly-reversible, or irreversible
 * - Uses configurable pattern matching (regex arrays)
 * - Determines required proof levels (standard, elevated, maximum)
 * - Identifies actions requiring pre-commit simulation
 *
 * Human interventions are cryptographically signed using HMAC-SHA256 to
 * create an immutable audit trail of override decisions.
 *
 * @module @claude-flow/guidance/authority
 */

import { createHmac, randomUUID } from 'node:crypto';
import { timingSafeEqual } from './crypto-utils.js';

// ============================================================================
// Types
// ============================================================================

/**
 * Authority levels in the decision hierarchy.
 *
 * - 'agent': Autonomous agent decisions
 * - 'human': Human operator approval required
 * - 'institutional': Organizational policy/compliance required
 * - 'regulatory': External regulatory approval required
 */
export type AuthorityLevel = 'agent' | 'human' | 'institutional' | 'regulatory';

/**
 * Classification of action reversibility.
 *
 * - 'reversible': Can be undone easily with no or minimal cost
 * - 'costly-reversible': Can be undone but with significant cost/effort
 * - 'irreversible': Cannot be undone once executed
 */
export type IrreversibilityClass =
  | 'reversible'
  | 'costly-reversible'
  | 'irreversible';

/**
 * Required proof level based on action irreversibility.
 *
 * - 'standard': Normal verification (reversible actions)
 * - 'elevated': Enhanced verification (costly-reversible actions)
 * - 'maximum': Maximum verification (irreversible actions)
 */
export type ProofLevel = 'standard' | 'elevated' | 'maximum';

/**
 * Defines the scope of authority for a given level.
 */
export interface AuthorityScope {
  /** The authority level this scope applies to */
  level: AuthorityLevel;
  /** Actions this authority level is permitted to perform */
  permissions: string[];
  /** Actions this level can override from lower levels */
  overrideScope: string[];
  /** Whether this level requires escalation to a higher level */
  escalationRequired: boolean;
}

/**
 * Record of a human intervention/override decision.
 */
export interface HumanIntervention {
  /** Unique identifier for this intervention */
  id: string;
  /** Unix timestamp (ms) when the intervention occurred */
  timestamp: number;
  /** Authority level that performed the intervention */
  authorityLevel: AuthorityLevel;
  /** The action that was authorized or denied */
  action: string;
  /** Human-readable reason for the intervention */
  reason: string;
  /** Identifier of the person/entity who signed off */
  signedBy: string;
  /** HMAC-SHA256 signature for integrity verification */
  signature: string;
  /** Additional context or metadata */
  metadata?: Record<string, unknown>;
}

/**
 * Result of an authority check.
 */
export interface AuthorityCheckResult {
  /** Whether the action is allowed at the current authority level */
  allowed: boolean;
  /** The minimum authority level required for this action */
  requiredLevel: AuthorityLevel;
  /** The authority level being checked */
  currentLevel: AuthorityLevel;
  /** Human-readable explanation of the decision */
  reason: string;
}

/**
 * Result of an irreversibility classification.
 */
export interface IrreversibilityResult {
  /** The classification of the action */
  classification: IrreversibilityClass;
  /** Patterns that matched this action */
  matchedPatterns: string[];
  /** Required proof level for this action */
  requiredProofLevel: ProofLevel;
  /** Whether pre-commit simulation is required */
  requiresSimulation: boolean;
}

/**
 * Configuration for the AuthorityGate.
 */
export interface AuthorityGateConfig {
  /** Authority scopes to register (defaults provided if not specified) */
  scopes?: AuthorityScope[];
  /** Secret key for HMAC signing (generated if not provided) */
  signatureSecret?: string;
}

/**
 * Configuration for the IrreversibilityClassifier.
 */
export interface IrreversibilityClassifierConfig {
  /** Patterns for irreversible actions (regex strings) */
  irreversiblePatterns?: string[];
  /** Patterns for costly-reversible actions (regex strings) */
  costlyReversiblePatterns?: string[];
  /** Patterns for reversible actions (regex strings) */
  reversiblePatterns?: string[];
}

