/**
 * Create a CapabilityAlgebra instance
 */
export function createCapabilityAlgebra(): CapabilityAlgebra {
  return new CapabilityAlgebra();
}

/**
 * Coherence Scheduler & Economic Governor
 *
 * Detects drift in agent behavior and enforces resource budgets.
 *
 * CoherenceScheduler:
 * - Computes a coherence score from violation rate, rework, and intent drift
 * - Maps scores to privilege levels (full, restricted, read-only, suspended)
 * - Tracks score history and provides human-readable recommendations
 *
 * EconomicGovernor:
 * - Tracks token usage, tool calls, storage, and time
 * - Checks budgets and emits alerts when thresholds are crossed
 * - Estimates remaining capacity and costs
 *
 * @module @claude-flow/guidance/coherence
 */

import type { RunEvent, OptimizationMetrics } from './types.js';

// ============================================================================
// Coherence Types
// ============================================================================

/**
 * Coherence score computed from recent run metrics and events
 */
export interface CoherenceScore {
  /** Overall coherence (0-1, 1 = perfectly coherent) */
  overall: number;
  /** Violation component (0-1, lower violations = higher score) */
  violationComponent: number;
  /** Rework component (0-1, lower rework = higher score) */
  reworkComponent: number;
  /** Drift component (0-1, consistent intents = higher score) */
  driftComponent: number;
  /** Timestamp when this score was computed */
  timestamp: number;
  /** Number of events evaluated in the window */
  windowSize: number;
}

/**
 * Thresholds for privilege level determination
 */
export interface CoherenceThresholds {
  /** Below this overall score the agent is restricted to read-only */
  readOnlyThreshold: number;
  /** Below this overall score warnings are emitted */
  warningThreshold: number;
  /** Above this overall score the agent has full privileges */
  healthyThreshold: number;
  /** Above this overall score privilege escalation is allowed */
  privilegeEscalationThreshold: number;
}

/**
 * Privilege level derived from a coherence score
 */
export type PrivilegeLevel = 'full' | 'restricted' | 'read-only' | 'suspended';

// ============================================================================
// Economic Types
// ============================================================================

/**
 * Budget usage breakdown across all tracked dimensions
 */
export interface BudgetUsage {
  tokens: { used: number; limit: number; percentage: number };
  toolCalls: { used: number; limit: number; percentage: number };
  storage: { usedBytes: number; limitBytes: number; percentage: number };
  time: { usedMs: number; limitMs: number; percentage: number };
  cost: { totalUsd: number; limitUsd: number; percentage: number };
}

// ============================================================================
// Default Configurations
// ============================================================================

const DEFAULT_THRESHOLDS: CoherenceThresholds = {
  readOnlyThreshold: 0.3,
  warningThreshold: 0.5,
  healthyThreshold: 0.7,
  privilegeEscalationThreshold: 0.9,
};

const DEFAULT_ECONOMIC_CONFIG = {
  tokenLimit: 1_000_000,
  toolCallLimit: 10_000,
  storageLimit: 1_073_741_824, // 1 GiB
  timeLimit: 3_600_000, // 1 hour
  costPerToken: 0.000003, // $3 per million tokens
  costPerToolCall: 0.0001,
  costLimit: 10, // $10 USD
};

// ============================================================================
// Coherence Scheduler
// ============================================================================

export interface CoherenceSchedulerConfig {
  thresholds?: Partial<CoherenceThresholds>;
  windowSize?: number;
  checkIntervalMs?: number;
}

/**
 * Computes coherence scores from run metrics and events, determines privilege
 * levels, and provides recommendations when drift is detected.
 */
export class CoherenceScheduler {
  private readonly thresholds: CoherenceThresholds;
  private readonly windowSize: number;
  private readonly checkIntervalMs: number;
  private readonly scoreHistory: CoherenceScore[] = [];
  private static readonly MAX_HISTORY = 100;

  constructor(config: CoherenceSchedulerConfig = {}) {
    this.thresholds = { ...DEFAULT_THRESHOLDS, ...config.thresholds };
    this.windowSize = config.windowSize ?? 20;
    this.checkIntervalMs = config.checkIntervalMs ?? 30_000;
  }

  /**
   * Compute a coherence score from optimization metrics and recent events.
   *
   * Components:
   * - violationComponent: 1 - (violationRate / 10) clamped to [0, 1]
   * - reworkComponent: 1 - (reworkLines / 100) clamped to [0, 1]
   * - driftComponent: intent consistency (fewer unique intents relative to window = higher)
   * - overall: weighted average (0.4 * violation + 0.3 * rework + 0.3 * drift)
   */
  computeCoherence(
    metrics: OptimizationMetrics,
    recentEvents: RunEvent[],
  ): CoherenceScore {
    const window = recentEvents.slice(-this.windowSize);
    const windowLen = window.length;

    // Violation component: fewer violations per 10 tasks = better
    const violationComponent = clamp(1 - metrics.violationRate / 10, 0, 1);

    // Rework component: fewer rework lines on average = better
    const reworkComponent = clamp(1 - metrics.reworkLines / 100, 0, 1);

    // Drift component: consistent intents = better
    // A single unique intent across N events means perfect consistency
    let driftComponent: number;
    if (windowLen === 0) {
      driftComponent = 1; // No events, assume no drift
    } else {
      const uniqueIntents = new Set(window.map(e => e.intent)).size;
      // 1 unique intent / N events = score 1; N unique / N events = score approaches 0
      driftComponent = clamp(1 - (uniqueIntents - 1) / Math.max(windowLen - 1, 1), 0, 1);
    }

    const overall =
      0.4 * violationComponent +
      0.3 * reworkComponent +
      0.3 * driftComponent;

    const score: CoherenceScore = {
      overall,
      violationComponent,
      reworkComponent,
      driftComponent,
      timestamp: Date.now(),
      windowSize: windowLen,
    };

    this.scoreHistory.push(score);
    if (this.scoreHistory.length > CoherenceScheduler.MAX_HISTORY) {
      this.scoreHistory.shift();
    }

    return score;
  }

  /**
   * Determine the privilege level from a coherence score.
   *
   * - overall >= healthyThreshold (0.7): 'full'
   * - overall >= warningThreshold (0.5): 'restricted'
   * - overall >= readOnlyThreshold (0.3): 'read-only'
   * - below readOnlyThreshold: 'suspended'
   */
  getPrivilegeLevel(score: CoherenceScore): PrivilegeLevel {
    if (score.overall >= this.thresholds.healthyThreshold) {
      return 'full';
    }
    if (score.overall >= this.thresholds.warningThreshold) {
      return 'restricted';
    }
    if (score.overall >= this.thresholds.readOnlyThreshold) {
      return 'read-only';
    }
    return 'suspended';
  }

  /**
   * Return the last 100 coherence scores (most recent last).
   */
  getScoreHistory(): CoherenceScore[] {
    return [...this.scoreHistory];
  }

  /**
   * Whether the score indicates healthy coherence.
   */
  isHealthy(score: CoherenceScore): boolean {
    return score.overall >= this.thresholds.healthyThreshold;
  }

  /**
   * Whether the score indicates drift (below warning threshold).
   */
  isDrifting(score: CoherenceScore): boolean {
    return score.overall < this.thresholds.warningThreshold;
  }

  /**
   * Whether the score warrants restricting agent actions.
   */
  shouldRestrict(score: CoherenceScore): boolean {
    return score.overall < this.thresholds.warningThreshold;
  }

  /**
   * Produce a human-readable recommendation based on the coherence score.
   */
  getRecommendation(score: CoherenceScore): string {
    const level = this.getPrivilegeLevel(score);
    const parts: string[] = [];

    switch (level) {
      case 'full':
        parts.push(
          `Coherence is healthy at ${(score.overall * 100).toFixed(1)}%.`,
        );
        if (score.overall >= this.thresholds.privilegeEscalationThreshold) {
          parts.push('Privilege escalation is permitted.');
        }
        break;

      case 'restricted':
        parts.push(
          `Coherence is degraded at ${(score.overall * 100).toFixed(1)}%. Agent privileges are restricted.`,
        );
        break;

      case 'read-only':
        parts.push(
          `Coherence is critically low at ${(score.overall * 100).toFixed(1)}%. Agent is limited to read-only operations.`,
        );
        break;

      case 'suspended':
        parts.push(
          `Coherence has collapsed to ${(score.overall * 100).toFixed(1)}%. Agent operations are suspended.`,
        );
        break;
    }

    // Add component-specific advice
    if (score.violationComponent < 0.5) {
      parts.push(
        `High violation rate detected (component: ${(score.violationComponent * 100).toFixed(0)}%). Review and strengthen enforcement gates.`,
      );
    }
    if (score.reworkComponent < 0.5) {
      parts.push(
        `Excessive rework detected (component: ${(score.reworkComponent * 100).toFixed(0)}%). Consider more prescriptive guidance or smaller task scopes.`,
      );
    }
    if (score.driftComponent < 0.5) {
      parts.push(
        `Intent drift detected (component: ${(score.driftComponent * 100).toFixed(0)}%). Agent is switching between too many task types. Focus on a single objective.`,
      );
    }

    return parts.join(' ');
  }

  /**
   * Get the configured check interval in milliseconds.
   */
  get interval(): number {
    return this.checkIntervalMs;
  }

  /**
   * Get the configured thresholds.
   */
  getThresholds(): CoherenceThresholds {
    return { ...this.thresholds };
  }
}

// ============================================================================
// Economic Governor
// ============================================================================

export interface EconomicGovernorConfig {
  tokenLimit?: number;
  toolCallLimit?: number;
  storageLimit?: number;
  timeLimit?: number;
  costPerToken?: number;
  costPerToolCall?: number;
  costLimit?: number;
}

interface ToolCallRecord {
  toolName: string;
  durationMs: number;
  timestamp: number;
}

/**
 * Tracks resource consumption (tokens, tool calls, storage, time, cost)
 * and enforces budget limits with alerts.
 */
export class EconomicGovernor {
  private readonly config: Required<EconomicGovernorConfig>;
  private tokensUsed = 0;
  private toolCallsUsed = 0;
  private storageUsed = 0;
  private readonly toolCallLog: ToolCallRecord[] = [];
  private readonly startTime: number;
  private periodStart: number;

  private static readonly ALERT_THRESHOLDS = [0.75, 0.9, 0.95, 1.0];

  constructor(config: EconomicGovernorConfig = {}) {
    this.config = {
      tokenLimit: config.tokenLimit ?? DEFAULT_ECONOMIC_CONFIG.tokenLimit,
      toolCallLimit: config.toolCallLimit ?? DEFAULT_ECONOMIC_CONFIG.toolCallLimit,
      storageLimit: config.storageLimit ?? DEFAULT_ECONOMIC_CONFIG.storageLimit,
      timeLimit: config.timeLimit ?? DEFAULT_ECONOMIC_CONFIG.timeLimit,
      costPerToken: config.costPerToken ?? DEFAULT_ECONOMIC_CONFIG.costPerToken,
      costPerToolCall: config.costPerToolCall ?? DEFAULT_ECONOMIC_CONFIG.costPerToolCall,
      costLimit: config.costLimit ?? DEFAULT_ECONOMIC_CONFIG.costLimit,
    };

    this.startTime = Date.now();
    this.periodStart = Date.now();
  }

  /**
   * Record token consumption.
   */
  recordTokenUsage(count: number): void {
    this.tokensUsed += count;
  }

  /**
   * Record a tool call with its name and duration.
   */
  recordToolCall(toolName: string, durationMs: number): void {
    this.toolCallsUsed++;
    this.toolCallLog.push({
      toolName,
      durationMs,
      timestamp: Date.now(),
    });
  }

  /**
   * Record storage usage in bytes.
   */
  recordStorageUsage(bytes: number): void {
    this.storageUsed += bytes;
  }

  /**
   * Check whether current usage is within budget limits.
   * Returns a summary with alerts for any limits that are near or exceeded.
   */
  checkBudget(): { withinBudget: boolean; usage: BudgetUsage; alerts: string[] } {
    const usage = this.getUsageSummary();
    const alerts: string[] = [];

    // Check each dimension against alert thresholds
    const dimensions: Array<{ name: string; percentage: number }> = [
      { name: 'tokens', percentage: usage.tokens.percentage },
      { name: 'tool calls', percentage: usage.toolCalls.percentage },
      { name: 'storage', percentage: usage.storage.percentage },
      { name: 'time', percentage: usage.time.percentage },
      { name: 'cost', percentage: usage.cost.percentage },
    ];

    let withinBudget = true;

    for (const dim of dimensions) {
      if (dim.percentage >= 100) {
        alerts.push(`BUDGET EXCEEDED: ${dim.name} at ${dim.percentage.toFixed(1)}% of limit`);
        withinBudget = false;
      } else if (dim.percentage >= 95) {
        alerts.push(`CRITICAL: ${dim.name} at ${dim.percentage.toFixed(1)}% of limit`);
      } else if (dim.percentage >= 90) {
        alerts.push(`WARNING: ${dim.name} at ${dim.percentage.toFixed(1)}% of limit`);
      } else if (dim.percentage >= 75) {
        alerts.push(`NOTICE: ${dim.name} at ${dim.percentage.toFixed(1)}% of limit`);
      }
    }

    return { withinBudget, usage, alerts };
  }

  /**
   * Get a full usage summary across all tracked dimensions.
   */
  getUsageSummary(): BudgetUsage {
    const elapsedMs = Date.now() - this.periodStart;
    const costEstimate = this.getCostEstimate();

    return {
      tokens: {
        used: this.tokensUsed,
        limit: this.config.tokenLimit,
        percentage: safePercentage(this.tokensUsed, this.config.tokenLimit),
      },
      toolCalls: {
        used: this.toolCallsUsed,
        limit: this.config.toolCallLimit,
        percentage: safePercentage(this.toolCallsUsed, this.config.toolCallLimit),
      },
      storage: {
        usedBytes: this.storageUsed,
        limitBytes: this.config.storageLimit,
        percentage: safePercentage(this.storageUsed, this.config.storageLimit),
      },
      time: {
        usedMs: elapsedMs,
        limitMs: this.config.timeLimit,
        percentage: safePercentage(elapsedMs, this.config.timeLimit),
      },
      cost: {
        totalUsd: costEstimate.totalCost,
        limitUsd: this.config.costLimit,
        percentage: safePercentage(costEstimate.totalCost, this.config.costLimit),
      },
    };
  }

  /**
   * Reset all counters for a new billing/tracking period.
   */
  resetPeriod(): void {
    this.tokensUsed = 0;
    this.toolCallsUsed = 0;
    this.storageUsed = 0;
    this.toolCallLog.length = 0;
    this.periodStart = Date.now();
  }

  /**
   * Estimate remaining capacity before hitting limits.
   */
  estimateRemainingCapacity(): {
    tokensRemaining: number;
    callsRemaining: number;
    timeRemainingMs: number;
  } {
    const elapsedMs = Date.now() - this.periodStart;

    return {
      tokensRemaining: Math.max(0, this.config.tokenLimit - this.tokensUsed),
      callsRemaining: Math.max(0, this.config.toolCallLimit - this.toolCallsUsed),
      timeRemainingMs: Math.max(0, this.config.timeLimit - elapsedMs),
    };
  }

  /**
   * Compute a cost estimate with a breakdown by category.
   */
  getCostEstimate(): { totalCost: number; breakdown: Record<string, number> } {
    const tokenCost = this.tokensUsed * this.config.costPerToken;
    const toolCallCost = this.toolCallsUsed * this.config.costPerToolCall;

    const breakdown: Record<string, number> = {
      tokens: tokenCost,
      toolCalls: toolCallCost,
    };

    return {
      totalCost: tokenCost + toolCallCost,
      breakdown,
    };
  }

  /**
   * Get the raw tool call log.
   */
  getToolCallLog(): ReadonlyArray<ToolCallRecord> {
    return this.toolCallLog;
  }
}

// ============================================================================
// Factory Functions
// ============================================================================

/**
 * Create a CoherenceScheduler with optional configuration.
 */
export function createCoherenceScheduler(
  config?: CoherenceSchedulerConfig,
): CoherenceScheduler {
  return new CoherenceScheduler(config);
}

/**
 * Create an EconomicGovernor with optional configuration.
 */
export function createEconomicGovernor(
  config?: EconomicGovernorConfig,
): EconomicGovernor {
  return new EconomicGovernor(config);
}

// ============================================================================
// Helpers
// ============================================================================

function clamp(value: number, min: number, max: number): number {
  return Math.min(max, Math.max(min, value));
}

function safePercentage(used: number, limit: number): number {
  if (limit <= 0) return 0;
  return (used / limit) * 100;
}

/**
 * Guidance Compiler
 *
 * Parses root CLAUDE.md and optional CLAUDE.local.md into a compiled policy bundle:
 * 1. A small always-loaded constitution (first 30-60 lines of invariants)
 * 2. A set of task-scoped rule shards tagged by intent, risk, domain, repo path, tool class
 * 3. A machine-readable manifest with rule IDs, triggers, and verifiers
 *
 * @module @claude-flow/guidance/compiler
 */

import { createHash } from 'node:crypto';
import type {
  GuidanceRule,
  RuleShard,
  Constitution,
  RuleManifest,
  PolicyBundle,
  RiskClass,
  ToolClass,
  TaskIntent,
} from './types.js';

// ============================================================================
// Parser Patterns
// ============================================================================

/** Matches a rule declaration: "R001:" or "RULE-001:" or "[R001]" or "- [R001]" */
const RULE_ID_PATTERN = /^(?:#{1,4}\s+)?(?:[-*]\s+)?\[?([A-Z]+-?\d{3,4})\]?[:\s]/;

/** Matches risk class annotations: "(critical)", "[high-risk]", etc. */
const RISK_PATTERN = /\(?(critical|high|medium|low|info)(?:-risk)?\)?/i;

/** Matches domain tags: @security, @testing, etc. */
const DOMAIN_TAG_PATTERN = /@(security|testing|performance|architecture|debugging|deployment|general)/gi;

/** Matches tool class tags: [edit], [bash], etc. */
const TOOL_TAG_PATTERN = /\[(edit|bash|read|write|mcp|task|all)\]/gi;

/** Matches intent tags: #bug-fix, #feature, etc. */
const INTENT_TAG_PATTERN = /#(bug-fix|feature|refactor|security|performance|testing|docs|deployment|architecture|debug|general)/gi;

/** Matches repo scope: scope:src/**, scope:tests/**, etc. */
const SCOPE_PATTERN = /scope:([\w\/\*\.\-]+)/gi;

/** Matches verifier annotations: verify:tests-pass, verify:lint-clean */
const VERIFIER_PATTERN = /verify:([\w\-]+)/i;

/** Matches priority override: priority:N */
const PRIORITY_PATTERN = /priority:(\d+)/i;

/** Section markers for constitution identification */
const CONSTITUTION_MARKERS = [
  /^#+\s*(safety|security|invariant|constitution|critical|non[- ]?negotiable|always)/i,
  /^#+\s*(must|never|always|required|mandatory)/i,
];

/** Section markers for shard boundaries */
const SHARD_MARKERS = [
  /^#+\s/,         // Any heading
  /^---+\s*$/,     // Horizontal rule
  /^\*\*\*+\s*$/,  // Bold horizontal rule
];

// ============================================================================
// Compiler Configuration
// ============================================================================

export interface CompilerConfig {
  /** Maximum lines for constitution */
  maxConstitutionLines: number;
  /** Default risk class */
  defaultRiskClass: RiskClass;
  /** Default priority */
  defaultPriority: number;
  /** Auto-generate rule IDs for untagged rules */
  autoGenerateIds: boolean;
}

const DEFAULT_CONFIG: CompilerConfig = {
  maxConstitutionLines: 60,
  defaultRiskClass: 'medium',
  defaultPriority: 50,
  autoGenerateIds: true,
};

// ============================================================================
// Guidance Compiler
// ============================================================================

export class GuidanceCompiler {
  private config: CompilerConfig;
  private nextAutoId = 1;

  constructor(config: Partial<CompilerConfig> = {}) {
    this.config = { ...DEFAULT_CONFIG, ...config };
  }

  /**
   * Compile guidance files into a policy bundle
   */
  compile(rootContent: string, localContent?: string): PolicyBundle {
    // Parse both files into raw rules
    const rootRules = this.parseGuidanceFile(rootContent, 'root');
    const localRules = localContent
      ? this.parseGuidanceFile(localContent, 'local')
      : [];

    // Merge rules (local overrides root for same ID)
    const allRules = this.mergeRules(rootRules, localRules);

    // Split into constitution and shards
    const constitutionRules = allRules.filter(r => r.isConstitution);
    const shardRules = allRules.filter(r => !r.isConstitution);

    // Build constitution
    const constitution = this.buildConstitution(constitutionRules);

    // Build shards
    const shards = this.buildShards(shardRules);

    // Build manifest
    const manifest = this.buildManifest(allRules, rootContent, localContent);

    return { constitution, shards, manifest };
  }

  /**
   * Parse a guidance markdown file into rules
   */
  parseGuidanceFile(content: string, source: 'root' | 'local'): GuidanceRule[] {
    const rules: GuidanceRule[] = [];
    const lines = content.split('\n');

    let currentSection = '';
    let currentBlock: string[] = [];
    let inConstitutionSection = false;
    let blockStartLine = 0;

    for (let i = 0; i < lines.length; i++) {
      const line = lines[i];

      // Detect section boundaries
      if (SHARD_MARKERS.some(m => m.test(line))) {
        // Flush current block
        if (currentBlock.length > 0) {
          const blockRules = this.extractRulesFromBlock(
            currentBlock.join('\n'),
            source,
            inConstitutionSection,
            currentSection
          );
          rules.push(...blockRules);
          currentBlock = [];
        }

        // Check if this is a constitution section
        inConstitutionSection = CONSTITUTION_MARKERS.some(m => m.test(line));
        currentSection = line.replace(/^#+\s*/, '').trim();
        blockStartLine = i;
      }

      currentBlock.push(line);
    }

    // Flush last block
    if (currentBlock.length > 0) {
      const blockRules = this.extractRulesFromBlock(
        currentBlock.join('\n'),
        source,
        inConstitutionSection,
        currentSection
      );
      rules.push(...blockRules);
    }

    return rules;
  }

  /**
   * Extract rules from a content block
   */
  private extractRulesFromBlock(
    block: string,
    source: 'root' | 'local',
    isConstitution: boolean,
    section: string
  ): GuidanceRule[] {
    const rules: GuidanceRule[] = [];
    const lines = block.split('\n');

    // Try to extract explicit rules (with IDs)
    let ruleBuffer: string[] = [];
    let currentRuleId: string | null = null;

    for (const line of lines) {
      const idMatch = line.match(RULE_ID_PATTERN);

      if (idMatch) {
        // Flush previous rule
        if (currentRuleId && ruleBuffer.length > 0) {
          rules.push(this.parseRule(currentRuleId, ruleBuffer.join('\n'), source, isConstitution));
          ruleBuffer = [];
        }
        currentRuleId = idMatch[1];
        ruleBuffer.push(line.replace(RULE_ID_PATTERN, '').trim());
      } else if (currentRuleId) {
        ruleBuffer.push(line);
      }
    }

    // Flush last rule
    if (currentRuleId && ruleBuffer.length > 0) {
      rules.push(this.parseRule(currentRuleId, ruleBuffer.join('\n'), source, isConstitution));
    }

    // If no explicit rules found, try to extract implicit rules from bullet points
    if (rules.length === 0) {
      const implicitRules = this.extractImplicitRules(block, source, isConstitution, section);
      rules.push(...implicitRules);
    }

    return rules;
  }

  /**
   * Extract implicit rules from bullet points and paragraphs
   */
  private extractImplicitRules(
    block: string,
    source: 'root' | 'local',
    isConstitution: boolean,
    section: string
  ): GuidanceRule[] {
    const rules: GuidanceRule[] = [];
    const lines = block.split('\n');

    for (const line of lines) {
      const trimmed = line.trim();

      // Skip empty lines, headings, and non-actionable content
      if (!trimmed || /^#+\s/.test(trimmed) || /^---/.test(trimmed)) continue;

      // Match actionable bullet points
      const bulletMatch = trimmed.match(/^[-*]\s+(.+)/);
      if (!bulletMatch) continue;

      const text = bulletMatch[1].trim();

      // Only create rules for actionable statements
      if (!this.isActionableRule(text)) continue;

      // Auto-generate ID if enabled
      if (this.config.autoGenerateIds) {
        const id = `AUTO-${String(this.nextAutoId++).padStart(3, '0')}`;
        rules.push(this.parseRule(id, text, source, isConstitution));
      }
    }

    return rules;
  }

  /**
   * Check if text represents an actionable rule
   */
  private isActionableRule(text: string): boolean {
    const actionPatterns = [
      /\b(must|never|always|should|require|forbid|ensure|validate|check|verify)\b/i,
      /\b(do not|don't|cannot|can't|avoid|prevent|block|deny|reject)\b/i,
      /\b(use|prefer|apply|follow|implement|enforce|maintain|keep|run|include|write|mock|respect)\b/i,
    ];

    return actionPatterns.some(p => p.test(text));
  }

  /**
   * Parse a single rule from its text content
   */
  private parseRule(
    id: string,
    text: string,
    source: 'root' | 'local',
    isConstitution: boolean
  ): GuidanceRule {
    const now = Date.now();

    // Extract risk class
    const riskMatch = text.match(RISK_PATTERN);
    const riskClass = (riskMatch?.[1]?.toLowerCase() as RiskClass) ?? this.config.defaultRiskClass;

    // Phase 1 perf — replace 4 `new RegExp(PATTERN.source, 'gi')` calls per
    // parseRule with `text.matchAll(PATTERN)` against the existing
    // module-level global regex. On a 500-rule file that previously meant
    // 2,000 RegExp constructions per compile; matchAll is allocation-free
    // per call and the module-level pattern is constructed exactly once.
    const toolClasses: ToolClass[] = [];
    for (const m of text.matchAll(TOOL_TAG_PATTERN)) {
      toolClasses.push(m[1].toLowerCase() as ToolClass);
    }
    if (toolClasses.length === 0) toolClasses.push('all');

    const intents: TaskIntent[] = [];
    for (const m of text.matchAll(INTENT_TAG_PATTERN)) {
      intents.push(m[1].toLowerCase() as TaskIntent);
    }
    if (intents.length === 0) intents.push(...this.inferIntents(text));

    const domains: string[] = [];
    for (const m of text.matchAll(DOMAIN_TAG_PATTERN)) {
      domains.push(m[1].toLowerCase());
    }
    if (domains.length === 0) domains.push(...this.inferDomains(text));

    const repoScopes: string[] = [];
    for (const m of text.matchAll(SCOPE_PATTERN)) {
      repoScopes.push(m[1]);
    }
    if (repoScopes.length === 0) repoScopes.push('**/*');

    // Extract verifier
    const verifierMatch = text.match(VERIFIER_PATTERN);
    const verifier = verifierMatch?.[1];

    // Extract priority
    const priorityMatch = text.match(PRIORITY_PATTERN);
    const priority = priorityMatch ? parseInt(priorityMatch[1], 10) : this.config.defaultPriority;

    // Clean rule text (remove annotations)
    const cleanText = text
      .replace(RISK_PATTERN, '')
      .replace(TOOL_TAG_PATTERN, '')
      .replace(INTENT_TAG_PATTERN, '')
      .replace(DOMAIN_TAG_PATTERN, '')
      .replace(SCOPE_PATTERN, '')
      .replace(VERIFIER_PATTERN, '')
      .replace(PRIORITY_PATTERN, '')
      .replace(/\s+/g, ' ')
      .trim();

    return {
      id,
      text: cleanText,
      riskClass,
      toolClasses,
      intents,
      repoScopes,
      domains,
      priority: isConstitution ? priority + 100 : priority,
      source,
      isConstitution,
      verifier,
      createdAt: now,
      updatedAt: now,
    };
  }

  /**
   * Infer intents from rule text
   */
  private inferIntents(text: string): TaskIntent[] {
    const intents: TaskIntent[] = [];
    const lower = text.toLowerCase();

    if (/secur|auth|secret|password|token|cve|vuln|encrypt/i.test(lower)) intents.push('security');
    if (/test|spec|mock|coverage|assert|tdd/i.test(lower)) intents.push('testing');
    if (/perf|optim|fast|slow|cache|memory|speed/i.test(lower)) intents.push('performance');
    if (/refactor|clean|restructur|simplif/i.test(lower)) intents.push('refactor');
    if (/bug|fix|error|broken|fail|debug/i.test(lower)) intents.push('bug-fix');
    if (/architect|design|pattern|structure|boundary/i.test(lower)) intents.push('architecture');
    if (/deploy|release|publish|ci|cd/i.test(lower)) intents.push('deployment');
    if (/doc|readme|comment|jsdoc/i.test(lower)) intents.push('docs');

    return intents.length > 0 ? intents : ['general'];
  }

  /**
   * Infer domains from rule text
   */
  private inferDomains(text: string): string[] {
    const domains: string[] = [];
    const lower = text.toLowerCase();

    if (/secur|auth|secret|password|token|cve|vuln/i.test(lower)) domains.push('security');
    if (/test|spec|mock|coverage|assert/i.test(lower)) domains.push('testing');
    if (/perf|optim|fast|slow|cache|speed/i.test(lower)) domains.push('performance');
    if (/architect|design|ddd|domain|boundary/i.test(lower)) domains.push('architecture');
    if (/bug|fix|error|debug/i.test(lower)) domains.push('debugging');

    return domains.length > 0 ? domains : ['general'];
  }

  /**
   * Merge root and local rules, local overrides root for same ID
   */
  private mergeRules(rootRules: GuidanceRule[], localRules: GuidanceRule[]): GuidanceRule[] {
    const ruleMap = new Map<string, GuidanceRule>();

    for (const rule of rootRules) {
      ruleMap.set(rule.id, rule);
    }

    for (const rule of localRules) {
      if (ruleMap.has(rule.id)) {
        // Local overrides root, but mark as updated
        const existing = ruleMap.get(rule.id)!;
        ruleMap.set(rule.id, {
          ...rule,
          priority: Math.max(rule.priority, existing.priority),
          updatedAt: Date.now(),
        });
      } else {
        ruleMap.set(rule.id, rule);
      }
    }

    return Array.from(ruleMap.values()).sort((a, b) => b.priority - a.priority);
  }

  /**
   * Build the constitution from constitution-class rules
   */
  private buildConstitution(rules: GuidanceRule[]): Constitution {
    // Sort by priority descending
    const sorted = [...rules].sort((a, b) => b.priority - a.priority);

    // Build compact text
    const lines: string[] = [
      '# Constitution - Always Active Rules',
      '',
    ];

    let currentDomain = '';
    for (const rule of sorted) {
      const domain = rule.domains[0] || 'general';
      if (domain !== currentDomain) {
        currentDomain = domain;
        lines.push(`## ${domain.charAt(0).toUpperCase() + domain.slice(1)}`);
      }
      lines.push(`- [${rule.id}] ${rule.text}`);
    }

    // Trim to max lines
    const text = lines.slice(0, this.config.maxConstitutionLines).join('\n');

    return {
      rules: sorted,
      text,
      hash: this.hashContent(text),
    };
  }

  /**
   * Build shards from non-constitution rules
   */
  private buildShards(rules: GuidanceRule[]): RuleShard[] {
    return rules.map(rule => ({
      rule,
      compactText: this.buildCompactShardText(rule),
    }));
  }

  /**
   * Build compact text for a shard
   */
  private buildCompactShardText(rule: GuidanceRule): string {
    const tags = [
      rule.riskClass,
      ...rule.domains,
      ...rule.intents,
      ...rule.toolClasses.filter(t => t !== 'all'),
    ].map(t => `@${t}`).join(' ');

    return `[${rule.id}] ${rule.text} ${tags}`.trim();
  }

  /**
   * Build the manifest
   */
  private buildManifest(
    allRules: GuidanceRule[],
    rootContent: string,
    localContent?: string
  ): RuleManifest {
    const sourceHashes: Record<string, string> = {
      root: this.hashContent(rootContent),
    };
    if (localContent) {
      sourceHashes.local = this.hashContent(localContent);
    }

    return {
      rules: allRules.map(r => ({
        id: r.id,
        triggers: [...r.intents, ...r.domains, ...r.toolClasses],
        verifier: r.verifier ?? null,
        riskClass: r.riskClass,
        priority: r.priority,
        source: r.source,
      })),
      compiledAt: Date.now(),
      sourceHashes,
      totalRules: allRules.length,
      constitutionRules: allRules.filter(r => r.isConstitution).length,
      shardRules: allRules.filter(r => !r.isConstitution).length,
    };
  }

  /**
   * Hash content for change detection
   */
  private hashContent(content: string): string {
    return createHash('sha256').update(content).digest('hex').slice(0, 16);
  }
}

/**
 * Create a compiler instance
 */
export function createCompiler(config?: Partial<CompilerConfig>): GuidanceCompiler {
  return new GuidanceCompiler(config);
}

/**
 * Agent Cell Conformance Kit
 *
 * Canonical acceptance test proving the entire guidance control plane works
 * end-to-end. Implements the "Memory Clerk" agent cell pattern:
 *
 * 1. Read 20 memory entries (knowledge retrieval)
 * 2. Run 1 model inference (reasoning)
 * 3. Propose 5 memory writes based on inference
 * 4. Inject a coherence drop at write #3
 * 5. Verify the system switches to read-only and blocks remaining writes
 * 6. Emit a signed proof envelope
 * 7. Return a complete, replayable trace
 *
 * @module @claude-flow/guidance/conformance-kit
 */

import { createHash, randomUUID } from 'node:crypto';
import {
  MemoryWriteGate,
  createMemoryWriteGate,
  createMemoryEntry,
} from './memory-gate.js';
import type { MemoryAuthority, MemoryEntry } from './memory-gate.js';
import { ProofChain, createProofChain } from './proof.js';
import type { MemoryOperation } from './proof.js';
import { RunLedger, createLedger } from './ledger.js';
import {
  CoherenceScheduler,
  createCoherenceScheduler,
  EconomicGovernor,
  createEconomicGovernor,
} from './coherence.js';
import type { PrivilegeLevel } from './coherence.js';
import { DeterministicToolGateway, createToolGateway } from './gateway.js';

// ============================================================================
// Trace Event
// ============================================================================

/**
 * A single event in the agent cell execution trace.
 */
export interface TraceEvent {
  /** Monotonically increasing sequence number starting at 0 */
  seq: number;
  /** Epoch-ms timestamp when the event was recorded */
  ts: number;
  /** Event classification */
  type:
    | 'memory_read'
    | 'memory_write_proposed'
    | 'memory_write_committed'
    | 'memory_write_blocked'
    | 'model_infer'
    | 'tool_invoke'
    | 'coherence_check'
    | 'privilege_change'
    | 'run_start'
    | 'run_end';
  /** Arbitrary structured data describing the event */
  payload: Record<string, unknown>;
  /** Human-readable decision string for replay verification */
  decision: string;
  /** Snapshot of budget counters at event time */
  budgetSnapshot: Record<string, number>;
}

// ============================================================================
// Cell Run Result
// ============================================================================

/**
 * Complete result of an agent cell run including the full trace,
 * memory operation counts, proof hash, and budget usage.
 */
export interface CellRunResult {
  cellId: string;
  runId: string;
  traceEvents: TraceEvent[];
  memoryReads: number;
  memoryWritesAttempted: number;
  memoryWritesCommitted: number;
  memoryWritesBlocked: number;
  proofEnvelopeHash: string;
  coherenceHistory: number[];
  budgetUsage: Record<string, number>;
  outcome: 'completed' | 'restricted' | 'suspended';
}

// ============================================================================
// Cell Runtime Interface
// ============================================================================

/**
 * Runtime services provided to an agent cell.
 */
export interface CellRuntime {
  readMemory(key: string, namespace: string): unknown;
  writeMemory(
    key: string,
    namespace: string,
    value: unknown,
    evidence?: Record<string, unknown>,
  ): { allowed: boolean; reason: string };
  invokeModel(prompt: string): string;
  invokeTool(
    name: string,
    params: Record<string, unknown>,
  ): { result: unknown; allowed: boolean };
  getCoherenceScore(): number;
  setCoherenceScore(score: number): void;
  getProofChain(): ProofChain;
  getLedger(): RunLedger;
}

// ============================================================================
// Agent Cell Interface
// ============================================================================

/**
 * An agent cell is a self-contained unit of work that executes against
 * a CellRuntime, producing a fully traced CellRunResult.
 */
export interface AgentCell {
  cellId: string;
  name: string;
  run(runtime: CellRuntime): CellRunResult;
}

// ============================================================================
// Simulated Runtime Configuration
// ============================================================================

export interface SimulatedRuntimeConfig {
  memoryGate: MemoryWriteGate;
  proofChain: ProofChain;
  ledger: RunLedger;
  coherenceScheduler: CoherenceScheduler;
  economicGovernor: EconomicGovernor;
  toolGateway?: DeterministicToolGateway;
  authority: MemoryAuthority;
  initialCoherenceScore?: number;
  initialMemory?: Map<string, { namespace: string; value: unknown }>;
}

// ============================================================================
// Simulated Runtime
// ============================================================================

/**
 * A test runtime that wires together all guidance control plane components
 * and records every operation as a TraceEvent.
 */
export class SimulatedRuntime implements CellRuntime {
  private readonly memoryGate: MemoryWriteGate;
  private readonly proofChain: ProofChain;
  private readonly ledger: RunLedger;
  private readonly coherenceScheduler: CoherenceScheduler;
  private readonly economicGovernor: EconomicGovernor;
  private readonly toolGateway: DeterministicToolGateway;
  private readonly authority: MemoryAuthority;

  private coherenceScore: number;
  private readonly memoryStore = new Map<
    string,
    { namespace: string; value: unknown }
  >();
  private readonly memoryEntries: MemoryEntry[] = [];
  private readonly traceEvents: TraceEvent[] = [];
  private readonly coherenceHistory: number[] = [];
  private seq = 0;

  private memoryReadCount = 0;
  private memoryWritesAttemptedCount = 0;
  private memoryWritesCommittedCount = 0;
  private memoryWritesBlockedCount = 0;
  private readonly memoryOps: MemoryOperation[] = [];

  constructor(config: SimulatedRuntimeConfig) {
    this.memoryGate = config.memoryGate;
    this.proofChain = config.proofChain;
    this.ledger = config.ledger;
    this.coherenceScheduler = config.coherenceScheduler;
    this.economicGovernor = config.economicGovernor;
    this.toolGateway = config.toolGateway ?? createToolGateway();
    this.authority = config.authority;
    this.coherenceScore = config.initialCoherenceScore ?? 0.9;

    if (config.initialMemory) {
      for (const [key, entry] of config.initialMemory) {
        this.memoryStore.set(`${entry.namespace}:${key}`, entry);
      }
    }
  }

  // =========================================================================
  // CellRuntime implementation
  // =========================================================================

  readMemory(key: string, namespace: string): unknown {
    this.memoryReadCount++;
    const storeKey = `${namespace}:${key}`;
    const entry = this.memoryStore.get(storeKey);
    const value = entry?.value ?? null;

    const valueHash = createHash('sha256')
      .update(JSON.stringify(value))
      .digest('hex');

    this.memoryOps.push({
      key,
      namespace,
      operation: 'read',
      valueHash,
      timestamp: Date.now(),
    });

    this.emitTrace(
      'memory_read',
      { key, namespace, found: entry !== undefined },
      'read_allowed',
    );

    this.economicGovernor.recordToolCall('memory_read', 1);

    return value;
  }

  writeMemory(
    key: string,
    namespace: string,
    value: unknown,
    evidence?: Record<string, unknown>,
  ): { allowed: boolean; reason: string } {
    this.memoryWritesAttemptedCount++;

    // Emit proposal trace
    this.emitTrace(
      'memory_write_proposed',
      {
        key,
        namespace,
        valuePreview:
          typeof value === 'string' ? value.slice(0, 100) : typeof value,
        evidence: evidence ?? {},
      },
      'proposed',
    );

    // Check coherence before allowing the write
    const privilegeLevel = this.resolvePrivilegeLevel(this.coherenceScore);
    this.emitTrace(
      'coherence_check',
      { score: this.coherenceScore, privilegeLevel },
      privilegeLevel,
    );

    if (privilegeLevel === 'read-only' || privilegeLevel === 'suspended') {
      this.memoryWritesBlockedCount++;
      const reason = `Write blocked: privilege level is "${privilegeLevel}" (coherence: ${this.coherenceScore.toFixed(3)})`;

      this.emitTrace(
        'memory_write_blocked',
        {
          key,
          namespace,
          privilegeLevel,
          coherenceScore: this.coherenceScore,
        },
        'blocked_coherence',
      );

      return { allowed: false, reason };
    }

    // Evaluate through the MemoryWriteGate
    const decision = this.memoryGate.evaluateWrite(
      this.authority,
      key,
      namespace,
      value,
      this.memoryEntries,
    );

    if (!decision.allowed) {
      this.memoryWritesBlockedCount++;
      this.emitTrace(
        'memory_write_blocked',
        { key, namespace, gateReason: decision.reason },
        'blocked_gate',
      );

      return { allowed: false, reason: decision.reason };
    }

    // Commit the write
    this.memoryWritesCommittedCount++;
    const storeKey = `${namespace}:${key}`;
    this.memoryStore.set(storeKey, { namespace, value });

    const entry = createMemoryEntry(key, namespace, value, this.authority);
    this.memoryEntries.push(entry);

    const valueHash = createHash('sha256')
      .update(JSON.stringify(value))
      .digest('hex');

    this.memoryOps.push({
      key,
      namespace,
      operation: 'write',
      valueHash,
      timestamp: Date.now(),
    });

    this.emitTrace(
      'memory_write_committed',
      { key, namespace, valueHash },
      'committed',
    );

    this.economicGovernor.recordToolCall('memory_write', 2);
    this.economicGovernor.recordStorageUsage(
      Buffer.byteLength(JSON.stringify(value), 'utf-8'),
    );

    return { allowed: true, reason: 'Write committed' };
  }

  invokeModel(prompt: string): string {
    const tokens = Math.ceil(prompt.length / 4) + 50;
    this.economicGovernor.recordTokenUsage(tokens);

    const response = `[Simulated inference for: ${prompt.slice(0, 50)}...]`;

    this.emitTrace(
      'model_infer',
      {
        promptLength: prompt.length,
        responseLength: response.length,
        tokensEstimated: tokens,
      },
      'inference_complete',
    );

    return response;
  }

  invokeTool(
    name: string,
    params: Record<string, unknown>,
  ): { result: unknown; allowed: boolean } {
    const decision = this.toolGateway.evaluate(name, params);

    this.emitTrace(
      'tool_invoke',
      {
        toolName: name,
        params,
        allowed: decision.allowed,
        gate: decision.gate,
      },
      decision.allowed ? 'allowed' : 'blocked',
    );

    if (!decision.allowed) {
      return { result: null, allowed: false };
    }

    const result = { status: 'ok', tool: name };
    this.toolGateway.recordCall(name, params, result, 10);
    this.economicGovernor.recordToolCall(name, 10);

    return { result, allowed: true };
  }

  getCoherenceScore(): number {
    return this.coherenceScore;
  }

  setCoherenceScore(score: number): void {
    const previousScore = this.coherenceScore;
    this.coherenceScore = score;
    this.coherenceHistory.push(score);

    const previousLevel = this.resolvePrivilegeLevel(previousScore);
    const newLevel = this.resolvePrivilegeLevel(score);

    if (previousLevel !== newLevel) {
      this.emitTrace(
        'privilege_change',
        { previousScore, newScore: score, previousLevel, newLevel },
        `${previousLevel}->${newLevel}`,
      );
    }
  }

  getProofChain(): ProofChain {
    return this.proofChain;
  }

  getLedger(): RunLedger {
    return this.ledger;
  }

  // =========================================================================
  // Public trace emission (used by cells for run_start / run_end)
  // =========================================================================

  /**
   * Emit a custom trace event. Exposed so agent cells can record
   * lifecycle events (run_start, run_end) through the same trace stream.
   */
  emitCustomTrace(
    type: TraceEvent['type'],
    payload: Record<string, unknown>,
    decision: string,
  ): void {
    this.emitTrace(type, payload, decision);
  }

  // =========================================================================
  // Accessors for test inspection
  // =========================================================================

  getTraceEvents(): TraceEvent[] {
    return [...this.traceEvents];
  }

  getCoherenceHistory(): number[] {
    return [...this.coherenceHistory];
  }

  getMemoryReads(): number {
    return this.memoryReadCount;
  }

  getMemoryWritesAttempted(): number {
    return this.memoryWritesAttemptedCount;
  }

  getMemoryWritesCommitted(): number {
    return this.memoryWritesCommittedCount;
  }

  getMemoryWritesBlocked(): number {
    return this.memoryWritesBlockedCount;
  }

  getMemoryOps(): MemoryOperation[] {
    return [...this.memoryOps];
  }

  getBudgetUsage(): Record<string, number> {
    const usage = this.economicGovernor.getUsageSummary();
    return {
      tokens: usage.tokens.used,
      toolCalls: usage.toolCalls.used,
      storageBytes: usage.storage.usedBytes,
      timeMs: usage.time.usedMs,
      costUsd: usage.cost.totalUsd,
    };
  }

  // =========================================================================
  // Private helpers
  // =========================================================================

  private resolvePrivilegeLevel(score: number): PrivilegeLevel {
    const thresholds = this.coherenceScheduler.getThresholds();
    if (score >= thresholds.healthyThreshold) return 'full';
    if (score >= thresholds.warningThreshold) return 'restricted';
    if (score >= thresholds.readOnlyThreshold) return 'read-only';
    return 'suspended';
  }

  private emitTrace(
    type: TraceEvent['type'],
    payload: Record<string, unknown>,
    decision: string,
  ): void {
    const usage = this.economicGovernor.getUsageSummary();
    const event: TraceEvent = {
      seq: this.seq++,
      ts: Date.now(),
      type,
      payload,
      decision,
      budgetSnapshot: {
        tokens: usage.tokens.used,
        toolCalls: usage.toolCalls.used,
        storageBytes: usage.storage.usedBytes,
      },
    };
    this.traceEvents.push(event);
  }
}

// ============================================================================
// Memory Clerk Cell
// ============================================================================

/**
 * The canonical test agent cell. Exercises every layer of the guidance
 * control plane by performing reads, inference, and gated writes with
 * a deliberate coherence drop mid-run.
 */
export class MemoryClerkCell implements AgentCell {
  readonly cellId: string;
  readonly name = 'MemoryClerk';

  private readonly readCount: number;
  private readonly inferenceCount: number;
  private readonly writeCount: number;
  private readonly coherenceDropAtWrite: number;
  private readonly droppedCoherenceScore: number;

  constructor(
    cellId?: string,
    options?: {
      readCount?: number;
      inferenceCount?: number;
      writeCount?: number;
      coherenceDropAtWrite?: number;
      droppedCoherenceScore?: number;
    },
  ) {
    this.cellId = cellId ?? `cell-${randomUUID()}`;
    this.readCount = options?.readCount ?? 20;
    this.inferenceCount = options?.inferenceCount ?? 1;
    this.writeCount = options?.writeCount ?? 5;
    this.coherenceDropAtWrite = options?.coherenceDropAtWrite ?? 3;
    this.droppedCoherenceScore = options?.droppedCoherenceScore ?? 0.2;
  }

  run(runtime: CellRuntime): CellRunResult {
    const runId = `run-${randomUUID()}`;
    const startTime = Date.now();
    const sim = runtime as SimulatedRuntime;

    // ----- Step 1: run_start -----
    sim.emitCustomTrace(
      'run_start',
      { cellId: this.cellId, runId, name: this.name },
      'started',
    );

    const coherenceHistory: number[] = [runtime.getCoherenceScore()];

    // ----- Step 2: 20 memory reads -----
    for (let i = 0; i < this.readCount; i++) {
      runtime.readMemory(`knowledge-${i}`, 'clerk-workspace');
    }
    coherenceHistory.push(runtime.getCoherenceScore());

    // ----- Step 3: Model inference -----
    let inferenceResult = '';
    for (let i = 0; i < this.inferenceCount; i++) {
      inferenceResult = runtime.invokeModel(
        `Analyze the ${this.readCount} knowledge entries and determine ` +
          `which ${this.writeCount} insights to persist.`,
      );
    }
    coherenceHistory.push(runtime.getCoherenceScore());

    // ----- Steps 4-7: Propose writes with coherence drop -----
    let writesCommitted = 0;
    let writesBlocked = 0;

    for (let i = 1; i <= this.writeCount; i++) {
      // Inject coherence drop just before the target write
      if (i === this.coherenceDropAtWrite) {
        runtime.setCoherenceScore(this.droppedCoherenceScore);
      }

      coherenceHistory.push(runtime.getCoherenceScore());

      const result = runtime.writeMemory(
        `insight-${i}`,
        'clerk-workspace',
        {
          insightId: i,
          content: `Insight #${i} derived from model inference`,
          inferenceRef: inferenceResult.slice(0, 20),
          timestamp: Date.now(),
        },
        { source: 'model_inference', writeIndex: i },
      );

      if (result.allowed) {
        writesCommitted++;
      } else {
        writesBlocked++;
      }
    }

    // ----- Step 8: Emit proof envelope -----
    const event = runtime.getLedger().createEvent(
      `task-${this.cellId}`,
      'general',
      'conformance-test',
    );
    event.toolsUsed = ['memory_read', 'memory_write', 'model_infer'];
    event.filesTouched = [];
    runtime.getLedger().finalizeEvent(event);

    const proofEnvelope = runtime.getProofChain().append(
      event,
      [],
      sim.getMemoryOps(),
      { agentId: this.cellId, sessionId: runId },
    );

    const proofEnvelopeHash = proofEnvelope.contentHash;

    // Determine final outcome
    let outcome: CellRunResult['outcome'] = 'completed';
    if (writesBlocked > 0 && writesCommitted > 0) {
      outcome = 'restricted';
    } else if (writesBlocked > 0 && writesCommitted === 0) {
      outcome = 'suspended';
    }

    // ----- Step 9: run_end -----
    sim.emitCustomTrace(
      'run_end',
      {
        cellId: this.cellId,
        runId,
        outcome,
        duration: Date.now() - startTime,
        writesCommitted,
        writesBlocked,
      },
      outcome,
    );

    return {
      cellId: this.cellId,
      runId,
      traceEvents: sim.getTraceEvents(),
      memoryReads: sim.getMemoryReads(),
      memoryWritesAttempted: sim.getMemoryWritesAttempted(),
      memoryWritesCommitted: sim.getMemoryWritesCommitted(),
      memoryWritesBlocked: sim.getMemoryWritesBlocked(),
      proofEnvelopeHash,
      coherenceHistory,
      budgetUsage: sim.getBudgetUsage(),
      outcome,
    };
  }
}

