export interface ConformanceTestResult {
  passed: boolean;
  checks: Array<{
    name: string;
    passed: boolean;
    expected: unknown;
    actual: unknown;
    details: string;
  }>;
  trace: TraceEvent[];
  proofHash: string;
  duration: number;
}

// ============================================================================
// Replay Test Result
// ============================================================================

export interface ReplayTestResult {
  identical: boolean;
  totalEvents: number;
  divergences: Array<{
    seq: number;
    originalDecision: string;
    replayDecision: string;
  }>;
}

// ============================================================================
// Conformance Runner
// ============================================================================

/**
 * Orchestrates conformance tests by creating all control plane components,
 * running the MemoryClerkCell, and verifying every invariant.
 */
export class ConformanceRunner {
  private readonly authority: MemoryAuthority;
  private readonly signingKey: string;

  constructor(authority?: MemoryAuthority, signingKey?: string) {
    if (!signingKey) {
      throw new Error('ConformanceRunner requires an explicit signingKey');
    }
    this.signingKey = signingKey;
    this.authority = authority ?? {
      agentId: 'memory-clerk-agent',
      role: 'worker',
      namespaces: ['clerk-workspace'],
      maxWritesPerMinute: 100,
      canDelete: false,
      canOverwrite: true,
      trustLevel: 0.8,
    };
  }

  /**
   * Run the full conformance test suite and return a structured result
   * with individual pass/fail checks.
   */
  runConformanceTest(): ConformanceTestResult {
    const startTime = Date.now();
    const checks: ConformanceTestResult['checks'] = [];

    // Assemble the control plane
    const memoryGate = createMemoryWriteGate({
      authorities: [this.authority],
      enableContradictionTracking: false,
    });
    const proofChain = createProofChain({ signingKey: this.signingKey });
    const ledger = createLedger();
    const coherenceScheduler = createCoherenceScheduler();
    const economicGovernor = createEconomicGovernor({
      tokenLimit: 100_000,
      toolCallLimit: 1_000,
    });

    const runtime = new SimulatedRuntime({
      memoryGate,
      proofChain,
      ledger,
      coherenceScheduler,
      economicGovernor,
      authority: this.authority,
      initialCoherenceScore: 0.9,
    });

    const cell = new MemoryClerkCell();
    const result = cell.run(runtime);

    // ----- Check 1: Exactly 20 memory reads -----
    checks.push({
      name: 'memory_reads_count',
      passed: result.memoryReads === 20,
      expected: 20,
      actual: result.memoryReads,
      details: `Expected 20 memory reads, got ${result.memoryReads}`,
    });

    // ----- Check 2: 5 memory writes attempted -----
    checks.push({
      name: 'memory_writes_attempted',
      passed: result.memoryWritesAttempted === 5,
      expected: 5,
      actual: result.memoryWritesAttempted,
      details: `Expected 5 write attempts, got ${result.memoryWritesAttempted}`,
    });

    // ----- Check 3: First 2 writes committed -----
    checks.push({
      name: 'memory_writes_committed',
      passed: result.memoryWritesCommitted === 2,
      expected: 2,
      actual: result.memoryWritesCommitted,
      details: `Expected 2 committed writes (writes 1-2 before coherence drop), got ${result.memoryWritesCommitted}`,
    });

    // ----- Check 4: Last 3 writes blocked -----
    checks.push({
      name: 'memory_writes_blocked',
      passed: result.memoryWritesBlocked === 3,
      expected: 3,
      actual: result.memoryWritesBlocked,
      details: `Expected 3 blocked writes (writes 3-5 after coherence drop), got ${result.memoryWritesBlocked}`,
    });

    // ----- Check 5: Proof envelope hash is valid SHA-256 hex -----
    const isValidHash =
      typeof result.proofEnvelopeHash === 'string' &&
      /^[0-9a-f]{64}$/.test(result.proofEnvelopeHash);
    checks.push({
      name: 'proof_envelope_hash',
      passed: isValidHash,
      expected: 'SHA-256 hex string (64 chars)',
      actual: result.proofEnvelopeHash,
      details: `Hash length: ${result.proofEnvelopeHash.length}, valid hex: ${isValidHash}`,
    });

    // ----- Check 6: Sequential seq numbers -----
    let seqValid = true;
    let seqErrorAt = -1;
    for (let i = 0; i < result.traceEvents.length; i++) {
      if (result.traceEvents[i].seq !== i) {
        seqValid = false;
        seqErrorAt = i;
        break;
      }
    }
    checks.push({
      name: 'sequential_seq_numbers',
      passed: seqValid,
      expected: 'Sequential 0..N',
      actual: seqValid
        ? `0..${result.traceEvents.length - 1}`
        : `Gap at index ${seqErrorAt} (seq=${result.traceEvents[seqErrorAt]?.seq})`,
      details: seqValid
        ? `All ${result.traceEvents.length} events have sequential seq numbers`
        : `Sequence breaks at index ${seqErrorAt}`,
    });

    // ----- Check 7: Budget tracking is consistent -----
    const budgetValid =
      result.budgetUsage.tokens > 0 && result.budgetUsage.toolCalls > 0;
    checks.push({
      name: 'budget_tracking_consistent',
      passed: budgetValid,
      expected: 'Non-zero token and tool call usage',
      actual: result.budgetUsage,
      details: `tokens=${result.budgetUsage.tokens}, toolCalls=${result.budgetUsage.toolCalls}, storageBytes=${result.budgetUsage.storageBytes}`,
    });

    // ----- Check 8: Outcome is "restricted" -----
    checks.push({
      name: 'outcome_restricted',
      passed: result.outcome === 'restricted',
      expected: 'restricted',
      actual: result.outcome,
      details:
        'Expected "restricted" when some writes committed and some blocked',
    });

    // ----- Check 9: Proof chain integrity -----
    const chainValid = proofChain.verifyChain();
    checks.push({
      name: 'proof_chain_valid',
      passed: chainValid,
      expected: true,
      actual: chainValid,
      details: 'Full proof chain HMAC and hash-chain verification',
    });

    // ----- Check 10: Trace has run_start and run_end bookends -----
    const hasRunStart = result.traceEvents.some(
      (e) => e.type === 'run_start',
    );
    const hasRunEnd = result.traceEvents.some((e) => e.type === 'run_end');
    checks.push({
      name: 'trace_bookends',
      passed: hasRunStart && hasRunEnd,
      expected: 'run_start and run_end present',
      actual: { hasRunStart, hasRunEnd },
      details: `run_start=${hasRunStart}, run_end=${hasRunEnd}`,
    });

    // ----- Check 11: Coherence history records the drop -----
    const hasCoherenceDrop = result.coherenceHistory.some(
      (s) => s < 0.3,
    );
    checks.push({
      name: 'coherence_drop_recorded',
      passed: hasCoherenceDrop,
      expected: 'At least one coherence score below 0.3',
      actual: result.coherenceHistory,
      details: `Min coherence: ${Math.min(...result.coherenceHistory).toFixed(3)}`,
    });

    const allPassed = checks.every((c) => c.passed);

    return {
      passed: allPassed,
      checks,
      trace: result.traceEvents,
      proofHash: result.proofEnvelopeHash,
      duration: Date.now() - startTime,
    };
  }

  /**
   * Replay a previously captured trace and verify that every decision
   * is reproduced identically by the control plane logic.
   */
  runReplayTest(originalTrace: TraceEvent[]): ReplayTestResult {
    const coherenceScheduler = createCoherenceScheduler();
    const thresholds = coherenceScheduler.getThresholds();

    const divergences: ReplayTestResult['divergences'] = [];

    for (const event of originalTrace) {
      let replayDecision: string;

      switch (event.type) {
        case 'memory_read':
          replayDecision = 'read_allowed';
          break;

        case 'memory_write_proposed':
          replayDecision = 'proposed';
          break;

        case 'coherence_check': {
          const score = event.payload.score as number;
          if (score >= thresholds.healthyThreshold) {
            replayDecision = 'full';
          } else if (score >= thresholds.warningThreshold) {
            replayDecision = 'restricted';
          } else if (score >= thresholds.readOnlyThreshold) {
            replayDecision = 'read-only';
          } else {
            replayDecision = 'suspended';
          }
          break;
        }

        case 'memory_write_committed':
          replayDecision = 'committed';
          break;

        case 'memory_write_blocked': {
          const hasPrivilegeLevel =
            event.payload.privilegeLevel !== undefined;
          replayDecision = hasPrivilegeLevel
            ? 'blocked_coherence'
            : 'blocked_gate';
          break;
        }

        case 'model_infer':
          replayDecision = 'inference_complete';
          break;

        case 'tool_invoke':
          replayDecision = (event.payload.allowed as boolean)
            ? 'allowed'
            : 'blocked';
          break;

        case 'privilege_change': {
          const prev = event.payload.previousLevel as string;
          const next = event.payload.newLevel as string;
          replayDecision = `${prev}->${next}`;
          break;
        }

        case 'run_start':
          replayDecision = 'started';
          break;

        case 'run_end':
          replayDecision = event.payload.outcome as string;
          break;

        default:
          replayDecision = 'unknown';
      }

      if (replayDecision !== event.decision) {
        divergences.push({
          seq: event.seq,
          originalDecision: event.decision,
          replayDecision,
        });
      }
    }

    return {
      identical: divergences.length === 0,
      totalEvents: originalTrace.length,
      divergences,
    };
  }
}

// ============================================================================
// Factory Functions
// ============================================================================

/**
 * Create a MemoryClerkCell with an optional cellId override.
 */
export function createMemoryClerkCell(cellId?: string): MemoryClerkCell {
  return new MemoryClerkCell(cellId);
}

/**
 * Create a ConformanceRunner with optional authority override.
 */
export function createConformanceRunner(
  authority?: MemoryAuthority,
  signingKey?: string,
): ConformanceRunner {
  return new ConformanceRunner(authority, signingKey ?? 'conformance-test-key');
}

/**
 * Continue Gate - Long-Running Agent Control
 *
 * Evaluates whether a long-running agent should continue its next step.
 * Prevents runaway loops, budget exhaustion, and coherence degradation.
 *
 * Problem:
 * Current gates are tool-centric (PreToolUse, PreCommand, PreEdit).
 * Long-run loops are often internally generated — the agent keeps going
 * without a single obviously bad tool call. There is no gate for "should
 * this agent continue at all?"
 *
 * ContinueGate provides step-level evaluation with:
 * - Hard limits on consecutive steps without checkpoints
 * - Budget acceleration detection via linear regression
 * - Coherence threshold enforcement
 * - Uncertainty threshold enforcement
 * - Rework ratio tracking
 * - Automatic checkpoint intervals
 * - Cooldown between evaluations
 *
 * Decision types:
 * - continue: Agent may proceed to next step
 * - checkpoint: Agent must save state before continuing
 * - throttle: Agent should slow down or wait
 * - pause: Agent should stop and await human review
 * - stop: Agent must halt immediately
 *
 * @module @claude-flow/guidance/continue-gate
 */

import { randomUUID } from 'node:crypto';

// ============================================================================
// Types
// ============================================================================

/**
 * Configuration for the ContinueGate
 */
export interface ContinueGateConfig {
  /** Hard limit on consecutive steps without checkpoint (default 100) */
  maxConsecutiveSteps: number;
  /** Maximum budget slope per step (cost acceleration threshold, default 0.02) */
  maxBudgetSlopePerStep: number;
  /** Minimum coherence score to continue (default 0.4) */
  minCoherenceForContinue: number;
  /** Maximum uncertainty score to continue (default 0.8) */
  maxUncertaintyForContinue: number;
  /** Maximum rework/total steps ratio (default 0.3) */
  maxReworkRatio: number;
  /** Force checkpoint every N steps (default 25) */
  checkpointIntervalSteps: number;
  /** Minimum time between evaluations in milliseconds (default 5000) */
  cooldownMs: number;
}

/**
 * Context for a single step evaluation
 */
export interface StepContext {
  /** Current step number in the run */
  stepNumber: number;
  /** Total tokens consumed so far */
  totalTokensUsed: number;
  /** Total tool calls made so far */
  totalToolCalls: number;
  /** Number of steps that redid previous work */
  reworkCount: number;
  /** Coherence score from CoherenceScheduler (0-1) */
  coherenceScore: number;
  /** Uncertainty score from UncertaintyAggregator (0-1) */
  uncertaintyScore: number;
  /** Elapsed time in milliseconds since run start */
  elapsedMs: number;
  /** Step number of the last checkpoint */
  lastCheckpointStep: number;
  /** Remaining budget across all dimensions */
  budgetRemaining: {
    tokens: number;
    toolCalls: number;
    timeMs: number;
  };
  /** Recent evaluation decisions (last 10) */
  recentDecisions: Array<{
    step: number;
    decision: 'allow' | 'deny' | 'warn';
  }>;
}

/**
 * Decision outcome from the continue gate
 */
export interface ContinueDecision {
  /** The decision type */
  decision: 'continue' | 'checkpoint' | 'throttle' | 'pause' | 'stop';
  /** Human-readable reasons for the decision */
  reasons: string[];
  /** Computed metrics for this evaluation */
  metrics: {
    /** Budget acceleration rate (tokens per step slope) */
    budgetSlope: number;
    /** Ratio of rework steps to total steps */
    reworkRatio: number;
    /** Steps until next required checkpoint */
    stepsUntilCheckpoint: number;
    /** Coherence health level */
    coherenceLevel: 'healthy' | 'degraded' | 'critical';
    /** Uncertainty level */
    uncertaintyLevel: 'low' | 'moderate' | 'high' | 'extreme';
  };
  /** Recommended action for the agent */
  recommendedAction?: string;
}

/**
 * Internal history record for tracking evaluations
 */
interface EvaluationRecord {
  step: number;
  decision: ContinueDecision;
  timestamp: number;
  tokensUsed: number;
}

// ============================================================================
// Default Configuration
// ============================================================================

const DEFAULT_CONFIG: ContinueGateConfig = {
  maxConsecutiveSteps: 100,
  maxBudgetSlopePerStep: 0.02,
  minCoherenceForContinue: 0.4,
  maxUncertaintyForContinue: 0.8,
  maxReworkRatio: 0.3,
  checkpointIntervalSteps: 25,
  cooldownMs: 5000,
};

const MAX_HISTORY_SIZE = 10000;
const SLOPE_WINDOW_SIZE = 10; // Number of recent steps to use for budget slope calculation

// ============================================================================
// ContinueGate
// ============================================================================

/**
 * Gate that evaluates whether a long-running agent should continue.
 *
 * Prevents runaway execution by checking:
 * - Step limits
 * - Budget exhaustion and acceleration
 * - Coherence degradation
 * - Uncertainty thresholds
 * - Rework ratios
 * - Checkpoint intervals
 *
 * Maintains history of evaluations and provides aggregate statistics.
 */
export class ContinueGate {
  private readonly config: ContinueGateConfig;
  private readonly history: EvaluationRecord[] = [];
  private lastEvaluationTime = 0;
  private readonly tokenHistory: Array<{ step: number; tokens: number }> = [];

  constructor(config: Partial<ContinueGateConfig> = {}) {
    this.config = { ...DEFAULT_CONFIG, ...config };
  }

  /**
   * Evaluate whether the agent should continue.
   *
   * Applies decision logic in priority order:
   * 1. Coherence below threshold → stop
   * 2. Step limit exceeded → stop
   * 3. Budget exhausted → stop
   * 4. High rework ratio → pause
   * 5. High uncertainty → pause
   * 6. Budget acceleration → throttle
   * 7. Checkpoint interval reached → checkpoint
   * 8. Otherwise → continue
   *
   * @param context - Current step context
   * @returns Decision with reasons and metrics
   */
  evaluate(context: StepContext): ContinueDecision {
    const now = Date.now();
    const reasons: string[] = [];

    // Track token usage for slope calculation
    this.tokenHistory.push({
      step: context.stepNumber,
      tokens: context.totalTokensUsed,
    });
    if (this.tokenHistory.length > SLOPE_WINDOW_SIZE) {
      this.tokenHistory.shift();
    }

    // Compute metrics
    const budgetSlope = this.computeBudgetSlope();
    const reworkRatio = context.stepNumber > 0
      ? context.reworkCount / context.stepNumber
      : 0;
    const stepsUntilCheckpoint =
      this.config.checkpointIntervalSteps -
      (context.stepNumber - context.lastCheckpointStep);
    const coherenceLevel = this.getCoherenceLevel(context.coherenceScore);
    const uncertaintyLevel = this.getUncertaintyLevel(context.uncertaintyScore);

    const metrics = {
      budgetSlope,
      reworkRatio,
      stepsUntilCheckpoint,
      coherenceLevel,
      uncertaintyLevel,
    };

    // Decision logic (priority order)

    // 1. Coherence below threshold → stop
    if (context.coherenceScore < this.config.minCoherenceForContinue) {
      reasons.push(
        `Coherence below threshold (${context.coherenceScore.toFixed(2)} < ${this.config.minCoherenceForContinue})`,
      );
      return this.createDecision('stop', reasons, metrics, 'Halt execution and review coherence issues');
    }

    // 2. Step limit exceeded → stop
    if (
      context.stepNumber >= this.config.maxConsecutiveSteps &&
      context.stepNumber - context.lastCheckpointStep >= this.config.checkpointIntervalSteps
    ) {
      reasons.push(
        `Step limit exceeded (${context.stepNumber} >= ${this.config.maxConsecutiveSteps}) without recent checkpoint`,
      );
      return this.createDecision('stop', reasons, metrics, 'Create checkpoint and review progress');
    }

    // 3. Budget exhausted → stop
    if (
      context.budgetRemaining.tokens <= 0 ||
      context.budgetRemaining.toolCalls <= 0 ||
      context.budgetRemaining.timeMs <= 0
    ) {
      const exhausted: string[] = [];
      if (context.budgetRemaining.tokens <= 0) exhausted.push('tokens');
      if (context.budgetRemaining.toolCalls <= 0) exhausted.push('tool calls');
      if (context.budgetRemaining.timeMs <= 0) exhausted.push('time');

      reasons.push(`Budget exhausted: ${exhausted.join(', ')}`);
      return this.createDecision('stop', reasons, metrics, 'Increase budget or simplify task scope');
    }

    // 4. High rework ratio → pause
    if (reworkRatio > this.config.maxReworkRatio) {
      reasons.push(
        `Rework ratio too high (${(reworkRatio * 100).toFixed(1)}% > ${(this.config.maxReworkRatio * 100).toFixed(1)}%)`,
      );
      return this.createDecision(
        'pause',
        reasons,
        metrics,
        'Review recent work for repeated errors or unclear objectives',
      );
    }

    // 5. High uncertainty → pause
    if (context.uncertaintyScore > this.config.maxUncertaintyForContinue) {
      reasons.push(
        `Uncertainty too high (${context.uncertaintyScore.toFixed(2)} > ${this.config.maxUncertaintyForContinue})`,
      );
      return this.createDecision(
        'pause',
        reasons,
        metrics,
        'Resolve uncertain beliefs or gather more evidence before continuing',
      );
    }

    // 6. Budget acceleration → throttle
    if (budgetSlope > this.config.maxBudgetSlopePerStep) {
      reasons.push(
        `Budget acceleration detected (slope: ${budgetSlope.toFixed(4)} > ${this.config.maxBudgetSlopePerStep})`,
      );
      return this.createDecision(
        'throttle',
        reasons,
        metrics,
        'Slow down execution or optimize token usage',
      );
    }

    // 7. Checkpoint interval reached → checkpoint
    if (stepsUntilCheckpoint <= 0) {
      reasons.push(
        `Checkpoint interval reached (${context.stepNumber - context.lastCheckpointStep} >= ${this.config.checkpointIntervalSteps})`,
      );
      return this.createDecision('checkpoint', reasons, metrics, 'Save current state before continuing');
    }

    // 8. Otherwise → continue
    reasons.push('All checks passed');
    return this.createDecision('continue', reasons, metrics);
  }

  /**
   * Evaluate and record the decision in history.
   *
   * This method also checks the cooldown period — if called too soon
   * after the last evaluation, it returns a 'continue' decision without
   * full evaluation to prevent excessive overhead.
   *
   * @param context - Current step context
   * @returns Decision with reasons and metrics
   */
  evaluateWithHistory(context: StepContext): ContinueDecision {
    const now = Date.now();

    // Cooldown check — but always evaluate critical stop conditions
    // to prevent agents from timing steps to bypass safety checks
    if (now - this.lastEvaluationTime < this.config.cooldownMs) {
      // Even during cooldown, check hard-stop conditions
      if (context.coherenceScore < this.config.minCoherenceForContinue) {
        return this.createDecision('stop',
          ['Coherence below threshold (checked during cooldown)'],
          { budgetSlope: 0, reworkRatio: 0, stepsUntilCheckpoint: 0, coherenceLevel: 'critical', uncertaintyLevel: 'low' },
          'Halt execution and review coherence issues');
      }
      if (context.budgetRemaining.tokens <= 0 || context.budgetRemaining.toolCalls <= 0 || context.budgetRemaining.timeMs <= 0) {
        return this.createDecision('stop',
          ['Budget exhausted (checked during cooldown)'],
          { budgetSlope: 0, reworkRatio: 0, stepsUntilCheckpoint: 0, coherenceLevel: 'healthy', uncertaintyLevel: 'low' },
          'Increase budget or simplify task scope');
      }

      // Non-critical checks can be skipped during cooldown
      return {
        decision: 'continue',
        reasons: ['Cooldown period active; skipping full evaluation'],
        metrics: {
          budgetSlope: 0,
          reworkRatio: 0,
          stepsUntilCheckpoint: 0,
          coherenceLevel: this.getCoherenceLevel(context.coherenceScore),
          uncertaintyLevel: this.getUncertaintyLevel(context.uncertaintyScore),
        },
      };
    }

    this.lastEvaluationTime = now;

    const decision = this.evaluate(context);

    // Record in history
    const record: EvaluationRecord = {
      step: context.stepNumber,
      decision,
      timestamp: now,
      tokensUsed: context.totalTokensUsed,
    };

    this.history.push(record);

    // Evict oldest if exceeding max size
    if (this.history.length > MAX_HISTORY_SIZE) {
      this.history.shift();
    }

    return decision;
  }

  /**
   * Get the full evaluation history.
   *
   * Returns up to MAX_HISTORY_SIZE most recent evaluations.
   *
   * @returns Array of evaluation records ordered oldest to newest
   */
  getHistory(): Array<{ step: number; decision: ContinueDecision; timestamp: number }> {
    return this.history.map(r => ({
      step: r.step,
      decision: { ...r.decision },
      timestamp: r.timestamp,
    }));
  }

  /**
   * Get aggregate statistics across all evaluations.
   *
   * @returns Statistics including total evaluations, decision counts, and average budget slope
   */
  getStats(): {
    totalEvaluations: number;
    decisions: Record<string, number>;
    averageBudgetSlope: number;
  } {
    const decisions: Record<string, number> = {
      continue: 0,
      checkpoint: 0,
      throttle: 0,
      pause: 0,
      stop: 0,
    };

    let totalSlope = 0;
    let slopeCount = 0;

    for (const record of this.history) {
      decisions[record.decision.decision]++;
      totalSlope += record.decision.metrics.budgetSlope;
      slopeCount++;
    }

    return {
      totalEvaluations: this.history.length,
      decisions,
      averageBudgetSlope: slopeCount > 0 ? totalSlope / slopeCount : 0,
    };
  }

  /**
   * Reset all internal state.
   *
   * Clears history, token tracking, and last evaluation time.
   */
  reset(): void {
    this.history.length = 0;
    this.tokenHistory.length = 0;
    this.lastEvaluationTime = 0;
  }

  /**
   * Get the current configuration.
   */
  getConfig(): ContinueGateConfig {
    return { ...this.config };
  }

  // =========================================================================
  // Private Helpers
  // =========================================================================

  /**
   * Compute the budget slope (rate of token consumption per step)
   * using linear regression on the last N steps.
   *
   * Returns the slope coefficient (tokens per step). A positive slope
   * indicates increasing token usage. A slope above the configured
   * threshold indicates budget acceleration.
   */
  private computeBudgetSlope(): number {
    if (this.tokenHistory.length < 2) {
      // Need at least 2 points for regression
      return 0;
    }

    const n = this.tokenHistory.length;
    let sumX = 0;
    let sumY = 0;
    let sumXY = 0;
    let sumXX = 0;

    for (const point of this.tokenHistory) {
      const x = point.step;
      const y = point.tokens;
      sumX += x;
      sumY += y;
      sumXY += x * y;
      sumXX += x * x;
    }

    // Linear regression: slope = (n*sumXY - sumX*sumY) / (n*sumXX - sumX*sumX)
    const denominator = n * sumXX - sumX * sumX;
    if (denominator === 0) {
      // All x values are the same (shouldn't happen, but guard)
      return 0;
    }

    const slope = (n * sumXY - sumX * sumY) / denominator;

    return slope;
  }

  /**
   * Map coherence score to a health level.
   */
  private getCoherenceLevel(score: number): 'healthy' | 'degraded' | 'critical' {
    if (score >= 0.7) return 'healthy';
    if (score >= 0.4) return 'degraded';
    return 'critical';
  }

  /**
   * Map uncertainty score to a level.
   */
  private getUncertaintyLevel(score: number): 'low' | 'moderate' | 'high' | 'extreme' {
    if (score <= 0.3) return 'low';
    if (score <= 0.6) return 'moderate';
    if (score <= 0.8) return 'high';
    return 'extreme';
  }

  /**
   * Create a standardized decision object.
   */
  private createDecision(
    decision: 'continue' | 'checkpoint' | 'throttle' | 'pause' | 'stop',
    reasons: string[],
    metrics: ContinueDecision['metrics'],
    recommendedAction?: string,
  ): ContinueDecision {
    return {
      decision,
      reasons,
      metrics,
      recommendedAction,
    };
  }
}

// ============================================================================
// Factory Function
// ============================================================================

/**
 * Create a ContinueGate instance with optional configuration.
 *
 * @param config - Partial configuration; unspecified values use defaults
 * @returns A fresh ContinueGate instance
 */
export function createContinueGate(config?: Partial<ContinueGateConfig>): ContinueGate {
  return new ContinueGate(config);
}

/**
 * Shared Cryptographic Utilities
 *
 * Centralises timing-safe comparison so every module that verifies
 * HMAC signatures uses the same constant-time implementation.
 *
 * @module @claude-flow/guidance/crypto-utils
 */

import { timingSafeEqual as nodeTimingSafeEqual } from 'node:crypto';

/**
 * Constant-time string comparison to prevent timing attacks on HMAC signatures.
 *
 * Delegates to Node.js `crypto.timingSafeEqual` via `Buffer.from` for
 * encoding-safe comparison. Falls back to a manual XOR loop when the
 * buffers have different byte lengths (which the native function rejects).
 */
export function timingSafeEqual(a: string, b: string): boolean {
  const bufA = Buffer.from(a, 'utf-8');
  const bufB = Buffer.from(b, 'utf-8');

  if (bufA.length !== bufB.length) return false;

  return nodeTimingSafeEqual(bufA, bufB);
}

/**
 * Evolution Pipeline
 *
 * Every change to prompts, policies, tools, and code becomes a signed change
 * proposal that goes through simulation, replay comparison, and staged rollout.
 *
 * Pipeline stages:
 * 1. Propose - Create a signed ChangeProposal
 * 2. Simulate - Replay golden traces with baseline vs candidate config
 * 3. Compare  - Approve or reject based on divergence threshold
 * 4. Stage    - Create a staged rollout plan (canary -> partial -> full)
 * 5. Advance  - Progress through stages with metric gates
 * 6. Promote / Rollback - Apply permanently or revert
 *
 * @module @claude-flow/guidance/evolution
 */

import { createHash, createHmac, randomUUID } from 'node:crypto';

// ============================================================================
// Types
// ============================================================================

/**
 * The kind of change being proposed.
 */
export type ChangeProposalKind =
  | 'rule-modify'
  | 'rule-add'
  | 'rule-remove'
  | 'rule-promote'
  | 'policy-update'
  | 'tool-config'
  | 'budget-adjust';

/**
 * Lifecycle status of a change proposal.
 */
export type ProposalStatus =
  | 'draft'
  | 'signed'
  | 'simulating'
  | 'compared'
  | 'staged'
  | 'promoted'
  | 'rolled-back'
  | 'rejected';

/**
 * Risk assessment attached to a proposal.
 */
export interface RiskAssessment {
  level: 'low' | 'medium' | 'high';
  factors: string[];
}

/**
 * A signed change proposal describing a modification to the guidance system.
 */
export interface ChangeProposal {
  /** Unique identifier (UUID) */
  proposalId: string;
  /** What kind of change this is */
  kind: ChangeProposalKind;
  /** Short human-readable title */
  title: string;
  /** Longer description of the change */
  description: string;
  /** Agent or human ID that authored the proposal */
  author: string;
  /** Dot-path or identifier of what is being changed */
  targetPath: string;
  /** Before/after snapshot of the change */
  diff: { before: unknown; after: unknown };
  /** Why this change is being proposed */
  rationale: string;
  /** Risk assessment for the change */
  riskAssessment: RiskAssessment;
  /** HMAC-SHA256 signature of the proposal content */
  signature: string;
  /** Epoch ms when the proposal was created */
  createdAt: number;
  /** Current lifecycle status */
  status: ProposalStatus;
}

/**
 * A single decision point where baseline and candidate diverged.
 */
export interface DecisionDiff {
  /** Sequence number in the trace */
  seq: number;
  /** What the baseline decided */
  baseline: unknown;
  /** What the candidate decided */
  candidate: unknown;
  /** How severe the divergence is */
  severity: 'low' | 'medium' | 'high';
}

/**
 * Result of simulating a proposal against golden traces.
 */
export interface SimulationResult {
  /** Proposal that was simulated */
  proposalId: string;
  /** Hash of the trace produced by baseline config */
  baselineTraceHash: string;
  /** Hash of the trace produced by candidate config */
  candidateTraceHash: string;
  /** 0-1 score: 0 = identical, 1 = completely different */
  divergenceScore: number;
  /** Individual decision points where behaviour diverged */
  decisionDiffs: DecisionDiff[];
  /** Side-by-side metric comparison */
  metricsComparison: {
    baseline: Record<string, number>;
    candidate: Record<string, number>;
  };
  /** Whether the simulation passed acceptance criteria */
  passed: boolean;
  /** Human-readable reason for the verdict */
  reason: string;
}

/**
 * A single stage in a staged rollout.
 */
export interface RolloutStage {
  /** Stage name (e.g. 'canary', 'partial', 'full') */
  name: string;
  /** Percentage of traffic/agents this stage covers (0-100) */
  percentage: number;
  /** How long this stage should run before advancing (ms) */
  durationMs: number;
  /** Observed metrics during this stage */
  metrics: Record<string, number>;
  /** Maximum acceptable divergence before auto-rollback */
  divergenceThreshold: number;
  /** null = not evaluated yet, true = passed, false = failed */
  passed: boolean | null;
  /** Epoch ms when the stage started (null if not started) */
  startedAt: number | null;
  /** Epoch ms when the stage completed (null if not completed) */
  completedAt: number | null;
}

/**
 * A staged rollout plan for a change proposal.
 */
export interface StagedRollout {
  /** Unique rollout identifier */
  rolloutId: string;
  /** The proposal being rolled out */
  proposalId: string;
  /** Ordered stages (canary -> partial -> full) */
  stages: RolloutStage[];
  /** Index of the current stage (0-based) */
  currentStage: number;
  /** Overall rollout status */
  status: 'in-progress' | 'completed' | 'rolled-back';
  /** Epoch ms when the rollout started */
  startedAt: number;
  /** Epoch ms when the rollout completed (null if still running) */
  completedAt: number | null;
}

/**
 * History entry combining proposal, optional simulation, optional rollout,
 * and final outcome.
 */
export interface EvolutionHistoryEntry {
  proposal: ChangeProposal;
  simulation?: SimulationResult;
  rollout?: StagedRollout;
  outcome: ProposalStatus;
}

/**
 * Evaluator function for simulation: given a golden trace and a config variant,
 * produce a trace hash and metrics.
 */
export type TraceEvaluator = (
  trace: unknown,
  config: 'baseline' | 'candidate',
) => { traceHash: string; metrics: Record<string, number>; decisions: unknown[] };

// ============================================================================
// Configuration
// ============================================================================

export interface EvolutionPipelineConfig {
  /** HMAC signing key for proposals */
  signingKey?: string;
  /** Maximum divergence score (0-1) to approve a change */
  maxDivergence?: number;
  /** Default rollout stages */
  stages?: RolloutStage[];
}

const DEFAULT_MAX_DIVERGENCE = 0.3;

const DEFAULT_STAGES: RolloutStage[] = [
  {
    name: 'canary',
    percentage: 5,
    durationMs: 60_000,
    metrics: {},
    divergenceThreshold: 0.2,
    passed: null,
    startedAt: null,
    completedAt: null,
  },
  {
    name: 'partial',
    percentage: 50,
    durationMs: 300_000,
    metrics: {},
    divergenceThreshold: 0.25,
    passed: null,
    startedAt: null,
    completedAt: null,
  },
  {
    name: 'full',
    percentage: 100,
    durationMs: 600_000,
    metrics: {},
    divergenceThreshold: 0.3,
    passed: null,
    startedAt: null,
    completedAt: null,
  },
];

// ============================================================================
// EvolutionPipeline
// ============================================================================

/**
 * The Evolution Pipeline manages the lifecycle of change proposals through
 * signing, simulation, comparison, staged rollout, and promotion or rollback.
 */
export class EvolutionPipeline {
  private readonly signingKey: string;
  private readonly maxDivergence: number;
  private readonly defaultStages: RolloutStage[];

  private proposals = new Map<string, ChangeProposal>();
  private simulations = new Map<string, SimulationResult>();
  private rollouts = new Map<string, StagedRollout>();

  constructor(config: EvolutionPipelineConfig = {}) {
    if (!config.signingKey) {
      throw new Error('EvolutionPipeline requires an explicit signingKey — hardcoded defaults are not secure');
    }
    this.signingKey = config.signingKey;
    this.maxDivergence = config.maxDivergence ?? DEFAULT_MAX_DIVERGENCE;
    this.defaultStages = config.stages ?? DEFAULT_STAGES;
  }

  // ==========================================================================
  // Propose
  // ==========================================================================

  /**
   * Create and sign a new change proposal.
   */
  propose(params: {
    kind: ChangeProposalKind;
    title: string;
    description: string;
    author: string;
    targetPath: string;
    diff: { before: unknown; after: unknown };
    rationale: string;
    riskAssessment: RiskAssessment;
  }): ChangeProposal {
    const proposalId = randomUUID();
    const createdAt = Date.now();

    const proposal: ChangeProposal = {
      proposalId,
      kind: params.kind,
      title: params.title,
      description: params.description,
      author: params.author,
      targetPath: params.targetPath,
      diff: params.diff,
      rationale: params.rationale,
      riskAssessment: params.riskAssessment,
      signature: '', // placeholder, signed below
      createdAt,
      status: 'draft',
    };

    proposal.signature = this.signProposal(proposal);
    proposal.status = 'signed';

    this.proposals.set(proposalId, proposal);
    return proposal;
  }

  // ==========================================================================
  // Simulate
  // ==========================================================================

  /**
   * Run golden traces through both baseline and candidate configs to measure
   * divergence. The evaluator is called once per golden trace per config.
   */
  simulate(
    proposalId: string,
    goldenTraces: unknown[],
    evaluator: TraceEvaluator,
  ): SimulationResult {
    const proposal = this.proposals.get(proposalId);
    if (!proposal) {
      throw new Error(`Proposal not found: ${proposalId}`);
    }

    proposal.status = 'simulating';

    // Evaluate each trace against both configs
    const baselineResults = goldenTraces.map(t => evaluator(t, 'baseline'));
    const candidateResults = goldenTraces.map(t => evaluator(t, 'candidate'));

    // Compute composite trace hashes
    const baselineTraceHash = this.hashTraceResults(baselineResults.map(r => r.traceHash));
    const candidateTraceHash = this.hashTraceResults(candidateResults.map(r => r.traceHash));

    // Compute decision diffs
    const decisionDiffs: DecisionDiff[] = [];
    for (let i = 0; i < goldenTraces.length; i++) {
      const bDecisions = baselineResults[i].decisions;
      const cDecisions = candidateResults[i].decisions;
      const maxLen = Math.max(bDecisions.length, cDecisions.length);

      for (let seq = 0; seq < maxLen; seq++) {
        const bVal = seq < bDecisions.length ? bDecisions[seq] : undefined;
        const cVal = seq < cDecisions.length ? cDecisions[seq] : undefined;

        if (JSON.stringify(bVal) !== JSON.stringify(cVal)) {
          decisionDiffs.push({
            seq,
            baseline: bVal,
            candidate: cVal,
            severity: this.classifyDiffSeverity(bVal, cVal),
          });
        }
      }
    }

    // Aggregate metrics
    const baselineMetrics = this.aggregateMetrics(baselineResults.map(r => r.metrics));
    const candidateMetrics = this.aggregateMetrics(candidateResults.map(r => r.metrics));

    // Compute divergence score (0-1)
    const divergenceScore = this.computeDivergenceScore(
      baselineTraceHash,
      candidateTraceHash,
      decisionDiffs,
      goldenTraces.length,
    );

    const passed = divergenceScore <= this.maxDivergence;
    const reason = passed
      ? `Divergence ${divergenceScore.toFixed(3)} is within threshold ${this.maxDivergence}`
      : `Divergence ${divergenceScore.toFixed(3)} exceeds threshold ${this.maxDivergence}`;

    const result: SimulationResult = {
      proposalId,
      baselineTraceHash,
      candidateTraceHash,
      divergenceScore,
      decisionDiffs,
      metricsComparison: {
        baseline: baselineMetrics,
        candidate: candidateMetrics,
      },
      passed,
      reason,
    };

    this.simulations.set(proposalId, result);
    return result;
  }

  // ==========================================================================
  // Compare
  // ==========================================================================

  /**
   * Compare a simulation result against acceptance criteria.
   *
   * Checks:
   * 1. Divergence is below threshold
   * 2. No regression in key metrics (candidate >= baseline)
   */
  compare(
    proposalId: string,
    simulationResult: SimulationResult,
  ): { approved: boolean; reason: string } {
    const proposal = this.proposals.get(proposalId);
    if (!proposal) {
      throw new Error(`Proposal not found: ${proposalId}`);
    }

    // Check divergence threshold
    if (simulationResult.divergenceScore > this.maxDivergence) {
      proposal.status = 'rejected';
      return {
        approved: false,
        reason: `Divergence ${simulationResult.divergenceScore.toFixed(3)} exceeds threshold ${this.maxDivergence}`,
      };
    }

    // Check for metric regressions
    const { baseline, candidate } = simulationResult.metricsComparison;
    const regressions: string[] = [];

    for (const key of Object.keys(baseline)) {
      if (candidate[key] !== undefined && candidate[key] < baseline[key]) {
        const pctDrop = ((baseline[key] - candidate[key]) / Math.max(baseline[key], 1)) * 100;
        // Only flag significant regressions (> 5%)
        if (pctDrop > 5) {
          regressions.push(`${key} regressed by ${pctDrop.toFixed(1)}%`);
        }
      }
    }

    if (regressions.length > 0) {
      proposal.status = 'rejected';
      return {
        approved: false,
        reason: `Metric regressions detected: ${regressions.join('; ')}`,
      };
    }

    proposal.status = 'compared';
    return {
      approved: true,
      reason: `Divergence ${simulationResult.divergenceScore.toFixed(3)} within threshold, no metric regressions`,
    };
  }

  // ==========================================================================
  // Stage
  // ==========================================================================

  /**
   * Create a staged rollout plan for a proposal.
   */
  stage(proposalId: string): StagedRollout {
    const proposal = this.proposals.get(proposalId);
    if (!proposal) {
      throw new Error(`Proposal not found: ${proposalId}`);
    }

    const now = Date.now();

    // Deep-clone default stages so each rollout has independent state
    const stages: RolloutStage[] = this.defaultStages.map(s => ({
      ...s,
      metrics: { ...s.metrics },
      passed: null,
      startedAt: null,
      completedAt: null,
    }));

    // Start the first stage immediately
    stages[0].startedAt = now;

    const rollout: StagedRollout = {
      rolloutId: randomUUID(),
      proposalId,
      stages,
      currentStage: 0,
      status: 'in-progress',
      startedAt: now,
      completedAt: null,
    };

    proposal.status = 'staged';
    this.rollouts.set(rollout.rolloutId, rollout);
    return rollout;
  }

  // ==========================================================================
  // Advance Stage
  // ==========================================================================

  /**
   * Advance to the next rollout stage or auto-rollback.
   *
   * If `stageMetrics.divergence` exceeds the current stage's threshold,
   * the rollout is automatically rolled back.
   */
  advanceStage(
    rolloutId: string,
    stageMetrics: Record<string, number>,
  ): { advanced: boolean; rolledBack: boolean; reason: string } {
    const rollout = this.rollouts.get(rolloutId);
    if (!rollout) {
      throw new Error(`Rollout not found: ${rolloutId}`);
    }

    if (rollout.status !== 'in-progress') {
      return {
        advanced: false,
        rolledBack: false,
        reason: `Rollout is ${rollout.status}, not in-progress`,
      };
    }

    const current = rollout.stages[rollout.currentStage];
    const now = Date.now();

    // Record metrics on the current stage
    current.metrics = { ...stageMetrics };

    // Check divergence against threshold
    const divergence = stageMetrics.divergence ?? 0;
    if (divergence > current.divergenceThreshold) {
      // Auto-rollback
      current.passed = false;
      current.completedAt = now;
      this.rollback(rolloutId, `Stage "${current.name}" divergence ${divergence.toFixed(3)} exceeded threshold ${current.divergenceThreshold}`);
      return {
        advanced: false,
        rolledBack: true,
        reason: `Auto-rollback: divergence ${divergence.toFixed(3)} exceeded threshold ${current.divergenceThreshold} at stage "${current.name}"`,
      };
    }

    // Current stage passed
    current.passed = true;
    current.completedAt = now;

    // Check if there are more stages
    if (rollout.currentStage < rollout.stages.length - 1) {
      rollout.currentStage += 1;
      rollout.stages[rollout.currentStage].startedAt = now;
      return {
        advanced: true,
        rolledBack: false,
        reason: `Advanced to stage "${rollout.stages[rollout.currentStage].name}"`,
      };
    }

    // All stages complete - auto-promote
    rollout.status = 'completed';
    rollout.completedAt = now;
    const proposal = this.proposals.get(rollout.proposalId);
    if (proposal) {
      proposal.status = 'promoted';
    }

    return {
      advanced: true,
      rolledBack: false,
      reason: 'All stages completed successfully; proposal promoted',
    };
  }

  // ==========================================================================
  // Rollback
  // ==========================================================================

  /**
   * Roll back a staged rollout.
   */
  rollback(rolloutId: string, reason: string): void {
    const rollout = this.rollouts.get(rolloutId);
    if (!rollout) {
      throw new Error(`Rollout not found: ${rolloutId}`);
    }

    rollout.status = 'rolled-back';
    rollout.completedAt = Date.now();

    const proposal = this.proposals.get(rollout.proposalId);
    if (proposal) {
      proposal.status = 'rolled-back';
    }
  }

  // ==========================================================================
  // Promote
  // ==========================================================================

  /**
   * Promote a rollout, permanently applying the change.
   */
  promote(rolloutId: string): void {
    const rollout = this.rollouts.get(rolloutId);
    if (!rollout) {
      throw new Error(`Rollout not found: ${rolloutId}`);
    }

    rollout.status = 'completed';
    rollout.completedAt = Date.now();

    const proposal = this.proposals.get(rollout.proposalId);
    if (proposal) {
      proposal.status = 'promoted';
    }
  }

  // ==========================================================================
  // Queries
  // ==========================================================================

  /**
   * Get a proposal by ID.
   */
  getProposal(id: string): ChangeProposal | undefined {
    return this.proposals.get(id);
  }

  /**
   * Get all proposals, optionally filtered by status.
   */
  getProposals(status?: ProposalStatus): ChangeProposal[] {
    const all = Array.from(this.proposals.values());
    if (status === undefined) {
      return all;
    }
    return all.filter(p => p.status === status);
  }

  /**
   * Get a rollout by ID.
   */
  getRollout(id: string): StagedRollout | undefined {
    return this.rollouts.get(id);
  }

  /**
   * Get the full evolution history across all proposals.
   */
  getHistory(): EvolutionHistoryEntry[] {
    return Array.from(this.proposals.values()).map(proposal => ({
      proposal,
      simulation: this.simulations.get(proposal.proposalId),
      rollout: this.findRolloutByProposal(proposal.proposalId),
      outcome: proposal.status,
    }));
  }

  // ==========================================================================
  // Private Helpers
  // ==========================================================================

  /**
   * Produce an HMAC-SHA256 signature for a proposal.
   *
   * The signature covers every field except `signature` and `status`.
   */
  private signProposal(proposal: ChangeProposal): string {
    const body = {
      proposalId: proposal.proposalId,
      kind: proposal.kind,
      title: proposal.title,
      description: proposal.description,
      author: proposal.author,
      targetPath: proposal.targetPath,
      diff: proposal.diff,
      rationale: proposal.rationale,
      riskAssessment: proposal.riskAssessment,
      createdAt: proposal.createdAt,
    };
    const payload = JSON.stringify(body);
    return createHmac('sha256', this.signingKey).update(payload).digest('hex');
  }

  /**
   * Compute a composite hash from an array of trace hashes.
   */
  private hashTraceResults(traceHashes: string[]): string {
    const payload = traceHashes.join(':');
    return createHash('sha256').update(payload).digest('hex');
  }

  /**
   * Classify how severe a single decision diff is.
   */
  private classifyDiffSeverity(
    baseline: unknown,
    candidate: unknown,
  ): 'low' | 'medium' | 'high' {
    // If one is undefined (extra/missing decision), it is high
    if (baseline === undefined || candidate === undefined) {
      return 'high';
    }

    const bStr = JSON.stringify(baseline);
    const cStr = JSON.stringify(candidate);

    // Very different lengths suggest structural changes
    if (Math.abs(bStr.length - cStr.length) > bStr.length * 0.5) {
      return 'high';
    }

    // Moderate difference
    if (bStr.length > 0 && Math.abs(bStr.length - cStr.length) > bStr.length * 0.2) {
      return 'medium';
    }

    return 'low';
  }

  /**
   * Compute an overall divergence score (0-1).
   */
  private computeDivergenceScore(
    baselineHash: string,
    candidateHash: string,
    diffs: DecisionDiff[],
    traceCount: number,
  ): number {
    // If hashes are identical, divergence = 0
    if (baselineHash === candidateHash) {
      return 0;
    }

    // If there are no golden traces, treat as fully divergent
    if (traceCount === 0) {
      return 1;
    }

    // Weight diffs by severity
    const severityWeights: Record<string, number> = {
      low: 0.1,
      medium: 0.4,
      high: 1.0,
    };

    const totalWeight = diffs.reduce(
      (sum, d) => sum + (severityWeights[d.severity] ?? 0.5),
      0,
    );

    // Normalize: max possible weight is traceCount * maxDecisionsPerTrace
    // Use a heuristic cap to keep score in [0, 1]
    const maxExpected = traceCount * 5; // assume ~5 decisions per trace at max weight
    const raw = totalWeight / Math.max(maxExpected, 1);

    return Math.min(1, Math.max(0, raw));
  }

  /**
   * Aggregate an array of metric records into averages.
   */
  private aggregateMetrics(records: Record<string, number>[]): Record<string, number> {
    if (records.length === 0) return {};

    const sums: Record<string, number> = {};
    const counts: Record<string, number> = {};

    for (const record of records) {
      for (const [key, value] of Object.entries(record)) {
        sums[key] = (sums[key] ?? 0) + value;
        counts[key] = (counts[key] ?? 0) + 1;
      }
    }

    const result: Record<string, number> = {};
    for (const key of Object.keys(sums)) {
      result[key] = sums[key] / counts[key];
    }
    return result;
  }

  /**
   * Find the rollout associated with a proposal.
   */
  private findRolloutByProposal(proposalId: string): StagedRollout | undefined {
    for (const rollout of this.rollouts.values()) {
      if (rollout.proposalId === proposalId) {
        return rollout;
      }
    }
    return undefined;
  }
}

// ============================================================================
// Factory
// ============================================================================

/**
 * Create an EvolutionPipeline instance.
 */
export function createEvolutionPipeline(
  config?: EvolutionPipelineConfig,
): EvolutionPipeline {
  return new EvolutionPipeline(config);
}

/**
 * Hook-based Enforcement Gates
 *
 * Uses Claude Flow hooks to enforce non-negotiable rules.
 * The model can forget. The hook does not.
 *
 * Gates:
 * 1. Destructive ops gate - requires confirmation + rollback plan
 * 2. Tool allowlist gate - blocks non-allowlisted tools
 * 3. Diff size gate - requires plan + staged commits for large diffs
 * 4. Secrets gate - redacts and warns on secret patterns
 *
 * @module @claude-flow/guidance/gates
 */

import type {
  GateConfig,
  GateResult,
  GateDecision,
  GuidanceRule,
} from './types.js';

// ============================================================================
// Default Configuration
// ============================================================================

const DEFAULT_GATE_CONFIG: GateConfig = {
  destructiveOps: true,
  toolAllowlist: false,
  diffSize: true,
  secrets: true,
  diffSizeThreshold: 300,
  allowedTools: [],
  secretPatterns: [
    /(?:api[_-]?key|apikey)\s*[:=]\s*['"][^'"]{8,}['"]/gi,
    /(?:secret|password|passwd|pwd)\s*[:=]\s*['"][^'"]{4,}['"]/gi,
    /(?:token|bearer)\s*[:=]\s*['"][^'"]{10,}['"]/gi,
    /-----BEGIN (?:RSA |EC |DSA )?PRIVATE KEY-----/g,
    /sk-[a-zA-Z0-9]{20,}/g,
    /ghp_[a-zA-Z0-9]{36}/g,
    /npm_[a-zA-Z0-9]{36}/g,
    /AKIA[0-9A-Z]{16}/g,
  ],
  destructivePatterns: [
    /\brm\s+-rf?\b/i,
    /\bdrop\s+(database|table|schema|index)\b/i,
    /\btruncate\s+table\b/i,
    /\bgit\s+push\s+.*--force\b/i,
    /\bgit\s+reset\s+--hard\b/i,
    /\bgit\s+clean\s+-fd?\b/i,
    /\bformat\s+[a-z]:/i,
    /\bdel\s+\/[sf]\b/i,
    /\b(?:kubectl|helm)\s+delete\s+(?:--all|namespace)\b/i,
    /\bDROP\s+(?:DATABASE|TABLE|SCHEMA)\b/i,
    /\bDELETE\s+FROM\s+\w+\s*$/i,
    /\bALTER\s+TABLE\s+\w+\s+DROP\b/i,
  ],
};

/** Severity ranking for gate decisions (module-level constant to avoid per-call allocation). */
const GATE_DECISION_SEVERITY: Record<GateDecision, number> = {
  'block': 3,
  'require-confirmation': 2,
  'warn': 1,
  'allow': 0,
};

// ============================================================================
// Enforcement Gates
// ============================================================================

export class EnforcementGates {
  private config: GateConfig;
  private activeRules: GuidanceRule[] = [];

  constructor(config: Partial<GateConfig> = {}) {
    this.config = { ...DEFAULT_GATE_CONFIG, ...config };
  }

  /**
   * Update active rules from retrieval
   */
  setActiveRules(rules: GuidanceRule[]): void {
    this.activeRules = rules;
  }

  /**
   * Update configuration
   */
  updateConfig(config: Partial<GateConfig>): void {
    this.config = { ...this.config, ...config };
  }

  /**
   * Evaluate all gates for a command
   */
  evaluateCommand(command: string): GateResult[] {
    const results: GateResult[] = [];

    if (this.config.destructiveOps) {
      const result = this.evaluateDestructiveOps(command);
      if (result) results.push(result);
    }

    if (this.config.secrets) {
      const result = this.evaluateSecrets(command);
      if (result) results.push(result);
    }

    return results;
  }

  /**
   * Evaluate all gates for a tool use
   */
  evaluateToolUse(toolName: string, params: Record<string, unknown>): GateResult[] {
    const results: GateResult[] = [];

    if (this.config.toolAllowlist && this.config.allowedTools.length > 0) {
      const result = this.evaluateToolAllowlist(toolName);
      if (result) results.push(result);
    }

    // Check tool params for secrets
    if (this.config.secrets) {
      const serialized = JSON.stringify(params);
      const result = this.evaluateSecrets(serialized);
      if (result) results.push(result);
    }

    return results;
  }

  /**
   * Evaluate all gates for a file edit
   */
  evaluateEdit(filePath: string, content: string, diffLines: number): GateResult[] {
    const results: GateResult[] = [];

    if (this.config.diffSize) {
      const result = this.evaluateDiffSize(filePath, diffLines);
      if (result) results.push(result);
    }

    if (this.config.secrets) {
      const result = this.evaluateSecrets(content);
      if (result) results.push(result);
    }

    return results;
  }

  // ===== Individual Gate Implementations =====

  /**
   * Gate 1: Destructive Operations
   *
   * If command includes delete, drop, rm, force, migration,
   * require explicit confirmation and a rollback plan.
   */
  evaluateDestructiveOps(command: string): GateResult | null {
    for (const pattern of this.config.destructivePatterns) {
      // Reset lastIndex for global regex
      pattern.lastIndex = 0;
      const match = pattern.exec(command);
      if (match) {
        const triggeredRules = this.findTriggeredRules('security', 'critical');

        return {
          decision: 'require-confirmation',
          gateName: 'destructive-ops',
          reason: `Destructive operation detected: "${match[0]}". Requires explicit confirmation and a rollback plan before proceeding.`,
          triggeredRules: triggeredRules.map(r => r.id),
          remediation: [
            '1. Confirm this operation is intentional',
            '2. Document the rollback plan (e.g., git ref, backup, undo command)',
            '3. If this is a migration, ensure it has a down/rollback step',
          ].join('\n'),
          metadata: {
            matchedPattern: match[0],
            fullCommand: command,
          },
        };
      }
    }

    return null;
  }

  /**
   * Gate 2: Tool Allowlist
   *
   * If tool not in allowlist, block and ask for permission.
   */
  evaluateToolAllowlist(toolName: string): GateResult | null {
    if (this.config.allowedTools.length === 0) return null;

    const allowed = this.config.allowedTools.some(t =>
      t === toolName || t === '*' || (t.endsWith('*') && toolName.startsWith(t.slice(0, -1)))
    );

    if (!allowed) {
      return {
        decision: 'block',
        gateName: 'tool-allowlist',
        reason: `Tool "${toolName}" is not in the allowlist. Request permission before using this tool.`,
        triggeredRules: this.findTriggeredRules('security').map(r => r.id),
        remediation: `Add "${toolName}" to the tool allowlist in gate configuration, or get explicit user approval.`,
        metadata: {
          blockedTool: toolName,
          allowedTools: this.config.allowedTools,
        },
      };
    }

    return null;
  }

  /**
   * Gate 3: Diff Size
   *
   * If patch exceeds threshold, require a plan and staged commits.
   */
  evaluateDiffSize(filePath: string, diffLines: number): GateResult | null {
    if (diffLines <= this.config.diffSizeThreshold) return null;

    return {
      decision: 'warn',
      gateName: 'diff-size',
      reason: `Diff for "${filePath}" is ${diffLines} lines (threshold: ${this.config.diffSizeThreshold}). Large changes should be planned and staged.`,
      triggeredRules: this.findTriggeredRules('architecture').map(r => r.id),
      remediation: [
        '1. Create a plan breaking this change into logical commits',
        '2. Stage changes incrementally (one concern per commit)',
        '3. Run tests after each staged commit',
        '4. Consider if this change should be split into multiple PRs',
      ].join('\n'),
      metadata: {
        filePath,
        diffLines,
        threshold: this.config.diffSizeThreshold,
      },
    };
  }

  /**
   * Gate 4: Secrets Detection
   *
   * If output matches secret patterns, redact and warn.
   */
  evaluateSecrets(content: string): GateResult | null {
    const detectedSecrets: string[] = [];

    for (const pattern of this.config.secretPatterns) {
      // Reset lastIndex for global regex
      pattern.lastIndex = 0;
      const matches = content.match(pattern);
      if (matches) {
        for (const match of matches) {
          // Redact the secret (show first 4 and last 4 chars)
          const redacted = match.length > 12
            ? `${match.slice(0, 4)}${'*'.repeat(match.length - 8)}${match.slice(-4)}`
            : '*'.repeat(match.length);
          detectedSecrets.push(redacted);
        }
      }
    }

    if (detectedSecrets.length === 0) return null;

    return {
      decision: 'block',
      gateName: 'secrets',
      reason: `Detected ${detectedSecrets.length} potential secret(s) in content. Secrets must not be committed or exposed.`,
      triggeredRules: this.findTriggeredRules('security', 'critical').map(r => r.id),
      remediation: [
        '1. Move secrets to environment variables',
        '2. Use .env files (ensure they are in .gitignore)',
        '3. Use a secret management service for production',
        `Detected patterns: ${detectedSecrets.join(', ')}`,
      ].join('\n'),
      metadata: {
        secretCount: detectedSecrets.length,
        redactedSecrets: detectedSecrets,
      },
    };
  }

  // ===== Aggregate Evaluation =====

  /**
   * Get the most restrictive decision from multiple gate results
   */
  aggregateDecision(results: GateResult[]): GateDecision {
    if (results.length === 0) return 'allow';

    let maxSeverity = 0;
    let worstDecision: GateDecision = 'allow';

    for (const result of results) {
      const s = GATE_DECISION_SEVERITY[result.decision];
      if (s > maxSeverity) {
        maxSeverity = s;
        worstDecision = result.decision;
      }
    }

    return worstDecision;
  }

  /**
   * Get gate statistics
   */
  getActiveGateCount(): number {
    let count = 0;
    if (this.config.destructiveOps) count++;
    if (this.config.toolAllowlist && this.config.allowedTools.length > 0) count++;
    if (this.config.diffSize) count++;
    if (this.config.secrets) count++;
    return count;
  }

  // ===== Helpers =====

  private findTriggeredRules(domain: string, riskClass?: string): GuidanceRule[] {
    return this.activeRules.filter(r => {
      const domainMatch = r.domains.includes(domain);
      const riskMatch = !riskClass || r.riskClass === riskClass;
      return domainMatch && riskMatch;
    });
  }
}

/**
 * Create enforcement gates
 */
export function createGates(config?: Partial<GateConfig>): EnforcementGates {
  return new EnforcementGates(config);
}

/**
 * Deterministic Tool Gateway
 *
 * Extends EnforcementGates with idempotency, schema validation,
 * and budget metering. Every tool call passes through a deterministic
 * pipeline: idempotency check -> schema validation -> budget check ->
 * enforcement gates -> allow/deny.
 *
 * @module @claude-flow/guidance/gateway
 */

import { createHash } from 'node:crypto';
import { EnforcementGates } from './gates.js';
import type { GateConfig } from './types.js';

// ============================================================================
// Types
// ============================================================================

/**
 * Schema definition for a tool's parameters
 */
export interface ToolSchema {
  /** Tool name this schema applies to */
  toolName: string;
  /** Parameters that must be present */
  requiredParams: string[];
  /** Parameters that may be present */
  optionalParams: string[];
  /** Expected type for each parameter */
  paramTypes: Record<string, 'string' | 'number' | 'boolean' | 'object' | 'array'>;
  /** Maximum total serialized size of all parameters in bytes */
  maxParamSize: number;
  /** Optional whitelist of allowed values per parameter */
  allowedValues?: Record<string, unknown[]>;
}

/**
 * Multi-dimensional budget tracking
 */
export interface Budget {
  tokenBudget: { used: number; limit: number };
  toolCallBudget: { used: number; limit: number };
  storageBudget: { usedBytes: number; limitBytes: number };
  timeBudget: { usedMs: number; limitMs: number };
  costBudget: { usedUsd: number; limitUsd: number };
}

/**
 * Record of a previous tool call for idempotency
 */
export interface IdempotencyRecord {
  /** SHA-256 of tool name + sorted params */
  key: string;
  /** Tool that was called */
  toolName: string;
  /** Hash of the parameters */
  paramsHash: string;
  /** Cached result from the call */
  result: unknown;
  /** When the call was recorded */
  timestamp: number;
  /** Time-to-live in milliseconds */
  ttlMs: number;
}

/**
 * Decision returned by the gateway for each tool call evaluation
 */
export interface GatewayDecision {
  /** Whether the call is allowed */
  allowed: boolean;
  /** Human-readable reason for the decision */
  reason: string;
  /** Which gate produced the decision (or 'none' if allowed) */
  gate: string;
  /** Evidence of what was checked */
  evidence: Record<string, unknown>;
  /** Whether an idempotency cache hit occurred */
  idempotencyHit: boolean;
  /** Cached result if idempotency hit */
  cachedResult?: unknown;
  /** Remaining budget after this decision */
  budgetRemaining?: Budget;
}

// ============================================================================
// Default Budget
// ============================================================================

const DEFAULT_BUDGET: Budget = {
  tokenBudget: { used: 0, limit: Infinity },
  toolCallBudget: { used: 0, limit: Infinity },
  storageBudget: { usedBytes: 0, limitBytes: Infinity },
  timeBudget: { usedMs: 0, limitMs: Infinity },
  costBudget: { usedUsd: 0, limitUsd: Infinity },
};

// ============================================================================
// Gateway Configuration
// ============================================================================

export interface ToolGatewayConfig {
  /** Tool schemas for validation */
  schemas?: ToolSchema[];
  /** Budget limits (partial; defaults to Infinity for unset dimensions) */
  budget?: Partial<Budget>;
  /** Default TTL for idempotency records in milliseconds */
  idempotencyTtlMs?: number;
  /** Maximum idempotency cache entries (default 10000) */
  maxCacheSize?: number;
  /** If true, evidence must be non-empty for allow decisions */
  requireEvidence?: boolean;
  /** Gate configuration passed through to EnforcementGates */
  gateConfig?: Partial<GateConfig>;
}

// ============================================================================
// Deterministic Tool Gateway
// ============================================================================

export class DeterministicToolGateway {
  private readonly gates: EnforcementGates;
  private readonly schemas: Map<string, ToolSchema>;
  private budget: Budget;
  private readonly idempotencyTtlMs: number;
  private readonly maxCacheSize: number;
  private readonly requireEvidence: boolean;
  private readonly idempotencyCache: Map<string, IdempotencyRecord> = new Map();
  private lastCleanupTime = 0;
  private static readonly CLEANUP_INTERVAL_MS = 30_000; // batch cleanup every 30s

  constructor(config: ToolGatewayConfig = {}) {
    this.gates = new EnforcementGates(config.gateConfig);

    // Index schemas by tool name
    this.schemas = new Map();
    if (config.schemas) {
      for (const schema of config.schemas) {
        this.schemas.set(schema.toolName, schema);
      }
    }

    // Merge partial budget with defaults
    this.budget = this.mergeBudget(config.budget);
    this.idempotencyTtlMs = config.idempotencyTtlMs ?? 300_000; // 5 minutes default
    this.maxCacheSize = config.maxCacheSize ?? 10_000;
    this.requireEvidence = config.requireEvidence ?? false;
  }

  // =========================================================================
  // Public API
  // =========================================================================

  /**
   * Evaluate whether a tool call should be allowed.
   *
   * Pipeline:
   * 1. Check idempotency cache
   * 2. Validate params against schema
   * 3. Check budget
   * 4. Run EnforcementGates checks
   * 5. Return decision with remaining budget
   */
  evaluate(
    toolName: string,
    params: Record<string, unknown>,
    context?: Record<string, unknown>,
  ): GatewayDecision {
    const evidence: Record<string, unknown> = {};

    // Step 1: Idempotency check (batch cleanup on interval, not every call)
    this.maybeCleanExpiredIdempotency();
    const idempotencyKey = this.getIdempotencyKey(toolName, params);
    const cached = this.idempotencyCache.get(idempotencyKey);

    if (cached) {
      return {
        allowed: true,
        reason: 'Idempotency cache hit; returning cached result',
        gate: 'idempotency',
        evidence: { idempotencyKey, cachedAt: cached.timestamp },
        idempotencyHit: true,
        cachedResult: cached.result,
        budgetRemaining: this.cloneBudget(),
      };
    }

    evidence.idempotencyKey = idempotencyKey;
    evidence.idempotencyHit = false;

    // Step 2: Schema validation
    const schemaResult = this.validateSchema(toolName, params);
    evidence.schemaValidation = schemaResult;

    if (!schemaResult.valid) {
      return {
        allowed: false,
        reason: `Schema validation failed: ${schemaResult.errors.join('; ')}`,
        gate: 'schema-validation',
        evidence,
        idempotencyHit: false,
      };
    }

    // Step 3: Budget check
    const budgetStatus = this.checkBudget();
    evidence.budgetStatus = budgetStatus;

    if (!budgetStatus.withinBudget) {
      const exceeded = this.findExceededBudgets();
      return {
        allowed: false,
        reason: `Budget exceeded: ${exceeded.join(', ')}`,
        gate: 'budget',
        evidence,
        idempotencyHit: false,
        budgetRemaining: this.cloneBudget(),
      };
    }

    // Step 4: EnforcementGates checks
    const gateResults = this.gates.evaluateToolUse(toolName, params);
    evidence.gateResults = gateResults;

    if (gateResults.length > 0) {
      const aggregated = this.gates.aggregateDecision(gateResults);

      if (aggregated === 'block') {
        const blockResult = gateResults.find(r => r.decision === 'block')!;
        return {
          allowed: false,
          reason: blockResult.reason,
          gate: `enforcement:${blockResult.gateName}`,
          evidence,
          idempotencyHit: false,
          budgetRemaining: this.cloneBudget(),
        };
      }

      if (aggregated === 'require-confirmation') {
        const confirmResult = gateResults.find(r => r.decision === 'require-confirmation')!;
        return {
          allowed: false,
          reason: confirmResult.reason,
          gate: `enforcement:${confirmResult.gateName}`,
          evidence,
          idempotencyHit: false,
          budgetRemaining: this.cloneBudget(),
        };
      }

      // 'warn' still allows, but note it in evidence
      evidence.warnings = gateResults
        .filter(r => r.decision === 'warn')
        .map(r => r.reason);
    }

    // Also run command-level checks if context provides a command string
    if (context?.command && typeof context.command === 'string') {
      const commandResults = this.gates.evaluateCommand(context.command);
      evidence.commandGateResults = commandResults;

      if (commandResults.length > 0) {
        const aggregated = this.gates.aggregateDecision(commandResults);
        if (aggregated === 'block' || aggregated === 'require-confirmation') {
          const worst = commandResults.find(
            r => r.decision === aggregated,
          )!;
          return {
            allowed: false,
            reason: worst.reason,
            gate: `enforcement:${worst.gateName}`,
            evidence,
            idempotencyHit: false,
            budgetRemaining: this.cloneBudget(),
          };
        }
      }
    }

    // Step 5: Allow
    return {
      allowed: true,
      reason: 'All gates passed',
      gate: 'none',
      evidence,
      idempotencyHit: false,
      budgetRemaining: this.cloneBudget(),
    };
  }

  /**
   * Record a completed tool call.
   * Updates budgets and stores the result in the idempotency cache.
   */
  recordCall(
    toolName: string,
    params: Record<string, unknown>,
    result: unknown,
    durationMs: number,
    tokenCount?: number,
  ): void {
    // Update budgets
    this.budget.toolCallBudget.used += 1;
    this.budget.timeBudget.usedMs += durationMs;

    if (tokenCount !== undefined) {
      this.budget.tokenBudget.used += tokenCount;
    }

    // Estimate storage from serialized result
    const serialized = JSON.stringify(result) ?? '';
    this.budget.storageBudget.usedBytes += Buffer.byteLength(serialized, 'utf-8');

    // Estimate cost: simple heuristic based on tokens
    if (tokenCount !== undefined) {
      // Rough estimate: $0.003 per 1K tokens (configurable in production)
      this.budget.costBudget.usedUsd += (tokenCount / 1000) * 0.003;
    }

    // Store in idempotency cache with size-based eviction
    const key = this.getIdempotencyKey(toolName, params);
    const paramsHash = this.computeParamsHash(params);

    this.idempotencyCache.set(key, {
      key,
      toolName,
      paramsHash,
      result,
      timestamp: Date.now(),
      ttlMs: this.idempotencyTtlMs,
    });

    // Evict oldest entries if cache exceeds max size
    if (this.idempotencyCache.size > this.maxCacheSize) {
      // Map iterates in insertion order; delete the first (oldest) entries
      const excess = this.idempotencyCache.size - this.maxCacheSize;
      let removed = 0;
      for (const [k] of this.idempotencyCache) {
        if (removed >= excess) break;
        this.idempotencyCache.delete(k);
        removed++;
      }
    }
  }

  /**
   * Validate tool parameters against the registered schema.
   * Returns valid:true if no schema is registered for the tool.
   */
  validateSchema(
    toolName: string,
    params: Record<string, unknown>,
  ): { valid: boolean; errors: string[] } {
    const schema = this.schemas.get(toolName);

    if (!schema) {
      // No schema registered; pass through
      return { valid: true, errors: [] };
    }

    const errors: string[] = [];

    // Check required params
    for (const required of schema.requiredParams) {
      if (!(required in params) || params[required] === undefined) {
        errors.push(`Missing required parameter: "${required}"`);
      }
    }

    // Check for unknown params
    const knownParams = new Set([...schema.requiredParams, ...schema.optionalParams]);
    for (const key of Object.keys(params)) {
      if (!knownParams.has(key)) {
        errors.push(`Unknown parameter: "${key}"`);
      }
    }

    // Check param types
    for (const [key, expectedType] of Object.entries(schema.paramTypes)) {
      if (!(key in params) || params[key] === undefined) continue;

      const value = params[key];
      const actualType = this.getParamType(value);

      if (actualType !== expectedType) {
        errors.push(
          `Parameter "${key}" expected type "${expectedType}" but got "${actualType}"`,
        );
      }
    }

    // Check param size
    const serialized = JSON.stringify(params);
    const sizeBytes = Buffer.byteLength(serialized, 'utf-8');
    if (sizeBytes > schema.maxParamSize) {
      errors.push(
        `Parameters size ${sizeBytes} bytes exceeds limit of ${schema.maxParamSize} bytes`,
      );
    }

    // Check allowed values
    if (schema.allowedValues) {
      for (const [key, allowed] of Object.entries(schema.allowedValues)) {
        if (!(key in params) || params[key] === undefined) continue;

        const value = params[key];
        const isAllowed = allowed.some(
          a => JSON.stringify(a) === JSON.stringify(value),
        );

        if (!isAllowed) {
          errors.push(
            `Parameter "${key}" value ${JSON.stringify(value)} is not in the allowed values list`,
          );
        }
      }
    }

    return { valid: errors.length === 0, errors };
  }

  /**
   * Check whether all budget dimensions are within limits.
   */
  checkBudget(): { withinBudget: boolean; budgetStatus: Budget } {
    const b = this.budget;

    const withinBudget =
      b.tokenBudget.used <= b.tokenBudget.limit &&
      b.toolCallBudget.used <= b.toolCallBudget.limit &&
      b.storageBudget.usedBytes <= b.storageBudget.limitBytes &&
      b.timeBudget.usedMs <= b.timeBudget.limitMs &&
      b.costBudget.usedUsd <= b.costBudget.limitUsd;

    return { withinBudget, budgetStatus: this.cloneBudget() };
  }

  /**
   * Compute a deterministic idempotency key from tool name and params.
   * Uses SHA-256 of `toolName:sortedParamsJSON`.
   */
  getIdempotencyKey(toolName: string, params: Record<string, unknown>): string {
    return this.computeIdempotencyKey(toolName, params);
  }

  /**
   * Reset all budget counters to zero.
   */
  resetBudget(): void {
    this.budget.tokenBudget.used = 0;
    this.budget.toolCallBudget.used = 0;
    this.budget.storageBudget.usedBytes = 0;
    this.budget.timeBudget.usedMs = 0;
    this.budget.costBudget.usedUsd = 0;
  }

  /**
   * Get a snapshot of the current budget.
   */
  getBudget(): Budget {
    return this.cloneBudget();
  }

  /**
   * Get all idempotency records (including expired ones not yet cleaned).
   */
  getCallHistory(): IdempotencyRecord[] {
    return Array.from(this.idempotencyCache.values());
  }

  /**
   * Access the underlying EnforcementGates instance.
   */
  getGates(): EnforcementGates {
    return this.gates;
  }

  // =========================================================================
  // Private helpers
  // =========================================================================

  /**
   * Remove expired idempotency records (batched on interval to avoid per-call overhead).
   */
  private maybeCleanExpiredIdempotency(): void {
    const now = Date.now();
    if (now - this.lastCleanupTime < DeterministicToolGateway.CLEANUP_INTERVAL_MS) {
      return; // Skip cleanup until interval has passed
    }
    this.lastCleanupTime = now;

    for (const [key, record] of this.idempotencyCache) {
      if (now - record.timestamp > record.ttlMs) {
        this.idempotencyCache.delete(key);
      }
    }
  }

  /**
   * Compute a deterministic SHA-256 key from tool name and sorted params.
   */
  private computeIdempotencyKey(
    toolName: string,
    params: Record<string, unknown>,
  ): string {
    const sortedParams = this.sortObject(params);
    const input = `${toolName}:${JSON.stringify(sortedParams)}`;
    return createHash('sha256').update(input).digest('hex');
  }

  /**
   * Compute a SHA-256 hash of params only (for the IdempotencyRecord).
   */
  private computeParamsHash(params: Record<string, unknown>): string {
    const sortedParams = this.sortObject(params);
    return createHash('sha256').update(JSON.stringify(sortedParams)).digest('hex');
  }

  /**
   * Recursively sort object keys for deterministic serialization.
   */
  private sortObject(obj: unknown): unknown {
    if (obj === null || obj === undefined) return obj;
    if (Array.isArray(obj)) return obj.map(item => this.sortObject(item));
    if (typeof obj === 'object') {
      const sorted: Record<string, unknown> = {};
      for (const key of Object.keys(obj as Record<string, unknown>).sort()) {
        sorted[key] = this.sortObject((obj as Record<string, unknown>)[key]);
      }
      return sorted;
    }
    return obj;
  }

  /**
   * Determine the type string for a parameter value.
   */
  private getParamType(value: unknown): string {
    if (Array.isArray(value)) return 'array';
    if (value === null) return 'object';
    return typeof value;
  }

  /**
   * Create a deep clone of the current budget.
   */
  private cloneBudget(): Budget {
    return {
      tokenBudget: { ...this.budget.tokenBudget },
      toolCallBudget: { ...this.budget.toolCallBudget },
      storageBudget: { ...this.budget.storageBudget },
      timeBudget: { ...this.budget.timeBudget },
      costBudget: { ...this.budget.costBudget },
    };
  }

  /**
   * Merge a partial budget config with defaults.
   */
  private mergeBudget(partial?: Partial<Budget>): Budget {
    if (!partial) return this.cloneDefaultBudget();

    return {
      tokenBudget: partial.tokenBudget
        ? { ...DEFAULT_BUDGET.tokenBudget, ...partial.tokenBudget }
        : { ...DEFAULT_BUDGET.tokenBudget },
      toolCallBudget: partial.toolCallBudget
        ? { ...DEFAULT_BUDGET.toolCallBudget, ...partial.toolCallBudget }
        : { ...DEFAULT_BUDGET.toolCallBudget },
      storageBudget: partial.storageBudget
        ? { ...DEFAULT_BUDGET.storageBudget, ...partial.storageBudget }
        : { ...DEFAULT_BUDGET.storageBudget },
      timeBudget: partial.timeBudget
        ? { ...DEFAULT_BUDGET.timeBudget, ...partial.timeBudget }
        : { ...DEFAULT_BUDGET.timeBudget },
      costBudget: partial.costBudget
        ? { ...DEFAULT_BUDGET.costBudget, ...partial.costBudget }
        : { ...DEFAULT_BUDGET.costBudget },
    };
  }

  private cloneDefaultBudget(): Budget {
    return {
      tokenBudget: { ...DEFAULT_BUDGET.tokenBudget },
      toolCallBudget: { ...DEFAULT_BUDGET.toolCallBudget },
      storageBudget: { ...DEFAULT_BUDGET.storageBudget },
      timeBudget: { ...DEFAULT_BUDGET.timeBudget },
      costBudget: { ...DEFAULT_BUDGET.costBudget },
    };
  }

  /**
   * Find which budget dimensions have been exceeded.
   */
  private findExceededBudgets(): string[] {
    const exceeded: string[] = [];
    const b = this.budget;

    if (b.tokenBudget.used > b.tokenBudget.limit) {
      exceeded.push(`tokens (${b.tokenBudget.used}/${b.tokenBudget.limit})`);
    }
    if (b.toolCallBudget.used > b.toolCallBudget.limit) {
      exceeded.push(`tool calls (${b.toolCallBudget.used}/${b.toolCallBudget.limit})`);
    }
    if (b.storageBudget.usedBytes > b.storageBudget.limitBytes) {
      exceeded.push(`storage (${b.storageBudget.usedBytes}/${b.storageBudget.limitBytes} bytes)`);
    }
    if (b.timeBudget.usedMs > b.timeBudget.limitMs) {
      exceeded.push(`time (${b.timeBudget.usedMs}/${b.timeBudget.limitMs} ms)`);
    }
    if (b.costBudget.usedUsd > b.costBudget.limitUsd) {
      exceeded.push(`cost ($${b.costBudget.usedUsd.toFixed(4)}/$${b.costBudget.limitUsd.toFixed(4)})`);
    }

    return exceeded;
  }
}

