  /** Package manager */
  packageManager?: 'npm' | 'pnpm' | 'yarn' | 'bun';
  /** Monorepo? */
  monorepo?: boolean;
  /** Build command */
  buildCommand?: string;
  /** Test command */
  testCommand?: string;
  /** Lint command */
  lintCommand?: string;
  /** Source directory */
  srcDir?: string;
  /** Test directory */
  testDir?: string;
  /** Domain-specific rules */
  domainRules?: string[];
  /** Architecture notes */
  architecture?: string;
  /** Team conventions */
  conventions?: string[];
  /** Forbidden patterns */
  forbidden?: string[];
  /** Required patterns */
  required?: string[];
  /** Import paths for personal instructions */
  imports?: string[];
  /** Enable guidance control plane integration */
  guidanceControlPlane?: boolean;
