  rootGuidancePath: './CLAUDE.md',
  localGuidancePath: './CLAUDE.local.md',
  gates: {},
  maxShardsPerTask: 5,
  optimizationCycleDays: 7,
  dataDir: './.claude-flow/guidance',
  headlessMode: false,
};

// ============================================================================
// Guidance Control Plane
// ============================================================================

/**
 * The main Guidance Control Plane
 *
 * Orchestrates all components:
 * - Compiler: CLAUDE.md → PolicyBundle
 * - Retriever: PolicyBundle → task-relevant shards
 * - Gates: enforcement hooks
 * - Ledger: run logging + evaluation
 * - Optimizer: rule evolution
 * - Headless: automated testing
 */
export class GuidanceControlPlane {
  private config: GuidanceControlPlaneConfig;
  private compiler: GuidanceCompiler;
  private retriever: ShardRetriever;
  private gates: EnforcementGates;
  private ledger: RunLedger;
  private optimizer: OptimizerLoop;
  private headless: HeadlessRunner | null = null;

  private bundle: PolicyBundle | null = null;
  private initialized = false;

  constructor(config: Partial<GuidanceControlPlaneConfig> = {}) {
    this.config = { ...DEFAULT_CONFIG, ...config };

    this.compiler = createCompiler();
    this.retriever = createRetriever();
    this.gates = createGates(this.config.gates);
    this.ledger = createLedger();
    this.optimizer = createOptimizer();
  }

  /**
   * Initialize the control plane
   *
   * 1. Read and compile guidance files
   * 2. Load shards into retriever
   * 3. Configure gates
   * 4. Set up headless runner if enabled
   */
  async initialize(): Promise<void> {
    if (this.initialized) return;

    // Step 1: Read guidance files
    const rootContent = await this.readGuidanceFile(this.config.rootGuidancePath);
    const localContent = this.config.localGuidancePath
      ? await this.readGuidanceFile(this.config.localGuidancePath)
      : undefined;

    if (!rootContent) {
      throw new Error(`Root guidance file not found: ${this.config.rootGuidancePath}`);
    }

    // Step 2: Compile
    this.bundle = this.compiler.compile(rootContent, localContent ?? undefined);

    // Step 3: Load into retriever
    await this.retriever.loadBundle(this.bundle);

    // Step 4: Set active rules on gates
    const allRules = [
      ...this.bundle.constitution.rules,
      ...this.bundle.shards.map(s => s.rule),
    ];
    this.gates.setActiveRules(allRules);

    // Step 5: Set up headless runner if enabled
    if (this.config.headlessMode) {
      this.headless = createHeadlessRunner(undefined, this.ledger, this.bundle.constitution.hash);
    }

    this.initialized = true;
  }

  /**
   * Compile guidance files (can be called independently)
   */
  async compile(rootContent: string, localContent?: string): Promise<PolicyBundle> {
    this.bundle = this.compiler.compile(rootContent, localContent);
    await this.retriever.loadBundle(this.bundle);

    const allRules = [
      ...this.bundle.constitution.rules,
      ...this.bundle.shards.map(s => s.rule),
    ];
    this.gates.setActiveRules(allRules);

    // Mark as initialized since we have a valid bundle
    this.initialized = true;

    return this.bundle;
  }

  /**
   * Retrieve relevant guidance for a task
   *
   * This is the main entry point called at task start.
   * Returns the constitution + relevant shards.
   */
  async retrieveForTask(request: RetrievalRequest): Promise<RetrievalResult> {
    this.ensureInitialized();
    return this.retriever.retrieve({
      ...request,
      maxShards: request.maxShards ?? this.config.maxShardsPerTask,
    });
  }

  /**
   * Evaluate a command through enforcement gates
   */
  evaluateCommand(command: string): GateResult[] {
    return this.gates.evaluateCommand(command);
  }

  /**
   * Evaluate a tool use through enforcement gates
   */
  evaluateToolUse(toolName: string, params: Record<string, unknown>): GateResult[] {
    return this.gates.evaluateToolUse(toolName, params);
  }

  /**
   * Evaluate a file edit through enforcement gates
   */
  evaluateEdit(filePath: string, content: string, diffLines: number): GateResult[] {
    return this.gates.evaluateEdit(filePath, content, diffLines);
  }

  /**
   * Start a run event for tracking
   */
  startRun(taskId: string, intent: TaskIntent): RunEvent {
    this.ensureInitialized();
    const event = this.ledger.createEvent(
      taskId,
      intent,
      this.bundle?.constitution.hash ?? 'unknown'
    );
    return event;
  }

  /**
   * Record a violation during a run
   */
  recordViolation(event: RunEvent, violation: Violation): void {
    event.violations.push(violation);
  }

  /**
   * Finalize a run and evaluate it
   */
  async finalizeRun(event: RunEvent): Promise<EvaluatorResult[]> {
    this.ledger.finalizeEvent(event);
    return this.ledger.evaluate(event);
  }

  /**
   * Run the optimization cycle
   */
  async optimize(): Promise<{
    promoted: string[];
    demoted: string[];
    adrsCreated: number;
  }> {
    this.ensureInitialized();

    if (this.ledger.eventCount < 10) {
      return { promoted: [], demoted: [], adrsCreated: 0 };
    }

    const result = await this.optimizer.runCycle(this.ledger, this.bundle!);

    // Apply promotions
    if (result.promoted.length > 0) {
      this.bundle = this.optimizer.applyPromotions(
        this.bundle!,
        result.promoted,
        result.changes
      );
      await this.retriever.loadBundle(this.bundle);
    }

    return {
      promoted: result.promoted,
      demoted: result.demoted,
      adrsCreated: result.adrs.length,
    };
  }

  /**
   * Get control plane status
   */
  getStatus(): ControlPlaneStatus {
    return {
      initialized: this.initialized,
      constitutionLoaded: this.bundle?.constitution != null,
      shardCount: this.retriever.shardCount,
      activeGates: this.gates.getActiveGateCount(),
      ledgerEventCount: this.ledger.eventCount,
      lastOptimizationRun: this.optimizer.lastRun,
      metrics: this.ledger.eventCount > 0
        ? this.ledger.computeMetrics()
        : null,
    };
  }

  /**
   * Get the current policy bundle
   */
  getBundle(): PolicyBundle | null {
    return this.bundle;
  }

  /**
   * Get the run ledger
   */
  getLedger(): RunLedger {
    return this.ledger;
  }

  /**
   * Get the optimizer
   */
  getOptimizer(): OptimizerLoop {
    return this.optimizer;
  }

  /**
   * Get the headless runner
   */
  getHeadlessRunner(): HeadlessRunner | null {
    return this.headless;
  }

  /**
   * Get metrics for benefit tracking
   */
  getMetrics(): {
    violationRatePer10Tasks: number;
    selfCorrectionRate: number;
    reworkLinesAvg: number;
    clarifyingQuestionsAvg: number;
    taskCount: number;
    topViolations: Array<{ ruleId: string; frequency: number; cost: number }>;
  } {
    const metrics = this.ledger.computeMetrics();
    const rankings = this.ledger.rankViolations();

    return {
      violationRatePer10Tasks: metrics.violationRate,
      selfCorrectionRate: metrics.selfCorrectionRate,
      reworkLinesAvg: metrics.reworkLines,
      clarifyingQuestionsAvg: metrics.clarifyingQuestions,
      taskCount: metrics.taskCount,
      topViolations: rankings.slice(0, 5).map(r => ({
        ruleId: r.ruleId,
        frequency: r.frequency,
        cost: r.cost,
      })),
    };
  }

  // ===== Private =====

  private async readGuidanceFile(path: string): Promise<string | null> {
    try {
      if (existsSync(path)) {
        return await readFile(path, 'utf-8');
      }
      return null;
    } catch {
      return null;
    }
  }

  private ensureInitialized(): void {
    if (!this.initialized) {
      throw new Error('GuidanceControlPlane not initialized. Call initialize() first.');
    }
  }
}

/**
 * Create a guidance control plane instance
 */
export function createGuidanceControlPlane(
  config?: Partial<GuidanceControlPlaneConfig>
): GuidanceControlPlane {
  return new GuidanceControlPlane(config);
}

/**
 * Quick setup: create and initialize the control plane
 */
export async function initializeGuidanceControlPlane(
  config?: Partial<GuidanceControlPlaneConfig>
): Promise<GuidanceControlPlane> {
  const plane = new GuidanceControlPlane(config);
  await plane.initialize();
  return plane;
}

export default GuidanceControlPlane;

/**
 * Run Ledger + Evaluators
 *
 * Logs every run as an event with a minimum schema, then runs evaluators
 * to assess compliance and quality.
 *
 * Objective evaluators:
 * 1. Tests pass
 * 2. Lint pass
 * 3. Forbidden dependency scan
 * 4. Forbidden command scan
 * 5. Required sections present in plan
 *
 * Subjective evaluators:
 * 1. Reviewer rating (pass/fail)
 * 2. Architecture compliance (pass/fail)
 *
 * @module @claude-flow/guidance/ledger
 */

import { randomUUID } from 'node:crypto';
import type {
  RunEvent,
  Violation,
  EvaluatorResult,
  TaskIntent,
  OptimizationMetrics,
  ViolationRanking,
} from './types.js';

// ============================================================================
// Evaluator Interface
// ============================================================================

export interface IEvaluator {
  /** Evaluator name */
  name: string;
  /** Whether this is objective (automated) or subjective (human) */
  type: 'objective' | 'subjective';
  /** Run the evaluation */
  evaluate(event: RunEvent): Promise<EvaluatorResult>;
}

// ============================================================================
// Built-in Evaluators
// ============================================================================

/**
 * Tests Pass evaluator - checks test results
 */
export class TestsPassEvaluator implements IEvaluator {
  name = 'tests-pass';
  type = 'objective' as const;

  async evaluate(event: RunEvent): Promise<EvaluatorResult> {
    if (!event.testResults.ran) {
      return {
        name: this.name,
        passed: false,
        details: 'Tests were not run during this task',
        score: 0,
      };
    }

    const passed = event.testResults.failed === 0;
    const total = event.testResults.passed + event.testResults.failed + event.testResults.skipped;

    return {
      name: this.name,
      passed,
      details: passed
        ? `All ${event.testResults.passed} tests passed (${event.testResults.skipped} skipped)`
        : `${event.testResults.failed} of ${total} tests failed`,
      score: total > 0 ? event.testResults.passed / total : 0,
    };
  }
}

/**
 * Forbidden command scan evaluator
 */
export class ForbiddenCommandEvaluator implements IEvaluator {
  name = 'forbidden-command-scan';
  type = 'objective' as const;
  private forbiddenPatterns: RegExp[];

  constructor(forbiddenPatterns?: RegExp[]) {
    this.forbiddenPatterns = forbiddenPatterns ?? [
      /\brm\s+-rf\s+\//,
      /\bgit\s+push\s+--force\s+origin\s+(?:main|master)\b/,
      /\bcurl\s+.*\|\s*(?:sh|bash)\b/,
      /\beval\s*\(/,
      /\bexec\s*\(/,
    ];
  }

  async evaluate(event: RunEvent): Promise<EvaluatorResult> {
    const violations: string[] = [];

    for (const tool of event.toolsUsed) {
      for (const pattern of this.forbiddenPatterns) {
        if (pattern.test(tool)) {
          violations.push(`Forbidden command pattern: ${pattern.source} matched in "${tool}"`);
        }
      }
    }

    return {
      name: this.name,
      passed: violations.length === 0,
      details: violations.length === 0
        ? 'No forbidden commands detected'
        : `Found ${violations.length} forbidden command(s): ${violations.join('; ')}`,
      score: violations.length === 0 ? 1 : 0,
    };
  }
}

/**
 * Forbidden dependency scan evaluator
 */
export class ForbiddenDependencyEvaluator implements IEvaluator {
  name = 'forbidden-dependency-scan';
  type = 'objective' as const;
  private forbiddenPackages: string[];

  constructor(forbiddenPackages?: string[]) {
    this.forbiddenPackages = forbiddenPackages ?? [];
  }

  async evaluate(event: RunEvent): Promise<EvaluatorResult> {
    if (this.forbiddenPackages.length === 0) {
      return { name: this.name, passed: true, details: 'No forbidden dependencies configured', score: 1 };
    }

    // Check if any forbidden packages were introduced in touched files
    const packageFiles = event.filesTouched.filter(f =>
      f.endsWith('package.json') || f.endsWith('package-lock.json')
    );

    return {
      name: this.name,
      passed: true,
      details: packageFiles.length > 0
        ? `Package files modified: ${packageFiles.join(', ')} - manual review recommended`
        : 'No package files modified',
      score: 1,
    };
  }
}

/**
 * Violation rate evaluator - checks violation count
 */
export class ViolationRateEvaluator implements IEvaluator {
  name = 'violation-rate';
  type = 'objective' as const;
  private maxViolations: number;

  constructor(maxViolations = 0) {
    this.maxViolations = maxViolations;
  }

  async evaluate(event: RunEvent): Promise<EvaluatorResult> {
    const count = event.violations.length;
    const passed = count <= this.maxViolations;

    return {
      name: this.name,
      passed,
      details: passed
        ? `${count} violation(s) within threshold (max: ${this.maxViolations})`
        : `${count} violation(s) exceeds threshold (max: ${this.maxViolations})`,
      score: Math.max(0, 1 - count / Math.max(this.maxViolations + 1, 1)),
    };
  }
}

/**
 * Diff quality evaluator - checks rework ratio
 */
export class DiffQualityEvaluator implements IEvaluator {
  name = 'diff-quality';
  type = 'objective' as const;
  private maxReworkRatio: number;

  constructor(maxReworkRatio = 0.3) {
    this.maxReworkRatio = maxReworkRatio;
  }

  async evaluate(event: RunEvent): Promise<EvaluatorResult> {
    const totalLines = event.diffSummary.linesAdded + event.diffSummary.linesRemoved;
    if (totalLines === 0) {
      return { name: this.name, passed: true, details: 'No diff produced', score: 1 };
    }

    const reworkRatio = event.reworkLines / totalLines;
    const passed = reworkRatio <= this.maxReworkRatio;

    return {
      name: this.name,
      passed,
      details: `Rework ratio: ${(reworkRatio * 100).toFixed(1)}% (${event.reworkLines}/${totalLines} lines). Threshold: ${(this.maxReworkRatio * 100).toFixed(0)}%`,
      score: Math.max(0, 1 - reworkRatio),
    };
  }
}

// ============================================================================
// Run Ledger
// ============================================================================

export class RunLedger {
  private events: RunEvent[] = [];
  private evaluators: IEvaluator[] = [];
  private readonly maxEvents: number;

  /**
   * @param maxEvents - Maximum events to retain in memory (0 = unlimited).
   *   When the limit is exceeded the oldest events are evicted.
   */
  constructor(maxEvents = 0) {
    this.maxEvents = maxEvents;
    // Register default evaluators
    this.evaluators = [
      new TestsPassEvaluator(),
      new ForbiddenCommandEvaluator(),
      new ForbiddenDependencyEvaluator(),
      new ViolationRateEvaluator(),
      new DiffQualityEvaluator(),
    ];
  }

  /**
   * Add a custom evaluator
   */
  addEvaluator(evaluator: IEvaluator): void {
    this.evaluators.push(evaluator);
  }

  /**
   * Remove an evaluator by name
   */
  removeEvaluator(name: string): void {
    this.evaluators = this.evaluators.filter(e => e.name !== name);
  }

  /**
   * Log a run event
   */
  logEvent(event: RunEvent | Omit<RunEvent, 'eventId'>): RunEvent {
    const fullEvent: RunEvent = {
      ...event,
      eventId: randomUUID(),
    } as RunEvent;

    this.events.push(fullEvent);
    this.evictIfNeeded();
    return fullEvent;
  }

  /**
   * Create a new run event with defaults
   */
  createEvent(taskId: string, intent: TaskIntent, guidanceHash: string): RunEvent {
    return {
      eventId: randomUUID(),
      taskId,
      guidanceHash,
      retrievedRuleIds: [],
      toolsUsed: [],
      filesTouched: [],
      diffSummary: { linesAdded: 0, linesRemoved: 0, filesChanged: 0 },
      testResults: { ran: false, passed: 0, failed: 0, skipped: 0 },
      violations: [],
      outcomeAccepted: null,
      reworkLines: 0,
      intent,
      timestamp: Date.now(),
      durationMs: 0,
    };
  }

  /**
   * Finalize and store an event
   */
  finalizeEvent(event: RunEvent): RunEvent {
    event.durationMs = Date.now() - event.timestamp;
    this.events.push(event);
    this.evictIfNeeded();
    return event;
  }

  /**
   * Evict oldest events when maxEvents is exceeded.
   * Trims 10% in a batch to amortize the O(n) splice cost.
   */
  private evictIfNeeded(): void {
    if (this.maxEvents > 0 && this.events.length > this.maxEvents) {
      const trimCount = Math.max(1, Math.floor(this.maxEvents * 0.1));
      this.events.splice(0, trimCount);
    }
  }

  /**
   * Run all evaluators against an event
   */
  async evaluate(event: RunEvent): Promise<EvaluatorResult[]> {
    const results: EvaluatorResult[] = [];

    for (const evaluator of this.evaluators) {
      const result = await evaluator.evaluate(event);
      results.push(result);
    }

    return results;
  }

  /**
   * Get all events
   */
  getEvents(): RunEvent[] {
    return [...this.events];
  }

  /**
   * Get events by task ID
   */
  getEventsByTask(taskId: string): RunEvent[] {
    return this.events.filter(e => e.taskId === taskId);
  }

  /**
   * Get events within a time range
   */
  getEventsInRange(startMs: number, endMs: number): RunEvent[] {
    return this.events.filter(e => e.timestamp >= startMs && e.timestamp <= endMs);
  }

  /**
   * Get recent events
   */
  getRecentEvents(count: number): RunEvent[] {
    return this.events.slice(-count);
  }

  /**
   * Compute optimization metrics from events
   */
  computeMetrics(events?: RunEvent[]): OptimizationMetrics {
    const evts = events ?? this.events;

    if (evts.length === 0) {
      return {
        violationRate: 0,
        selfCorrectionRate: 0,
        reworkLines: 0,
        clarifyingQuestions: 0,
        taskCount: 0,
      };
    }

    // Violations per 10 tasks
    const totalViolations = evts.reduce((sum, e) => sum + e.violations.length, 0);
    const violationRate = evts.length > 0 ? (totalViolations / evts.length) * 10 : 0;

    // Self-correction rate: violations that were auto-corrected
    const totalCorrectable = evts.reduce(
      (sum, e) => sum + e.violations.length,
      0
    );
    const totalCorrected = evts.reduce(
      (sum, e) => sum + e.violations.filter(v => v.autoCorrected).length,
      0
    );
    const selfCorrectionRate = totalCorrectable > 0
      ? totalCorrected / totalCorrectable
      : 1;

    // Average rework lines
    const reworkLines = evts.reduce((sum, e) => sum + e.reworkLines, 0) / evts.length;

    // Clarifying questions are tracked in metadata (placeholder for now)
    const clarifyingQuestions = 0;

    return {
      violationRate,
      selfCorrectionRate,
      reworkLines,
      clarifyingQuestions,
      taskCount: evts.length,
    };
  }

  /**
   * Rank violations by frequency and cost (rework lines)
   */
  rankViolations(windowEvents?: RunEvent[]): ViolationRanking[] {
    const evts = windowEvents ?? this.events;
    const violationMap = new Map<string, { frequency: number; totalRework: number }>();

    for (const event of evts) {
      for (const violation of event.violations) {
        const existing = violationMap.get(violation.ruleId) ?? { frequency: 0, totalRework: 0 };
        existing.frequency++;
        existing.totalRework += event.reworkLines;
        violationMap.set(violation.ruleId, existing);
      }
    }

    const rankings: ViolationRanking[] = [];
    for (const [ruleId, stats] of violationMap) {
      const cost = stats.totalRework / stats.frequency;
      rankings.push({
        ruleId,
        frequency: stats.frequency,
        cost,
        score: stats.frequency * cost,
      });
    }

    return rankings.sort((a, b) => b.score - a.score);
  }

  /**
   * Get event count
   */
  get eventCount(): number {
    return this.events.length;
  }

  /**
   * Export events for persistence
   */
  exportEvents(): RunEvent[] {
    return [...this.events];
  }

  /**
   * Import events from persistence
   */
  importEvents(events: RunEvent[]): void {
    this.events.push(...events);
  }

  /**
   * Clear all events
   */
  clear(): void {
    this.events = [];
  }
}

/**
 * Create a run ledger instance
 *
 * @param maxEvents - Maximum events to retain in memory (0 = unlimited).
 */
export function createLedger(maxEvents = 0): RunLedger {
  return new RunLedger(maxEvents);
}

/**
 * Manifest Validator & Conformance Suite
 *
 * Validates AgentCellManifest documents against the Agentic Container spec,
 * computes risk scores, selects execution lanes, and fails closed on any
 * validation error. The ConformanceSuite runs golden traces through an
 * evaluator to prove the platform behaves as specified.
 *
 * @module @claude-flow/guidance/manifest-validator
 */

// ============================================================================
// Constants
// ============================================================================

const SUPPORTED_API_VERSION = 'agentic_cells.v0_1';
const SHA256_DIGEST_RE = /^sha256:[a-f0-9]{64}$/;

/** Maximum budget limits (sanity caps) */
const MAX_BUDGET_LIMITS = {
  maxWallClockSeconds: 86_400,       // 24 hours
  maxToolCalls: 100_000,
  maxBytesEgress: 10_737_418_240,    // 10 GiB
  maxTokensInMtok: 100,             // 100M tokens
  maxTokensOutMtok: 100,            // 100M tokens
  maxMemoryWrites: 1_000_000,
} as const;

/** Data sensitivity levels ordered by severity */
const DATA_SENSITIVITY_LEVELS = ['public', 'internal', 'confidential', 'restricted'] as const;
type DataSensitivity = typeof DATA_SENSITIVITY_LEVELS[number];

/** Write modes for memory policy */
const WRITE_MODES = ['append', 'overwrite', 'merge'] as const;
type WriteMode = typeof WRITE_MODES[number];

/** Authority scopes for memory policy */
const AUTHORITY_SCOPES = ['self', 'team', 'tenant', 'global'] as const;
type AuthorityScope = typeof AUTHORITY_SCOPES[number];

/** Known tool names the system recognizes */
const KNOWN_TOOLS = new Set([
  'Read', 'Write', 'Edit', 'MultiEdit', 'Glob', 'Grep',
  'Bash', 'Task', 'TodoWrite', 'NotebookEdit', 'WebFetch', 'WebSearch',
  'mcp_memory', 'mcp_swarm', 'mcp_hooks', 'mcp_agent',
]);

/** Trace levels for observability */
const TRACE_LEVELS = ['none', 'errors', 'decisions', 'full'] as const;

/** Execution lanes ordered by privilege (lowest to highest) */
const LANES = ['wasm', 'sandboxed', 'native'] as const;
type Lane = typeof LANES[number];

// ============================================================================
// AgentCellManifest Interface
// ============================================================================

/**
 * The manifest describing an agent cell per the Agentic Container spec.
 */
export interface AgentCellManifest {
  /** API version string (must be 'agentic_cells.v0_1') */
  apiVersion: string;

  /** Cell identity */
  cell: {
    name: string;
    purpose: string;
    ownerTenant: string;
    codeRef: {
      kind: string;
      digest: string;
      entry: string;
    };
  };

  /** Lane execution policy */
  lanePolicy: {
    portabilityRequired: boolean;
    needsNativeThreads: boolean;
    preferredLane: Lane;
    maxRiskScore: number;
  };

  /** Resource budgets */
  budgets: {
    maxWallClockSeconds: number;
    maxToolCalls: number;
    maxBytesEgress: number;
    maxTokensInMtok: number;
    maxTokensOutMtok: number;
    maxMemoryWrites: number;
  };

  /** Data handling policy */
  dataPolicy: {
    dataSensitivity: DataSensitivity;
    piiAllowed: boolean;
    retentionDays: number;
    exportControls: {
      allowedRegions: string[];
      blockedRegions: string[];
    };
  };

  /** Tool usage policy */
  toolPolicy: {
    toolsAllowed: string[];
    networkAllowlist: string[];
    writeActionsRequireConfirmation: boolean;
  };

  /** Memory system policy */
  memoryPolicy: {
    namespace: string;
    authorityScope: AuthorityScope;
    writeMode: WriteMode;
    requiresCoherenceGate: boolean;
    requiresAntiHallucinationGate: boolean;
  };

  /** Observability configuration */
  observability: {
    traceLevel: typeof TRACE_LEVELS[number];
    emitArtifacts: boolean;
    artifactBucket: string;
  };
}

// ============================================================================
// Validation Result Types
// ============================================================================

/**
 * A single validation error or warning.
 */
export interface ValidationError {
  /** Error code (e.g., 'MISSING_FIELD', 'INVALID_DIGEST', 'BUDGET_EXCEED') */
  code: string;
  /** JSON path to the problematic field */
  field: string;
  /** Human-readable description */
  message: string;
  /** Severity level */
  severity: 'error';
}

/**
 * A single validation warning.
 */
export interface ValidationWarning {
  /** Warning code */
  code: string;
  /** JSON path to the problematic field */
  field: string;
  /** Human-readable description */
  message: string;
  /** Severity level */
  severity: 'warning';
}

/**
 * Complete validation result for a manifest.
 */
export interface ValidationResult {
  /** Whether the manifest passed all validation checks */
  valid: boolean;
  /** Validation errors (each causes rejection) */
  errors: ValidationError[];
  /** Validation warnings (informational, do not block admission) */
  warnings: ValidationWarning[];
  /** Admission decision: admit, reject, or review */
  admissionDecision: 'admit' | 'reject' | 'review';
  /** Selected execution lane (null if rejected) */
  laneSelection: Lane | null;
  /** Computed risk score (0-100) */
  riskScore: number;
}

// ============================================================================
// ManifestValidator
// ============================================================================

/**
 * Validates AgentCellManifest documents against the Agentic Container spec.
 *
 * Fails closed: any validation error results in a 'reject' decision.
 * Warnings alone do not block admission but may trigger a 'review' decision
 * when the risk score is between thresholds.
 */
export class ManifestValidator {
  /** Risk score threshold: below this, admit. Above reject threshold, reject. Between, review. */
  private readonly admitThreshold: number;
  private readonly rejectThreshold: number;

  constructor(options?: { admitThreshold?: number; rejectThreshold?: number }) {
    this.admitThreshold = options?.admitThreshold ?? 30;
    this.rejectThreshold = options?.rejectThreshold ?? 70;
  }

  /**
   * Validate a manifest, compute its risk score, select a lane, and decide admission.
   *
   * FAILS CLOSED: any validation error leads to reject.
   */
  validate(manifest: AgentCellManifest): ValidationResult {
    const errors: ValidationError[] = [];
    const warnings: ValidationWarning[] = [];

    // Structural validation
    errors.push(...this.validateRequiredFields(manifest));
    errors.push(...this.validateApiVersion(manifest));
    errors.push(...this.validateDigest(manifest));
    errors.push(...this.validateBudgets(manifest.budgets));
    errors.push(...this.validateToolPolicy(manifest.toolPolicy));
    errors.push(...this.validateDataPolicy(manifest.dataPolicy));
    warnings.push(...this.validateWarnings(manifest));

    // Compute risk score (even if there are errors, for diagnostics)
    const riskScore = this.computeRiskScore(manifest);

    // FAIL CLOSED: any error means reject
    if (errors.length > 0) {
      return {
        valid: false,
        errors,
        warnings,
        admissionDecision: 'reject',
        laneSelection: null,
        riskScore,
      };
    }

    // Lane selection
    const laneSelection = this.selectLane(manifest, riskScore);

    // Admission decision based on risk score
    let admissionDecision: 'admit' | 'reject' | 'review';
    if (riskScore > this.rejectThreshold) {
      admissionDecision = 'reject';
    } else if (riskScore > this.admitThreshold) {
      admissionDecision = 'review';
    } else {
      admissionDecision = 'admit';
    }

    return {
      valid: true,
      errors,
      warnings,
      admissionDecision,
      laneSelection,
      riskScore,
    };
  }

  /**
   * Compute a risk score (0-100) from tool risk, data sensitivity, and privilege surface.
   *
   * Components:
   * - tool_risk (0-40): based on tool types and network access
   * - data_sensitivity (0-30): based on sensitivity level and PII
   * - privilege_surface (0-30): based on memory scope, write mode, native threads
   */
  computeRiskScore(manifest: AgentCellManifest): number {
    let toolRisk = 0;
    let dataSensitivity = 0;
    let privilegeSurface = 0;

    // --- Tool risk (0-40) ---
    const tools = manifest.toolPolicy?.toolsAllowed ?? [];
    const networkList = manifest.toolPolicy?.networkAllowlist ?? [];

    // Bash/command execution is high risk
    if (tools.includes('Bash') || tools.includes('bash')) {
      toolRisk += 15;
    }
    // Task spawning
    if (tools.includes('Task') || tools.includes('task')) {
      toolRisk += 8;
    }
    // Write operations
    if (tools.some(t => ['Write', 'Edit', 'MultiEdit', 'NotebookEdit'].includes(t))) {
      toolRisk += 5;
    }
    // MCP tools
    if (tools.some(t => t.startsWith('mcp_'))) {
      toolRisk += 5;
    }
    // Network access
    if (networkList.length > 0) {
      toolRisk += 5;
    }
    // Wildcard in network (already caught as error if not privileged, but score anyway)
    if (networkList.some(h => h === '*' || h.startsWith('*.'))) {
      toolRisk += 10;
    }
    // No confirmation on writes
    if (manifest.toolPolicy && !manifest.toolPolicy.writeActionsRequireConfirmation) {
      toolRisk += 3;
    }

    toolRisk = Math.min(toolRisk, 40);

    // --- Data sensitivity (0-30) ---
    const sensitivityIndex = DATA_SENSITIVITY_LEVELS.indexOf(
      manifest.dataPolicy?.dataSensitivity as DataSensitivity
    );
    if (sensitivityIndex >= 0) {
      dataSensitivity += sensitivityIndex * 8; // 0, 8, 16, 24
    }
    if (manifest.dataPolicy?.piiAllowed) {
      dataSensitivity += 6;
    }
    dataSensitivity = Math.min(dataSensitivity, 30);

    // --- Privilege surface (0-30) ---
    const scopeIndex = AUTHORITY_SCOPES.indexOf(
      manifest.memoryPolicy?.authorityScope as AuthorityScope
    );
    if (scopeIndex >= 0) {
      privilegeSurface += scopeIndex * 5; // 0, 5, 10, 15
    }
    if (manifest.memoryPolicy?.writeMode === 'overwrite') {
      privilegeSurface += 5;
    }
    if (manifest.lanePolicy?.needsNativeThreads) {
      privilegeSurface += 8;
    }
    if (manifest.memoryPolicy && !manifest.memoryPolicy.requiresCoherenceGate) {
      privilegeSurface += 3;
    }
    if (manifest.memoryPolicy && !manifest.memoryPolicy.requiresAntiHallucinationGate) {
      privilegeSurface += 3;
    }

    privilegeSurface = Math.min(privilegeSurface, 30);

    return Math.min(toolRisk + dataSensitivity + privilegeSurface, 100);
  }

  /**
   * Select the execution lane based on risk score and manifest policy.
   *
   * Lane selection rules:
   * - If portabilityRequired or risk <= 30: wasm
   * - If needsNativeThreads and risk > 50: native
   * - Otherwise: sandboxed
   * - Always respect preferredLane if risk score allows it
   * - Risk exceeding maxRiskScore forces the most restrictive lane
   */
  selectLane(manifest: AgentCellManifest, riskScore: number): Lane {
    const policy = manifest.lanePolicy;

    // If risk exceeds the manifest's own maxRiskScore, force wasm
    if (riskScore > policy.maxRiskScore) {
      return 'wasm';
    }

    // Portability requirement forces wasm
    if (policy.portabilityRequired) {
      return 'wasm';
    }

    // Native threads require native lane
    if (policy.needsNativeThreads) {
      // Only grant native if risk is acceptable
      if (riskScore <= 50) {
        return 'native';
      }
      return 'sandboxed';
    }

    // Low risk can go to wasm
    if (riskScore <= 20) {
      return policy.preferredLane;
    }

    // Medium risk gets sandboxed
    if (riskScore <= 50) {
      // Respect preference if it's not native
      if (policy.preferredLane !== 'native') {
        return policy.preferredLane;
      }
      return 'sandboxed';
    }

    // High risk gets wasm
    return 'wasm';
  }

  /**
   * Validate budget values: no negatives, within sanity limits.
   */
  validateBudgets(budgets: AgentCellManifest['budgets']): ValidationError[] {
    const errors: ValidationError[] = [];

    if (!budgets) {
      errors.push({
        code: 'MISSING_FIELD',
        field: 'budgets',
        message: 'Budget configuration is required',
        severity: 'error',
      });
      return errors;
    }

    const budgetFields: Array<{
      key: keyof typeof budgets;
      max: number;
    }> = [
      { key: 'maxWallClockSeconds', max: MAX_BUDGET_LIMITS.maxWallClockSeconds },
      { key: 'maxToolCalls', max: MAX_BUDGET_LIMITS.maxToolCalls },
      { key: 'maxBytesEgress', max: MAX_BUDGET_LIMITS.maxBytesEgress },
      { key: 'maxTokensInMtok', max: MAX_BUDGET_LIMITS.maxTokensInMtok },
      { key: 'maxTokensOutMtok', max: MAX_BUDGET_LIMITS.maxTokensOutMtok },
      { key: 'maxMemoryWrites', max: MAX_BUDGET_LIMITS.maxMemoryWrites },
    ];

    for (const { key, max } of budgetFields) {
      const value = budgets[key];
      if (value === undefined || value === null) {
        errors.push({
          code: 'MISSING_FIELD',
          field: `budgets.${key}`,
          message: `Budget field "${key}" is required`,
          severity: 'error',
        });
        continue;
      }

      if (typeof value !== 'number' || Number.isNaN(value)) {
        errors.push({
          code: 'INVALID_TYPE',
          field: `budgets.${key}`,
          message: `Budget field "${key}" must be a number`,
          severity: 'error',
        });
        continue;
      }

      if (value < 0) {
        errors.push({
          code: 'BUDGET_NEGATIVE',
          field: `budgets.${key}`,
          message: `Budget field "${key}" must not be negative (got ${value})`,
          severity: 'error',
        });
      }

      if (value > max) {
        errors.push({
          code: 'BUDGET_EXCEED',
          field: `budgets.${key}`,
          message: `Budget field "${key}" exceeds maximum (${value} > ${max})`,
          severity: 'error',
        });
      }
    }

    return errors;
  }

  /**
   * Validate tool policy: network allowlist must not contain wildcards
   * unless the cell explicitly has Bash (privileged).
   */
  validateToolPolicy(toolPolicy: AgentCellManifest['toolPolicy']): ValidationError[] {
    const errors: ValidationError[] = [];

    if (!toolPolicy) {
      errors.push({
        code: 'MISSING_FIELD',
        field: 'toolPolicy',
        message: 'Tool policy is required',
        severity: 'error',
      });
      return errors;
    }

    if (!Array.isArray(toolPolicy.toolsAllowed)) {
      errors.push({
        code: 'INVALID_TYPE',
        field: 'toolPolicy.toolsAllowed',
        message: 'toolsAllowed must be an array',
        severity: 'error',
      });
    }

    if (!Array.isArray(toolPolicy.networkAllowlist)) {
      errors.push({
        code: 'INVALID_TYPE',
        field: 'toolPolicy.networkAllowlist',
        message: 'networkAllowlist must be an array',
        severity: 'error',
      });
    }

    // Check for wildcards in network allowlist
    const isPrivileged = Array.isArray(toolPolicy.toolsAllowed) &&
      toolPolicy.toolsAllowed.includes('Bash');

    if (Array.isArray(toolPolicy.networkAllowlist)) {
      for (let i = 0; i < toolPolicy.networkAllowlist.length; i++) {
        const entry = toolPolicy.networkAllowlist[i];
        if (entry === '*' || entry.startsWith('*.')) {
          if (!isPrivileged) {
            errors.push({
              code: 'WILDCARD_NETWORK',
              field: `toolPolicy.networkAllowlist[${i}]`,
              message: `Wildcard "${entry}" in network allowlist requires privileged access (Bash tool)`,
              severity: 'error',
            });
          }
        }
      }
    }

    return errors;
  }

  /**
   * Validate data policy fields.
   */
  validateDataPolicy(dataPolicy: AgentCellManifest['dataPolicy']): ValidationError[] {
    const errors: ValidationError[] = [];

    if (!dataPolicy) {
      errors.push({
        code: 'MISSING_FIELD',
        field: 'dataPolicy',
        message: 'Data policy is required',
        severity: 'error',
      });
      return errors;
    }

    if (!DATA_SENSITIVITY_LEVELS.includes(dataPolicy.dataSensitivity as DataSensitivity)) {
      errors.push({
        code: 'INVALID_ENUM',
        field: 'dataPolicy.dataSensitivity',
        message: `dataSensitivity must be one of: ${DATA_SENSITIVITY_LEVELS.join(', ')} (got "${dataPolicy.dataSensitivity}")`,
        severity: 'error',
      });
    }

    if (typeof dataPolicy.retentionDays !== 'number' || dataPolicy.retentionDays < 0) {
      errors.push({
        code: 'INVALID_VALUE',
        field: 'dataPolicy.retentionDays',
        message: 'retentionDays must be a non-negative number',
        severity: 'error',
      });
    }

    if (!dataPolicy.exportControls) {
      errors.push({
        code: 'MISSING_FIELD',
        field: 'dataPolicy.exportControls',
        message: 'exportControls is required in data policy',
        severity: 'error',
      });
    } else {
      if (!Array.isArray(dataPolicy.exportControls.allowedRegions)) {
        errors.push({
          code: 'INVALID_TYPE',
          field: 'dataPolicy.exportControls.allowedRegions',
          message: 'allowedRegions must be an array',
          severity: 'error',
        });
      }
      if (!Array.isArray(dataPolicy.exportControls.blockedRegions)) {
        errors.push({
          code: 'INVALID_TYPE',
          field: 'dataPolicy.exportControls.blockedRegions',
          message: 'blockedRegions must be an array',
          severity: 'error',
        });
      }

      // Check for overlap between allowed and blocked regions
      if (
        Array.isArray(dataPolicy.exportControls.allowedRegions) &&
        Array.isArray(dataPolicy.exportControls.blockedRegions)
      ) {
        const overlap = dataPolicy.exportControls.allowedRegions.filter(
          r => dataPolicy.exportControls.blockedRegions.includes(r)
        );
        if (overlap.length > 0) {
          errors.push({
            code: 'REGION_CONFLICT',
            field: 'dataPolicy.exportControls',
            message: `Regions appear in both allowed and blocked lists: ${overlap.join(', ')}`,
            severity: 'error',
          });
        }
      }
    }

    return errors;
  }

  // ===== Private validation helpers =====

  private validateRequiredFields(manifest: AgentCellManifest): ValidationError[] {
    const errors: ValidationError[] = [];

    if (!manifest) {
      errors.push({
        code: 'MISSING_FIELD',
        field: '',
        message: 'Manifest is required',
        severity: 'error',
      });
      return errors;
    }

    // Top-level required sections
    const requiredSections = [
      'apiVersion', 'cell', 'lanePolicy', 'budgets',
      'dataPolicy', 'toolPolicy', 'memoryPolicy', 'observability',
    ] as const;

    for (const section of requiredSections) {
      if (manifest[section] === undefined || manifest[section] === null) {
        errors.push({
          code: 'MISSING_FIELD',
          field: section,
          message: `Required field "${section}" is missing`,
          severity: 'error',
        });
      }
    }

    // Cell sub-fields
    if (manifest.cell) {
      for (const field of ['name', 'purpose', 'ownerTenant'] as const) {
        if (!manifest.cell[field]) {
          errors.push({
            code: 'MISSING_FIELD',
            field: `cell.${field}`,
            message: `Required field "cell.${field}" is missing`,
            severity: 'error',
          });
        }
      }

      if (!manifest.cell.codeRef) {
        errors.push({
          code: 'MISSING_FIELD',
          field: 'cell.codeRef',
          message: 'Required field "cell.codeRef" is missing',
          severity: 'error',
        });
      } else {
        for (const field of ['kind', 'digest', 'entry'] as const) {
          if (!manifest.cell.codeRef[field]) {
            errors.push({
              code: 'MISSING_FIELD',
              field: `cell.codeRef.${field}`,
              message: `Required field "cell.codeRef.${field}" is missing`,
              severity: 'error',
            });
          }
        }
      }
    }

    // Memory policy sub-fields
    if (manifest.memoryPolicy) {
      if (!manifest.memoryPolicy.namespace) {
        errors.push({
          code: 'MISSING_FIELD',
          field: 'memoryPolicy.namespace',
          message: 'Required field "memoryPolicy.namespace" is missing',
          severity: 'error',
        });
      }

      if (!AUTHORITY_SCOPES.includes(manifest.memoryPolicy.authorityScope as AuthorityScope)) {
        errors.push({
          code: 'INVALID_ENUM',
          field: 'memoryPolicy.authorityScope',
          message: `authorityScope must be one of: ${AUTHORITY_SCOPES.join(', ')}`,
          severity: 'error',
        });
      }

      if (!WRITE_MODES.includes(manifest.memoryPolicy.writeMode as WriteMode)) {
        errors.push({
          code: 'INVALID_ENUM',
          field: 'memoryPolicy.writeMode',
          message: `writeMode must be one of: ${WRITE_MODES.join(', ')}`,
          severity: 'error',
        });
      }
    }

    // Observability sub-fields
    if (manifest.observability) {
      if (!TRACE_LEVELS.includes(manifest.observability.traceLevel as typeof TRACE_LEVELS[number])) {
        errors.push({
          code: 'INVALID_ENUM',
          field: 'observability.traceLevel',
          message: `traceLevel must be one of: ${TRACE_LEVELS.join(', ')}`,
          severity: 'error',
        });
      }
    }

    return errors;
  }

  private validateApiVersion(manifest: AgentCellManifest): ValidationError[] {
    if (!manifest.apiVersion) return []; // caught by requiredFields

    if (manifest.apiVersion !== SUPPORTED_API_VERSION) {
      return [{
        code: 'UNSUPPORTED_API_VERSION',
        field: 'apiVersion',
        message: `API version "${manifest.apiVersion}" is not supported (expected "${SUPPORTED_API_VERSION}")`,
        severity: 'error',
      }];
    }
    return [];
  }

  private validateDigest(manifest: AgentCellManifest): ValidationError[] {
    if (!manifest.cell?.codeRef?.digest) return []; // caught by requiredFields

    if (!SHA256_DIGEST_RE.test(manifest.cell.codeRef.digest)) {
      return [{
        code: 'INVALID_DIGEST',
        field: 'cell.codeRef.digest',
        message: `Digest must match "sha256:<64 hex chars>" format (got "${manifest.cell.codeRef.digest}")`,
        severity: 'error',
      }];
    }
    return [];
  }

  private validateWarnings(manifest: AgentCellManifest): ValidationWarning[] {
    const warnings: ValidationWarning[] = [];

    // Warn about unknown tools
    if (manifest.toolPolicy?.toolsAllowed) {
      for (const tool of manifest.toolPolicy.toolsAllowed) {
        if (!KNOWN_TOOLS.has(tool)) {
          warnings.push({
            code: 'UNKNOWN_TOOL',
            field: 'toolPolicy.toolsAllowed',
            message: `Tool "${tool}" is not a recognized system tool`,
            severity: 'warning',
          });
        }
      }
    }

    // Warn if both coherence and anti-hallucination gates are disabled
    if (
      manifest.memoryPolicy &&
      !manifest.memoryPolicy.requiresCoherenceGate &&
      !manifest.memoryPolicy.requiresAntiHallucinationGate
    ) {
      warnings.push({
        code: 'NO_MEMORY_GATES',
        field: 'memoryPolicy',
        message: 'Both coherence and anti-hallucination gates are disabled; memory writes are ungated',
        severity: 'warning',
      });
    }

    // Warn about high retention with sensitive data
    if (
      manifest.dataPolicy &&
      manifest.dataPolicy.dataSensitivity === 'restricted' &&
      manifest.dataPolicy.retentionDays > 30
    ) {
      warnings.push({
        code: 'HIGH_RETENTION_SENSITIVE',
        field: 'dataPolicy.retentionDays',
        message: `Retention of ${manifest.dataPolicy.retentionDays} days is high for restricted data`,
        severity: 'warning',
      });
    }

    // Warn if no trace level is set to full but artifacts are emitted
    if (
      manifest.observability &&
      manifest.observability.emitArtifacts &&
      manifest.observability.traceLevel === 'none'
    ) {
      warnings.push({
        code: 'ARTIFACTS_WITHOUT_TRACING',
        field: 'observability',
        message: 'Artifact emission is enabled but trace level is "none"',
        severity: 'warning',
      });
    }

    return warnings;
  }
}

// ============================================================================
// Golden Trace Types
// ============================================================================

/**
 * A single event within a golden trace.
 */
export interface GoldenTraceEvent {
  /** Sequence number within the trace */
  seq: number;
  /** Type of event (e.g., 'command', 'tool-use', 'memory-write', 'budget-check') */
  eventType: string;
  /** Event payload */
  payload: Record<string, unknown>;
  /** Expected outcome from the platform */
  expectedOutcome: 'allow' | 'deny' | 'warn';
}

/**
 * A complete golden trace including events and expected decisions.
 */
export interface GoldenTrace {
  /** Unique trace identifier */
  traceId: string;
  /** Human-readable name */
  name: string;
  /** Description of what the trace verifies */
  description: string;
  /** Ordered sequence of events */
  events: GoldenTraceEvent[];
  /** Map from event seq (as string) to expected decision string */
  expectedDecisions: Record<string, string>;
  /** Map from memory key to expected parent chain for lineage verification */
  expectedMemoryLineage: Record<string, string[]>;
}

// ============================================================================
// ConformanceResult
// ============================================================================

/**
 * Result of running the conformance suite.
 */
export interface ConformanceResult {
  /** Whether all events matched their expected outcomes */
  passed: boolean;
  /** Total number of events evaluated */
  totalEvents: number;
  /** Number of events that matched expectations */
  matchedEvents: number;
  /** Details of any mismatches */
  mismatches: Array<{
    traceId: string;
    seq: number;
    expected: string;
    actual: string;
    details: unknown;
  }>;
}

// ============================================================================
// ConformanceSuite
// ============================================================================

/**
 * Runs golden traces through an evaluator and reports conformance.
 *
 * Each trace contains events with expected outcomes. The suite feeds every
 * event to the evaluator and compares the actual decision to the expectation.
 */
export class ConformanceSuite {
  private traces: GoldenTrace[] = [];

  /**
   * Add a golden trace to the suite.
   */
  addTrace(trace: GoldenTrace): void {
    this.traces.push(trace);
  }

  /**
   * Run every event in every trace through the evaluator and compare
   * actual decisions against expected outcomes.
   */
  run(
    evaluator: (event: GoldenTraceEvent) => { decision: string; details: unknown },
  ): ConformanceResult {
    let totalEvents = 0;
    let matchedEvents = 0;
    const mismatches: ConformanceResult['mismatches'] = [];

    for (const trace of this.traces) {
      for (const event of trace.events) {
        totalEvents++;

        const { decision, details } = evaluator(event);
        const expected = trace.expectedDecisions[String(event.seq)] ?? event.expectedOutcome;

        if (decision === expected) {
          matchedEvents++;
        } else {
          mismatches.push({
            traceId: trace.traceId,
            seq: event.seq,
            expected,
            actual: decision,
            details,
          });
        }
      }
    }

    return {
      passed: mismatches.length === 0,
      totalEvents,
      matchedEvents,
      mismatches,
    };
  }

  /**
   * Get all registered traces.
   */
  getTraces(): GoldenTrace[] {
    return [...this.traces];
  }

  /**
   * Create built-in default golden traces that verify core platform invariants:
   *
   * 1. Destructive command blocked
   * 2. Secret detected and blocked
   * 3. Budget exceeded and denied
   * 4. Memory write without evidence blocked
   * 5. Valid operation allowed
   */
  createDefaultTraces(): GoldenTrace[] {
    const traces: GoldenTrace[] = [
      // Trace 1: Destructive command must be blocked
      {
        traceId: 'default-destructive-blocked',
        name: 'Destructive command blocked',
        description: 'Verifies that destructive commands (rm -rf, DROP TABLE) are denied',
        events: [
          {
            seq: 1,
            eventType: 'command',
            payload: { command: 'rm -rf /', tool: 'Bash' },
            expectedOutcome: 'deny',
          },
          {
            seq: 2,
            eventType: 'command',
            payload: { command: 'DROP TABLE users', tool: 'Bash' },
            expectedOutcome: 'deny',
          },
          {
            seq: 3,
            eventType: 'command',
            payload: { command: 'git push --force origin main', tool: 'Bash' },
            expectedOutcome: 'deny',
          },
        ],
        expectedDecisions: { '1': 'deny', '2': 'deny', '3': 'deny' },
        expectedMemoryLineage: {},
      },

      // Trace 2: Secret detected and blocked
      {
        traceId: 'default-secret-blocked',
        name: 'Secret detected and blocked',
        description: 'Verifies that secrets in tool parameters are detected and blocked',
        events: [
          {
            seq: 1,
            eventType: 'tool-use',
            payload: {
              tool: 'Write',
              params: { content: 'api_key = "sk-abc123456789012345678901234567890"' },
            },
            expectedOutcome: 'deny',
          },
          {
            seq: 2,
            eventType: 'tool-use',
            payload: {
              tool: 'Edit',
              params: { content: '-----BEGIN RSA PRIVATE KEY-----' },
            },
            expectedOutcome: 'deny',
          },
        ],
        expectedDecisions: { '1': 'deny', '2': 'deny' },
        expectedMemoryLineage: {},
      },

      // Trace 3: Budget exceeded and denied
      {
        traceId: 'default-budget-exceeded',
        name: 'Budget exceeded and denied',
        description: 'Verifies that operations exceeding budget limits are denied',
        events: [
          {
            seq: 1,
            eventType: 'budget-check',
            payload: {
              resource: 'toolCalls',
              current: 999,
              limit: 1000,
              requested: 5,
            },
            expectedOutcome: 'deny',
          },
          {
            seq: 2,
            eventType: 'budget-check',
            payload: {
              resource: 'wallClockSeconds',
              current: 3500,
              limit: 3600,
              requested: 200,
            },
            expectedOutcome: 'deny',
          },
        ],
        expectedDecisions: { '1': 'deny', '2': 'deny' },
        expectedMemoryLineage: {},
      },

      // Trace 4: Memory write without evidence blocked
      {
        traceId: 'default-memory-no-evidence',
        name: 'Memory write without evidence blocked',
        description: 'Verifies that memory writes without proof/evidence trail are denied',
        events: [
          {
            seq: 1,
            eventType: 'memory-write',
            payload: {
              key: 'critical-decision',
              namespace: 'coordination',
              hasEvidence: false,
              coherenceScore: 0.3,
            },
            expectedOutcome: 'deny',
          },
          {
            seq: 2,
            eventType: 'memory-write',
            payload: {
              key: 'hallucinated-data',
              namespace: 'facts',
              hasEvidence: false,
              antiHallucinationPassed: false,
            },
            expectedOutcome: 'deny',
          },
        ],
        expectedDecisions: { '1': 'deny', '2': 'deny' },
        expectedMemoryLineage: {
          'critical-decision': ['initial-assessment', 'root-task'],
        },
      },

      // Trace 5: Valid operation allowed
      {
        traceId: 'default-valid-allowed',
        name: 'Valid operation allowed',
        description: 'Verifies that well-formed, safe operations are allowed through',
        events: [
          {
            seq: 1,
            eventType: 'command',
            payload: { command: 'git status', tool: 'Bash' },
            expectedOutcome: 'allow',
          },
          {
            seq: 2,
            eventType: 'tool-use',
            payload: {
              tool: 'Read',
              params: { file_path: '/home/user/project/src/index.ts' },
            },
            expectedOutcome: 'allow',
          },
          {
            seq: 3,
            eventType: 'memory-write',
            payload: {
              key: 'agent-status',
              namespace: 'coordination',
              hasEvidence: true,
              coherenceScore: 0.95,
              antiHallucinationPassed: true,
            },
            expectedOutcome: 'allow',
          },
        ],
        expectedDecisions: { '1': 'allow', '2': 'allow', '3': 'allow' },
        expectedMemoryLineage: {},
      },
    ];

    return traces;
  }
}

// ============================================================================
// Factory Functions
// ============================================================================

/**
 * Create a new ManifestValidator instance.
 */
export function createManifestValidator(
  options?: { admitThreshold?: number; rejectThreshold?: number },
): ManifestValidator {
  return new ManifestValidator(options);
}

/**
 * Create a new ConformanceSuite instance, optionally pre-loaded with default traces.
 */
export function createConformanceSuite(
  options?: { includeDefaults?: boolean },
): ConformanceSuite {
  const suite = new ConformanceSuite();
  if (options?.includeDefaults) {
    for (const trace of suite.createDefaultTraces()) {
      suite.addTrace(trace);
    }
  }
  return suite;
}

/**
 * Memory Write Gating System
 *
 * Adds authority scope, TTL, decay, and contradiction tracking
 * to memory operations. Ensures that only authorized agents can
 * write to specific namespaces, enforces rate limits, and detects
 * contradictions between memory entries.
 *
 * @module @claude-flow/guidance/memory-gate
 */

import { createHash } from 'node:crypto';

// ============================================================================
// Types
// ============================================================================

/**
 * Authority definition for a memory-writing agent
 */
export interface MemoryAuthority {
  /** Agent identifier */
  agentId: string;
  /** Role in the hierarchy */
  role: 'queen' | 'coordinator' | 'worker' | 'observer';
  /** Namespaces this agent is allowed to write to */
  namespaces: string[];
  /** Maximum writes allowed per minute */
  maxWritesPerMinute: number;
  /** Whether this agent can delete entries */
  canDelete: boolean;
  /** Whether this agent can overwrite existing entries */
  canOverwrite: boolean;
  /** Trust level from 0 (untrusted) to 1 (fully trusted) */
  trustLevel: number;
}

/**
 * A gated memory entry with metadata for TTL, decay, lineage, and contradictions
 */
export interface MemoryEntry {
  /** Entry key */
  key: string;
  /** Namespace the entry belongs to */
  namespace: string;
  /** The stored value */
  value: unknown;
  /** SHA-256 hash of the serialized value */
  valueHash: string;
  /** Authority that created/last wrote this entry */
  authority: MemoryAuthority;
  /** Timestamp when the entry was created (ms since epoch) */
  createdAt: number;
  /** Timestamp of the last update (ms since epoch) */
  updatedAt: number;
  /** Time-to-live in milliseconds, or null for no expiry */
  ttlMs: number | null;
  /** Decay rate from 0 (no decay) to 1 (immediate decay) */
  decayRate: number;
  /** Confidence score from 0 to 1, decays over time */
  confidence: number;
  /** Lineage tracking for provenance */
  lineage: {
    parentKey?: string;
    derivedFrom?: string[];
    operation: string;
  };
  /** Detected contradictions with other entries */
  contradictions: Array<{
    entryKey: string;
    description: string;
    resolvedAt?: number;
  }>;
}

/**
 * Result of evaluating a write request
 */
export interface WriteDecision {
  /** Whether the write is allowed */
  allowed: boolean;
  /** Human-readable reason for the decision */
  reason: string;
  /** Contradictions detected with existing entries */
  contradictions: Array<{ existingKey: string; description: string }>;
  /** Authority check result */
  authorityCheck: {
    passed: boolean;
    requiredRole: string;
    actualRole: string;
  };
  /** Rate limit check result */
  rateCheck: {
    passed: boolean;
    writesInWindow: number;
    limit: number;
  };
  /** Overwrite permission check result */
  overwriteCheck: {
    isOverwrite: boolean;
    allowed: boolean;
  };
}

/**
 * Configuration for the MemoryWriteGate
 */
export interface MemoryWriteGateConfig {
  /** Pre-registered authorities */
  authorities?: MemoryAuthority[];
  /** Similarity threshold for contradiction detection (0-1) */
  contradictionThreshold?: number;
  /** Default TTL for new entries in ms (null = no expiry) */
  defaultTtlMs?: number;
  /** Default decay rate for new entries (0-1) */
  defaultDecayRate?: number;
  /** Whether to run contradiction detection on writes */
  enableContradictionTracking?: boolean;
}

// ============================================================================
// Role Hierarchy
// ============================================================================

/** Role hierarchy levels (higher = more authority) */
const ROLE_HIERARCHY: Record<MemoryAuthority['role'], number> = {
  queen: 4,
  coordinator: 3,
  worker: 2,
  observer: 1,
};

/**
 * Minimum role required to write to any namespace
 */
const MINIMUM_WRITE_ROLE: MemoryAuthority['role'] = 'worker';

// ============================================================================
// Contradiction Detection Patterns
// ============================================================================

const CONTRADICTION_PATTERNS: Array<{
  positive: RegExp;
  negative: RegExp;
  description: string;
}> = [
  {
    positive: /\bmust\b/i,
    negative: /\bnever\b|\bdo not\b|\bavoid\b/i,
    description: 'Conflicting obligation: "must" vs negation',
  },
  {
    positive: /\balways\b/i,
    negative: /\bnever\b|\bdon't\b|\bdo not\b/i,
    description: 'Conflicting frequency: "always" vs "never"',
  },
  {
    positive: /\brequire\b/i,
    negative: /\bforbid\b|\bprohibit\b/i,
    description: 'Conflicting policy: "require" vs "forbid"',
  },
  {
    positive: /\benable\b/i,
    negative: /\bdisable\b/i,
    description: 'Conflicting state: "enable" vs "disable"',
  },
  {
    positive: /\btrue\b/i,
    negative: /\bfalse\b/i,
    description: 'Conflicting boolean: "true" vs "false"',
  },
];

// ============================================================================
// Utility Functions
// ============================================================================

/**
 * Compute SHA-256 hash of a value
 */
function computeValueHash(value: unknown): string {
  const serialized = JSON.stringify(value);
  return createHash('sha256').update(serialized).digest('hex');
}

/**
 * Stringify a value for contradiction detection
 */
function stringifyForComparison(value: unknown): string {
  if (typeof value === 'string') return value;
  if (typeof value === 'number' || typeof value === 'boolean') return String(value);
  try {
    return JSON.stringify(value);
  } catch {
    return String(value);
  }
}

// ============================================================================
// MemoryWriteGate
// ============================================================================

/**
 * Memory Write Gate
 *
 * Controls write access to the memory system by enforcing:
 * - Authority checks (namespace access, role hierarchy)
 * - Rate limiting (sliding window per agent)
 * - Overwrite permissions
 * - Contradiction detection against existing entries
 * - TTL and confidence decay tracking
 */
export class MemoryWriteGate {
  private authorities: Map<string, MemoryAuthority> = new Map();
  private writeTimestamps: Map<string, number[]> = new Map();
  private contradictionThreshold: number;
  private defaultTtlMs: number | null;
  private defaultDecayRate: number;
  private enableContradictionTracking: boolean;
  private contradictionResolutions: Map<string, string> = new Map();

  constructor(config: MemoryWriteGateConfig = {}) {
    this.contradictionThreshold = config.contradictionThreshold ?? 0.5;
    this.defaultTtlMs = config.defaultTtlMs ?? null;
    this.defaultDecayRate = config.defaultDecayRate ?? 0;
    this.enableContradictionTracking = config.enableContradictionTracking ?? true;

    if (config.authorities) {
      for (const authority of config.authorities) {
        this.authorities.set(authority.agentId, authority);
      }
    }
  }

  /**
   * Evaluate whether a write operation should be allowed.
   *
   * Steps:
   * 1. Check authority (namespace allowed, role sufficient)
   * 2. Check rate limit
   * 3. Check overwrite permission
   * 4. Detect contradictions against existing entries
   * 5. Return decision
   */
  evaluateWrite(
    authority: MemoryAuthority,
    key: string,
    namespace: string,
    value: unknown,
    existingEntries?: MemoryEntry[]
  ): WriteDecision {
    const reasons: string[] = [];
    let allowed = true;

    // Step 1: Authority check
    const authorityCheck = this.checkAuthority(authority, namespace);
    if (!authorityCheck.passed) {
      allowed = false;
      reasons.push(
        `Authority check failed: role "${authority.role}" insufficient or namespace "${namespace}" not allowed`
      );
    }

    // Step 2: Rate limit check
    const rateCheck = this.checkRateLimit(authority);
    if (!rateCheck.passed) {
      allowed = false;
      reasons.push(
        `Rate limit exceeded: ${rateCheck.writesInWindow}/${rateCheck.limit} writes in window`
      );
    }

    // Step 3: Overwrite check
    const isOverwrite = existingEntries
      ? existingEntries.some((e) => e.key === key && e.namespace === namespace)
      : false;
    const overwriteCheck = {
      isOverwrite,
      allowed: isOverwrite ? authority.canOverwrite : true,
    };
    if (isOverwrite && !authority.canOverwrite) {
      allowed = false;
      reasons.push('Overwrite not permitted for this authority');
    }

    // Step 4: Contradiction detection
    let contradictions: Array<{ existingKey: string; description: string }> = [];
    if (
      this.enableContradictionTracking &&
      existingEntries &&
      existingEntries.length > 0
    ) {
      const raw = this.detectContradictions(value, existingEntries);
      contradictions = raw.map((c) => ({
        existingKey: c.entryKey,
        description: c.description,
      }));
    }

    // Step 5: Record write timestamp if allowed
    if (allowed) {
      this.recordWrite(authority.agentId);
    }

    const reason = allowed
      ? 'Write allowed'
      : reasons.join('; ');

    return {
      allowed,
      reason,
      contradictions,
      authorityCheck,
      rateCheck,
      overwriteCheck,
    };
  }

  /**
   * Register a new authority or update an existing one
   */
  registerAuthority(authority: MemoryAuthority): void {
    this.authorities.set(authority.agentId, authority);
  }

  /**
   * Compute the current confidence for an entry based on decay over time.
   *
   * Uses exponential decay: confidence = initialConfidence * e^(-decayRate * ageHours)
   * where ageHours is (now - updatedAt) / 3600000
   */
  computeConfidence(entry: MemoryEntry): number {
    if (entry.decayRate === 0) return entry.confidence;
    if (entry.decayRate >= 1) return 0;

    const now = Date.now();
    const ageMs = now - entry.updatedAt;
    const ageHours = ageMs / 3_600_000;

    const decayed = entry.confidence * Math.exp(-entry.decayRate * ageHours);
    return Math.max(0, Math.min(1, decayed));
  }

  /**
   * Get all entries whose TTL has been exceeded
   */
  getExpiredEntries(entries: MemoryEntry[]): MemoryEntry[] {
    const now = Date.now();
    return entries.filter((entry) => {
      if (entry.ttlMs === null) return false;
      return now - entry.createdAt > entry.ttlMs;
    });
  }

  /**
   * Get entries whose decayed confidence has dropped below a threshold
   */
  getDecayedEntries(entries: MemoryEntry[], threshold: number): MemoryEntry[] {
    return entries.filter((entry) => {
      const currentConfidence = this.computeConfidence(entry);
      return currentConfidence < threshold;
    });
  }

  /**
   * Detect contradictions between a new value and existing entries.
   *
   * Uses string-based pattern matching to find conflicting statements
   * (must vs never, always vs never, require vs forbid, etc.)
   */
  detectContradictions(
    newValue: unknown,
    existingEntries: MemoryEntry[]
  ): Array<{ entryKey: string; description: string }> {
    const newText = stringifyForComparison(newValue);
    const contradictions: Array<{ entryKey: string; description: string }> = [];

    for (const entry of existingEntries) {
      const existingText = stringifyForComparison(entry.value);

      for (const pattern of CONTRADICTION_PATTERNS) {
        const newMatchesPositive =
          pattern.positive.test(newText) && pattern.negative.test(existingText);
        const newMatchesNegative =
          pattern.negative.test(newText) && pattern.positive.test(existingText);

        if (newMatchesPositive || newMatchesNegative) {
          contradictions.push({
            entryKey: entry.key,
            description: pattern.description,
          });
          break; // Only report the first contradiction per entry
        }
      }
    }

    return contradictions;
  }

  /**
   * Mark a contradiction as resolved
   */
  resolveContradiction(entryKey: string, resolution: string): void {
    this.contradictionResolutions.set(entryKey, resolution);
  }

  /**
   * Get the authority for an agent by ID
   */
  getAuthorityFor(agentId: string): MemoryAuthority | undefined {
    return this.authorities.get(agentId);
  }

  /**
   * Get the current rate limit status for an agent
   */
  getRateLimitStatus(agentId: string): {
    writesInWindow: number;
    limit: number;
    resetAt: number;
  } {
    const authority = this.authorities.get(agentId);
    const limit = authority?.maxWritesPerMinute ?? 0;
    const now = Date.now();
    const windowMs = 60_000;
    const windowStart = now - windowMs;

    const timestamps = this.writeTimestamps.get(agentId) ?? [];
    const recentWrites = timestamps.filter((t) => t > windowStart);

    // Find the earliest write in the window to compute reset time
    const resetAt =
      recentWrites.length > 0
        ? recentWrites[0] + windowMs
        : now;

    return {
      writesInWindow: recentWrites.length,
      limit,
      resetAt,
    };
  }

  // ===== Accessors =====

  /** Get the default TTL in ms */
  getDefaultTtlMs(): number | null {
    return this.defaultTtlMs;
  }

  /** Get the default decay rate */
  getDefaultDecayRate(): number {
    return this.defaultDecayRate;
  }

  /** Check if contradiction tracking is enabled */
  isContradictionTrackingEnabled(): boolean {
    return this.enableContradictionTracking;
  }

  /** Get the contradiction resolution for an entry key */
  getContradictionResolution(entryKey: string): string | undefined {
    return this.contradictionResolutions.get(entryKey);
  }

  // ===== Private Methods =====

  /**
   * Check whether an authority is allowed to write to a namespace
   */
  private checkAuthority(
    authority: MemoryAuthority,
    namespace: string
  ): { passed: boolean; requiredRole: string; actualRole: string } {
    const roleLevel = ROLE_HIERARCHY[authority.role];
    const minimumLevel = ROLE_HIERARCHY[MINIMUM_WRITE_ROLE];

    // Role check: must be at least 'worker' level
    if (roleLevel < minimumLevel) {
      return {
        passed: false,
        requiredRole: MINIMUM_WRITE_ROLE,
        actualRole: authority.role,
      };
    }

    // Namespace check: must be in allowed list, or queen can write anywhere
    if (authority.role !== 'queen' && !authority.namespaces.includes(namespace)) {
      return {
        passed: false,
        requiredRole: MINIMUM_WRITE_ROLE,
        actualRole: authority.role,
      };
    }

    return {
      passed: true,
      requiredRole: MINIMUM_WRITE_ROLE,
      actualRole: authority.role,
    };
  }

  /**
   * Check rate limit using a sliding window of write timestamps
   */
  private checkRateLimit(authority: MemoryAuthority): {
    passed: boolean;
    writesInWindow: number;
    limit: number;
  } {
    const now = Date.now();
    const windowMs = 60_000;
    const windowStart = now - windowMs;

    const timestamps = this.writeTimestamps.get(authority.agentId) ?? [];
    // Prune old timestamps outside the window
    const recentWrites = timestamps.filter((t) => t > windowStart);
    this.writeTimestamps.set(authority.agentId, recentWrites);

    return {
      passed: recentWrites.length < authority.maxWritesPerMinute,
      writesInWindow: recentWrites.length,
      limit: authority.maxWritesPerMinute,
    };
  }

  /**
   * Record a write timestamp for an agent
   */
  private recordWrite(agentId: string): void {
    const timestamps = this.writeTimestamps.get(agentId) ?? [];
    timestamps.push(Date.now());
    this.writeTimestamps.set(agentId, timestamps);
  }
}

// ============================================================================
// Factory
// ============================================================================

/**
 * Create a MemoryWriteGate instance with optional configuration
 */
export function createMemoryWriteGate(
  config?: MemoryWriteGateConfig
): MemoryWriteGate {
  return new MemoryWriteGate(config);
}

// ============================================================================
// Helper: Create a MemoryEntry
// ============================================================================

/**
 * Create a new MemoryEntry with defaults applied
 */
export function createMemoryEntry(
  key: string,
  namespace: string,
  value: unknown,
  authority: MemoryAuthority,
  options: {
    ttlMs?: number | null;
    decayRate?: number;
    confidence?: number;
    lineage?: MemoryEntry['lineage'];
  } = {}
): MemoryEntry {
  const now = Date.now();
  return {
    key,
    namespace,
    value,
    valueHash: computeValueHash(value),
    authority,
    createdAt: now,
    updatedAt: now,
    ttlMs: options.ttlMs ?? null,
    decayRate: options.decayRate ?? 0,
    confidence: options.confidence ?? 1,
    lineage: options.lineage ?? { operation: 'create' },
    contradictions: [],
  };
}

/**
 * @fileoverview Meta-Governance Module
 *
 * Provides constitutional governance over the governance system itself.
 * Manages invariants, amendments, and optimizer constraints to prevent
 * governance drift and ensure constitutional stability.
 *
 * Features:
 * - Constitutional invariants with severity levels
 * - Amendment proposal and voting system
 * - Optimizer action validation
 * - Rate limiting and supermajority requirements
 * - Built-in constitutional protections
 *
 * Core capabilities:
 * - Constitutional invariant checking
 * - Amendment lifecycle (propose → vote → resolve → enact)
 * - Optimizer constraint enforcement
 * - Supermajority voting
 * - Emergency veto power
 * - Immutability protection
 *
 * @module @claude-flow/guidance/meta-governance
 * @author Claude Flow Team
 */

import { randomUUID } from 'node:crypto';

/**
 * Result of checking a constitutional invariant
 */
export interface InvariantCheckResult {
  /** Whether the invariant holds */
  holds: boolean;
  /** Description of violation if invariant does not hold */
  violation?: string;
  /** Additional details about the check */
  details?: Record<string, unknown>;
}

/**
 * Current state of the governance system for invariant checking
 */
export interface GovernanceState {
  /** Number of active governance rules */
  ruleCount: number;
  /** Size of constitution in lines */
  constitutionSize: number;
  /** Number of active gates */
  gateCount: number;
  /** Whether optimizer is enabled */
  optimizerEnabled: boolean;
  /** Number of active agents */
  activeAgentCount: number;
  /** Timestamp of last amendment */
  lastAmendmentTimestamp: number;
  /** Additional state metadata */
  metadata: Record<string, unknown>;
}

/**
 * Constitutional invariant that must hold
 */
export interface ConstitutionalInvariant {
  /** Unique identifier */
  id: string;
  /** Human-readable name */
  name: string;
  /** Description of the invariant */
  description: string;
  /** Function to check if invariant holds */
  check: (state: GovernanceState) => InvariantCheckResult;
  /** Severity level */
  severity: 'critical' | 'warning';
  /** Whether this invariant can be removed */
  immutable: boolean;
}

/**
 * A specific change within an amendment
 */
export interface AmendmentChange {
  /** Type of change */
  type: 'add-rule' | 'remove-rule' | 'modify-rule' | 'adjust-threshold' | 'add-gate' | 'remove-gate';
  /** Target of the change (rule ID, gate ID, etc.) */
  target: string;
  /** State before the change (for modify operations) */
  before?: string;
  /** State after the change */
  after?: string;
}

/**
 * Amendment to the governance system
 */
export interface Amendment {
  /** Unique identifier */
  id: string;
  /** Agent or entity that proposed the amendment */
  proposedBy: string;
  /** Description of the amendment */
  description: string;
  /** Specific changes in the amendment */
  changes: AmendmentChange[];
  /** When the amendment was proposed */
  timestamp: number;
  /** Current status */
  status: 'proposed' | 'approved' | 'rejected' | 'enacted' | 'vetoed';
  /** Votes for/against (voterId → approve) */
  votes: Map<string, boolean>;
  /** Number of approvals required to pass */
  requiredApprovals: number;
  /** Additional metadata */
  metadata?: Record<string, unknown>;
}

/**
 * Constraints on optimizer behavior
 */
export interface OptimizerConstraint {
  /** Unique identifier */
  id: string;
  /** Human-readable name */
  name: string;
  /** Description of the constraint */
  description: string;
  /** Maximum governance drift per optimization cycle (0-1) */
  maxDriftPerCycle: number;
  /** Maximum rules promoted per cycle */
  maxPromotionRate: number;
  /** Maximum rules demoted per cycle */
  maxDemotionRate: number;
  /** Cooldown between optimizer actions (ms) */
  cooldownMs: number;
}

/**
 * Action the optimizer wants to take
 */
export interface OptimizerAction {
  /** Type of action */
  type: 'promote' | 'demote' | 'add' | 'remove' | 'reweight';
  /** Target rule identifier */
  targetRuleId: string;
  /** Magnitude of the action (interpretation depends on type) */
  magnitude: number;
  /** When the action was requested */
  timestamp: number;
}

/**
 * Validation result for an optimizer action
 */
export interface OptimizerValidation {
  /** Whether the action is allowed */
  allowed: boolean;
  /** Reason for the decision */
  reason: string;
  /** Specific constraint violations */
  constraintViolations: string[];
}

/**
 * Report of all invariant checks
 */
export interface InvariantReport {
  /** Whether all invariants hold */
  allHold: boolean;
  /** Results for each invariant */
  results: Array<{
    invariant: ConstitutionalInvariant;
    result: InvariantCheckResult;
  }>;
  /** When the report was generated */
  timestamp: number;
}

/**
 * Configuration for meta-governance
 */
export interface MetaGovernanceConfig {
  /** Threshold for supermajority (0-1, default 0.75) */
  supermajorityThreshold?: number;
  /** Maximum amendments allowed per time window */
  maxAmendmentsPerWindow?: number;
  /** Time window for amendment rate limiting (ms) */
  amendmentWindowMs?: number;
  /** Optimizer constraints (partial allows overriding defaults) */
  optimizerConstraints?: Partial<OptimizerConstraint>;
  /** Optional signing key for amendments */
  signingKey?: string;
}

/**
 * Meta-Governor: Governs the governance system itself
 *
 * Enforces constitutional invariants, manages amendments,
 * and constrains optimizer behavior to prevent governance drift.
 */
export class MetaGovernor {
  private invariants: Map<string, ConstitutionalInvariant> = new Map();
  private amendments: Map<string, Amendment> = new Map();
  private amendmentHistory: Amendment[] = [];
  private optimizerConstraints: OptimizerConstraint;
  private lastOptimizerAction: number = 0;
  private optimizerActionsThisCycle: Map<string, number> = new Map();

  private readonly supermajorityThreshold: number;
  private readonly maxAmendmentsPerWindow: number;
  private readonly amendmentWindowMs: number;
  private readonly signingKey?: string;

  constructor(config: MetaGovernanceConfig = {}) {
    this.supermajorityThreshold = config.supermajorityThreshold ?? 0.75;
    this.maxAmendmentsPerWindow = config.maxAmendmentsPerWindow ?? 3;
    this.amendmentWindowMs = config.amendmentWindowMs ?? 24 * 60 * 60 * 1000; // 24 hours
    this.signingKey = config.signingKey;

    // Initialize optimizer constraints with defaults
    this.optimizerConstraints = {
      id: 'default-optimizer-constraints',
      name: 'Default Optimizer Constraints',
      description: 'Default constraints on optimizer behavior',
      maxDriftPerCycle: 0.1, // 10% change max
      maxPromotionRate: 2,
      maxDemotionRate: 1,
      cooldownMs: 3600000, // 1 hour
      ...config.optimizerConstraints,
    };

    // Add built-in invariants
    this.addBuiltInInvariants();
  }

  /**
   * Add built-in constitutional invariants
   */
  private addBuiltInInvariants(): void {
    // 1. Constitution size limit
    this.addInvariant({
      id: 'constitution-size-limit',
      name: 'Constitution Size Limit',
      description: 'Constitution must not exceed 60 lines',
      severity: 'critical',
      immutable: true,
      check: (state: GovernanceState): InvariantCheckResult => {
        const holds = state.constitutionSize <= 60;
        return {
          holds,
          violation: holds ? undefined : `Constitution size ${state.constitutionSize} exceeds limit of 60 lines`,
          details: { constitutionSize: state.constitutionSize, limit: 60 },
        };
      },
    });

    // 2. Gate minimum
    this.addInvariant({
      id: 'gate-minimum',
      name: 'Minimum Gate Count',
      description: 'At least 4 gates must be active',
      severity: 'critical',
      immutable: true,
      check: (state: GovernanceState): InvariantCheckResult => {
        const holds = state.gateCount >= 4;
        return {
          holds,
          violation: holds ? undefined : `Gate count ${state.gateCount} is below minimum of 4`,
          details: { gateCount: state.gateCount, minimum: 4 },
        };
      },
    });

    // 3. Rule count sanity
    this.addInvariant({
      id: 'rule-count-sanity',
      name: 'Rule Count Sanity Check',
      description: 'Total rules should not exceed 1000',
      severity: 'warning',
      immutable: false,
      check: (state: GovernanceState): InvariantCheckResult => {
        const holds = state.ruleCount <= 1000;
        return {
          holds,
          violation: holds ? undefined : `Rule count ${state.ruleCount} exceeds recommended limit of 1000`,
          details: { ruleCount: state.ruleCount, recommendedLimit: 1000 },
        };
      },
    });

    // 4. Optimizer bounds
    this.addInvariant({
      id: 'optimizer-bounds',
      name: 'Optimizer Drift Bounds',
      description: 'Optimizer must operate within reasonable drift bounds',
      severity: 'warning',
      immutable: false,
      check: (state: GovernanceState): InvariantCheckResult => {
        if (!state.optimizerEnabled) {
          return { holds: true, details: { optimizerEnabled: false } };
        }

        const reasonableDrift = this.optimizerConstraints.maxDriftPerCycle <= 0.2;
        return {
          holds: reasonableDrift,
          violation: reasonableDrift ? undefined : `Optimizer drift ${this.optimizerConstraints.maxDriftPerCycle} exceeds reasonable bounds`,
          details: { maxDrift: this.optimizerConstraints.maxDriftPerCycle, reasonableLimit: 0.2 },
        };
      },
    });
  }

  /**
   * Add a constitutional invariant
   */
  addInvariant(invariant: ConstitutionalInvariant): void {
    this.invariants.set(invariant.id, invariant);
  }

  /**
   * Remove an invariant (only if not immutable)
   */
  removeInvariant(id: string): boolean {
    const invariant = this.invariants.get(id);
    if (!invariant) {
      return false;
    }
    if (invariant.immutable) {
      throw new Error(`Cannot remove immutable invariant: ${id}`);
    }
    return this.invariants.delete(id);
  }

  /**
   * Check all constitutional invariants against current state
   */
  checkAllInvariants(state: GovernanceState): InvariantReport {
    const results: Array<{ invariant: ConstitutionalInvariant; result: InvariantCheckResult }> = [];
    let allHold = true;

    for (const invariant of this.invariants.values()) {
      const result = invariant.check(state);
      results.push({ invariant, result });
      if (!result.holds) {
        allHold = false;
      }
    }

    return {
      allHold,
      results,
      timestamp: Date.now(),
    };
  }

  /**
   * Propose a new amendment
   */
  proposeAmendment(
    proposal: Omit<Amendment, 'id' | 'timestamp' | 'status' | 'votes'>
  ): Amendment {
    // Check rate limiting
    const now = Date.now();
    const recentAmendments = this.amendmentHistory.filter(
      (a) => now - a.timestamp < this.amendmentWindowMs
    );

    if (recentAmendments.length >= this.maxAmendmentsPerWindow) {
      throw new Error(
        `Amendment rate limit exceeded: ${this.maxAmendmentsPerWindow} per ${this.amendmentWindowMs}ms`
      );
    }

    const amendment: Amendment = {
      id: randomUUID(),
      timestamp: now,
      status: 'proposed',
      votes: new Map(),
      ...proposal,
    };

    this.amendments.set(amendment.id, amendment);
    return amendment;
  }

  /**
   * Vote on an amendment
   */
  voteOnAmendment(amendmentId: string, voterId: string, approve: boolean): void {
    const amendment = this.amendments.get(amendmentId);
    if (!amendment) {
      throw new Error(`Amendment not found: ${amendmentId}`);
    }
    if (amendment.status !== 'proposed') {
      throw new Error(`Cannot vote on amendment with status: ${amendment.status}`);
    }

    amendment.votes.set(voterId, approve);
  }

  /**
   * Resolve an amendment (check if supermajority reached)
   */
  resolveAmendment(amendmentId: string): Amendment {
    const amendment = this.amendments.get(amendmentId);
    if (!amendment) {
      throw new Error(`Amendment not found: ${amendmentId}`);
    }
    if (amendment.status !== 'proposed') {
      throw new Error(`Amendment already resolved: ${amendment.status}`);
    }

    const totalVotes = amendment.votes.size;
    const approvals = Array.from(amendment.votes.values()).filter((v) => v).length;
    const approvalRate = totalVotes > 0 ? approvals / totalVotes : 0;

    if (approvalRate >= this.supermajorityThreshold && approvals >= amendment.requiredApprovals) {
      amendment.status = 'approved';
    } else {
      amendment.status = 'rejected';
    }

    return amendment;
  }

  /**
   * Enact an approved amendment
   * Returns true if enacted successfully
   */
  enactAmendment(amendmentId: string): boolean {
    const amendment = this.amendments.get(amendmentId);
    if (!amendment) {
      throw new Error(`Amendment not found: ${amendmentId}`);
    }
    if (amendment.status !== 'approved') {
      throw new Error(`Cannot enact amendment with status: ${amendment.status}`);
    }

    // Check if any changes would violate immutable invariants
    for (const change of amendment.changes) {
      if (change.type === 'remove-rule' || change.type === 'modify-rule') {
        const invariant = this.invariants.get(change.target);
        if (invariant?.immutable) {
          throw new Error(`Cannot modify immutable invariant: ${change.target}`);
        }
      }
    }

    amendment.status = 'enacted';
    this.amendmentHistory.push(amendment);
    this.amendments.delete(amendmentId);

    return true;
  }

  /**
   * Emergency veto of an amendment
   */
  vetoAmendment(amendmentId: string, reason: string): void {
    const amendment = this.amendments.get(amendmentId);
    if (!amendment) {
      throw new Error(`Amendment not found: ${amendmentId}`);
    }

    amendment.status = 'vetoed';
    amendment.metadata = {
      ...amendment.metadata,
      vetoReason: reason,
      vetoedAt: Date.now(),
    };

    this.amendmentHistory.push(amendment);
    this.amendments.delete(amendmentId);
  }

  /**
   * Get full amendment history
   */
  getAmendmentHistory(): Amendment[] {
    return [...this.amendmentHistory];
  }

  /**
   * Validate an optimizer action against constraints
   */
  validateOptimizerAction(action: OptimizerAction): OptimizerValidation {
    const violations: string[] = [];
    const now = Date.now();

    // Check cooldown
    if (now - this.lastOptimizerAction < this.optimizerConstraints.cooldownMs) {
      violations.push(
        `Cooldown not met: ${now - this.lastOptimizerAction}ms < ${this.optimizerConstraints.cooldownMs}ms`
      );
    }

    // Track actions this cycle
    const cycleKey = `${action.type}-${action.targetRuleId}`;
    const actionsThisCycle = this.optimizerActionsThisCycle.get(cycleKey) ?? 0;

    // Check promotion rate
    if (action.type === 'promote') {
      if (actionsThisCycle >= this.optimizerConstraints.maxPromotionRate) {
        violations.push(
          `Promotion rate exceeded: ${actionsThisCycle} >= ${this.optimizerConstraints.maxPromotionRate}`
        );
      }
    }

    // Check demotion rate
    if (action.type === 'demote') {
      if (actionsThisCycle >= this.optimizerConstraints.maxDemotionRate) {
        violations.push(
          `Demotion rate exceeded: ${actionsThisCycle} >= ${this.optimizerConstraints.maxDemotionRate}`
        );
      }
    }

    // Check drift magnitude
    if (action.magnitude > this.optimizerConstraints.maxDriftPerCycle) {
      violations.push(
        `Drift magnitude ${action.magnitude} exceeds limit ${this.optimizerConstraints.maxDriftPerCycle}`
      );
    }

    const allowed = violations.length === 0;

    if (allowed) {
      this.lastOptimizerAction = now;
      this.optimizerActionsThisCycle.set(cycleKey, actionsThisCycle + 1);
    }

    return {
      allowed,
      reason: allowed ? 'Action permitted' : `Constraint violations: ${violations.join(', ')}`,
      constraintViolations: violations,
    };
  }

  /**
   * Get current optimizer constraints
   */
  getConstraints(): OptimizerConstraint {
    return { ...this.optimizerConstraints };
  }

  /**
   * Reset optimizer action tracking (call at cycle boundaries)
   */
  resetOptimizerTracking(): void {
    this.optimizerActionsThisCycle.clear();
  }

  /**
   * Get all invariants
   */
  getInvariants(): ConstitutionalInvariant[] {
    return Array.from(this.invariants.values());
  }

  /**
   * Get pending amendments
   */
  getPendingAmendments(): Amendment[] {
    return Array.from(this.amendments.values()).filter((a) => a.status === 'proposed');
  }
}

/**
 * Factory function to create a MetaGovernor instance
 */
export function createMetaGovernor(config?: MetaGovernanceConfig): MetaGovernor {
  return new MetaGovernor(config);
}

/**
 * Optimizer Loop
 *
 * Weekly loop that edits guidance like code:
 * 1. Rank top violations by frequency and cost
 * 2. For the top 3, propose one rule change each
 * 3. Run the fixed task suite with and without the change
 * 4. Promote only if risk does not increase and rework decreases
 * 5. Record the decision in an ADR note
 *
 * Promotion rule: Local rules that win twice become root rules.
 *
 * @module @claude-flow/guidance/optimizer
 */

import { randomUUID } from 'node:crypto';
import type {
  PolicyBundle,
  GuidanceRule,
  ViolationRanking,
  RuleChange,
  ABTestResult,
  OptimizationMetrics,
  RuleADR,
} from './types.js';
import type { RunLedger } from './ledger.js';

// ============================================================================
// Optimizer Configuration
// ============================================================================

export interface OptimizerConfig {
  /** Number of top violations to address per cycle */
  topViolationsPerCycle: number;
  /** Minimum events required before optimization */
  minEventsForOptimization: number;
  /** Required improvement threshold for promotion (0-1) */
  improvementThreshold: number;
  /** Maximum risk increase tolerance (0-1) */
  maxRiskIncrease: number;
  /** Number of consecutive wins needed for promotion to root */
  promotionWins: number;
  /** ADR storage path */
  adrPath: string;
}

const DEFAULT_CONFIG: OptimizerConfig = {
  topViolationsPerCycle: 3,
  minEventsForOptimization: 10,
  improvementThreshold: 0.1,
  maxRiskIncrease: 0.05,
  promotionWins: 2,
  adrPath: './docs/adrs',
};

// ============================================================================
// Optimizer Loop
// ============================================================================

export class OptimizerLoop {
  private config: OptimizerConfig;
  private proposedChanges: RuleChange[] = [];
  private testResults: ABTestResult[] = [];
  private adrs: RuleADR[] = [];
  private promotionTracker = new Map<string, number>(); // ruleId -> win count
  private lastOptimizationRun: number | null = null;

  constructor(config: Partial<OptimizerConfig> = {}) {
    this.config = { ...DEFAULT_CONFIG, ...config };
  }

  /**
   * Run a full optimization cycle
   *
   * Steps:
   * 1. Rank violations
   * 2. Propose changes for top N
   * 3. Evaluate changes against baseline
   * 4. Promote winners, record ADRs
   */
  async runCycle(
    ledger: RunLedger,
    currentBundle: PolicyBundle
  ): Promise<{
    rankings: ViolationRanking[];
    changes: RuleChange[];
    results: ABTestResult[];
    adrs: RuleADR[];
    promoted: string[];
    demoted: string[];
  }> {
    this.lastOptimizationRun = Date.now();

    // Step 1: Rank violations
    const rankings = ledger.rankViolations();

    if (rankings.length === 0) {
      return { rankings: [], changes: [], results: [], adrs: [], promoted: [], demoted: [] };
    }

    // Step 2: Propose changes for top violations
    const topViolations = rankings.slice(0, this.config.topViolationsPerCycle);
    const changes = this.proposeChanges(topViolations, currentBundle);
    this.proposedChanges.push(...changes);

    // Step 3: Evaluate each change
    const baselineMetrics = ledger.computeMetrics();
    const results: ABTestResult[] = [];

    for (const change of changes) {
      const result = this.evaluateChange(change, baselineMetrics, ledger);
      results.push(result);
      this.testResults.push(result);
    }

    // Step 4: Promote winners, record ADRs
    const promoted: string[] = [];
    const demoted: string[] = [];
    const newAdrs: RuleADR[] = [];

    for (const result of results) {
      const adr = this.recordADR(result);
      newAdrs.push(adr);
      this.adrs.push(adr);

      if (result.shouldPromote) {
        // Track wins for promotion from local to root
        const ruleId = result.change.targetRuleId;
        const wins = (this.promotionTracker.get(ruleId) ?? 0) + 1;
        this.promotionTracker.set(ruleId, wins);

        if (wins >= this.config.promotionWins) {
          promoted.push(ruleId);
        }
      } else {
        // Demote if change failed
        const ruleId = result.change.targetRuleId;
        this.promotionTracker.set(ruleId, 0);
        if (result.change.changeType === 'promote') {
          demoted.push(ruleId);
        }
      }
    }

    return {
      rankings,
      changes,
      results,
      adrs: newAdrs,
      promoted,
      demoted,
    };
  }

  /**
   * Propose rule changes for top violations
   */
  proposeChanges(
    violations: ViolationRanking[],
    bundle: PolicyBundle
  ): RuleChange[] {
    const changes: RuleChange[] = [];

    for (const violation of violations) {
      // Find the rule
      const rule = this.findRule(violation.ruleId, bundle);

      if (rule) {
        // Existing rule that's being violated too often
        changes.push(this.proposeRuleModification(rule, violation));
      } else {
        // No rule exists for this violation type - propose new rule
        changes.push(this.proposeNewRule(violation));
      }
    }

    return changes;
  }

  /**
   * Propose modification to an existing rule
   */
  private proposeRuleModification(
    rule: GuidanceRule,
    violation: ViolationRanking
  ): RuleChange {
    // Analyze violation pattern to suggest improvement
    let proposedText = rule.text;
    let changeType: RuleChange['changeType'] = 'modify';

    if (violation.frequency > 5) {
      // Rule is violated frequently - make it more specific or add enforcement
      proposedText = `${rule.text}. This rule requires automated enforcement via gates.`;
    } else if (violation.cost > 50) {
      // Violations are expensive - elevate priority
      proposedText = `[HIGH PRIORITY] ${rule.text}. Violations of this rule are costly (avg ${violation.cost.toFixed(0)} rework lines).`;
    }

    // If rule is local and performing well, propose promotion
    if (rule.source === 'local') {
      const wins = this.promotionTracker.get(rule.id) ?? 0;
      if (wins >= this.config.promotionWins - 1) {
        changeType = 'promote';
      }
    }

    return {
      changeId: randomUUID(),
      targetRuleId: rule.id,
      changeType,
      originalText: rule.text,
      proposedText,
      rationale: `Violated ${violation.frequency} times with avg cost of ${violation.cost.toFixed(0)} rework lines (score: ${violation.score.toFixed(1)})`,
      triggeringViolation: violation,
    };
  }

  /**
   * Propose a new rule for unhandled violations
   */
  private proposeNewRule(violation: ViolationRanking): RuleChange {
    return {
      changeId: randomUUID(),
      targetRuleId: violation.ruleId,
      changeType: 'add',
      proposedText: `[${violation.ruleId}] Enforce compliance for pattern "${violation.ruleId}". Auto-generated from ${violation.frequency} violations with avg cost ${violation.cost.toFixed(0)} lines.`,
      rationale: `No existing rule covers violations classified as "${violation.ruleId}". ${violation.frequency} occurrences detected.`,
      triggeringViolation: violation,
    };
  }

  /**
   * Evaluate a proposed change against baseline metrics
   */
  evaluateChange(
    change: RuleChange,
    baseline: OptimizationMetrics,
    ledger: RunLedger
  ): ABTestResult {
    // Get events that would be affected by this rule
    const events = ledger.getEvents();
    const affectedEvents = events.filter(e =>
      e.violations.some(v => v.ruleId === change.targetRuleId) ||
      e.retrievedRuleIds.includes(change.targetRuleId)
    );

    // Compute "candidate" metrics: simulate the effect of the change
    // For now, estimate based on the violation pattern
    const candidateMetrics = this.simulateChangeEffect(change, baseline, affectedEvents.length);

    // Decision logic:
    // 1. Risk must not increase (violation rate stays same or drops)
    // 2. Rework must decrease
    const riskIncrease = candidateMetrics.violationRate - baseline.violationRate;
    const reworkDecrease = baseline.reworkLines - candidateMetrics.reworkLines;

    const shouldPromote =
      riskIncrease <= this.config.maxRiskIncrease &&
      reworkDecrease > 0 &&
      (reworkDecrease / Math.max(baseline.reworkLines, 1)) >= this.config.improvementThreshold;

    const reason = shouldPromote
      ? `Rework decreased by ${reworkDecrease.toFixed(1)} lines (${((reworkDecrease / Math.max(baseline.reworkLines, 1)) * 100).toFixed(1)}%) without increasing risk`
      : riskIncrease > this.config.maxRiskIncrease
        ? `Risk increased by ${riskIncrease.toFixed(2)} (exceeds threshold ${this.config.maxRiskIncrease})`
        : `Insufficient rework improvement (${((reworkDecrease / Math.max(baseline.reworkLines, 1)) * 100).toFixed(1)}% < ${(this.config.improvementThreshold * 100).toFixed(0)}% required)`;

    return {
      change,
      baseline,
      candidate: candidateMetrics,
      shouldPromote,
      reason,
    };
  }

  /**
   * Heuristic estimation of how a rule change would affect metrics.
   *
   * This does NOT run a real A/B test against live traffic — it applies
   * fixed multipliers per change-type to the baseline numbers.  The
   * percentages (e.g. 40% for modify, 60% for add) are conservative
   * estimates, not measured values.  Results should be treated as
   * directional guidance, not ground truth.
   */
  private simulateChangeEffect(
    change: RuleChange,
    baseline: OptimizationMetrics,
    affectedEventCount: number
  ): OptimizationMetrics {
    const affectedRatio = baseline.taskCount > 0
      ? affectedEventCount / baseline.taskCount
      : 0;

    // Conservative estimates based on change type
    let violationReduction = 0;
    let reworkReduction = 0;

    switch (change.changeType) {
      case 'modify':
        // Modifying a rule typically reduces its specific violations by 30-50%
        violationReduction = affectedRatio * 0.4;
        reworkReduction = change.triggeringViolation.cost * 0.3;
        break;
      case 'add':
        // Adding a new rule typically catches 50-70% of unhandled violations
        violationReduction = affectedRatio * 0.6;
        reworkReduction = change.triggeringViolation.cost * 0.5;
        break;
      case 'promote':
        // Promoting to root means it's always active, catching 80%+
        violationReduction = affectedRatio * 0.8;
        reworkReduction = change.triggeringViolation.cost * 0.6;
        break;
      case 'remove':
        // Removing a bad rule might increase violations temporarily
        violationReduction = -affectedRatio * 0.2;
        reworkReduction = -change.triggeringViolation.cost * 0.1;
        break;
      default:
        break;
    }

    return {
      violationRate: Math.max(0, baseline.violationRate * (1 - violationReduction)),
      selfCorrectionRate: Math.min(1, baseline.selfCorrectionRate + violationReduction * 0.1),
      reworkLines: Math.max(0, baseline.reworkLines - reworkReduction),
      clarifyingQuestions: baseline.clarifyingQuestions,
      taskCount: baseline.taskCount,
    };
  }

  /**
   * Record an ADR for a rule change decision
   */
  private recordADR(result: ABTestResult): RuleADR {
    const adrNumber = this.adrs.length + 1;

    return {
      number: adrNumber,
      title: `${result.shouldPromote ? 'Promote' : 'Reject'}: ${result.change.changeType} rule ${result.change.targetRuleId}`,
      decision: result.shouldPromote
        ? `Apply ${result.change.changeType} to rule ${result.change.targetRuleId}`
        : `Reject proposed ${result.change.changeType} for rule ${result.change.targetRuleId}`,
      rationale: result.reason,
      change: result.change,
      testResult: result,
      date: Date.now(),
    };
  }

  /**
   * Find a rule in the policy bundle
   */
  private findRule(ruleId: string, bundle: PolicyBundle): GuidanceRule | undefined {
    const constitutionRule = bundle.constitution.rules.find(r => r.id === ruleId);
    if (constitutionRule) return constitutionRule;

    const shardRule = bundle.shards.find(s => s.rule.id === ruleId);
    return shardRule?.rule;
  }

  /**
   * Apply promoted changes to a policy bundle
   */
  applyPromotions(
    bundle: PolicyBundle,
    promoted: string[],
    changes: RuleChange[]
  ): PolicyBundle {
    // Clone the bundle
    const newConstitution = { ...bundle.constitution, rules: [...bundle.constitution.rules] };
    const newShards = [...bundle.shards];

    for (const ruleId of promoted) {
      const change = changes.find(c => c.targetRuleId === ruleId);
      if (!change) continue;

      // Find the shard to promote
      const shardIdx = newShards.findIndex(s => s.rule.id === ruleId);
      if (shardIdx >= 0) {
        const shard = newShards[shardIdx];
        const promotedRule: GuidanceRule = {
          ...shard.rule,
          source: 'root',
          isConstitution: true,
          priority: shard.rule.priority + 100,
          text: change.proposedText || shard.rule.text,
          updatedAt: Date.now(),
        };

        // Add to constitution
        newConstitution.rules.push(promotedRule);

        // Remove from shards
        newShards.splice(shardIdx, 1);
      }
    }

    return {
      constitution: newConstitution,
      shards: newShards,
      manifest: bundle.manifest, // Manifest would need recompilation
    };
  }

  // ===== Getters =====

  get lastRun(): number | null {
    return this.lastOptimizationRun;
  }

  getADRs(): RuleADR[] {
    return [...this.adrs];
  }

  getProposedChanges(): RuleChange[] {
    return [...this.proposedChanges];
  }

  getTestResults(): ABTestResult[] {
    return [...this.testResults];
  }

  getPromotionTracker(): Map<string, number> {
    return new Map(this.promotionTracker);
  }
}

/**
 * Create an optimizer instance
 */
export function createOptimizer(config?: Partial<OptimizerConfig>): OptimizerLoop {
  return new OptimizerLoop(config);
}

/**
 * Ledger Persistence Layer
 *
 * Connects the in-memory RunLedger to durable file-based storage using
 * newline-delimited JSON (NDJSON). Provides append-only event logging,
 * compaction, and lock-based concurrent access prevention.
 *
 * Storage layout:
 *   {storagePath}/events.ndjson  - Newline-delimited JSON events
 *   {storagePath}/index.json     - Metadata index (counts, timestamps, task IDs)
 *   {storagePath}/.lock          - Lock file for concurrent access prevention
 *
 * @module @claude-flow/guidance/persistence
 */

import { mkdir, readFile, writeFile, appendFile, stat, unlink, rename } from 'node:fs/promises';
import { existsSync } from 'node:fs';
import { join } from 'node:path';
import { randomUUID } from 'node:crypto';
import { RunLedger } from './ledger.js';
import type { RunEvent } from './types.js';

// ============================================================================
// Types
// ============================================================================

/**
 * Configuration for the persistent ledger
 */
export interface PersistenceConfig {
  /** Directory path for storage files (default: '.claude-flow/guidance') */
  storagePath: string;
  /** Maximum events to keep; oldest evicted on compact (default: 10000) */
  maxEvents: number;
  /** How often to compact/vacuum in milliseconds (default: 1 hour) */
  compactIntervalMs: number;
  /** Enable write-ahead logging style (flush after each write) (default: true) */
  enableWAL: boolean;
}

/**
 * Storage statistics
 */
export interface StorageStats {
  /** Total number of stored events */
  eventCount: number;
  /** Storage size in bytes */
  storageSizeBytes: number;
  /** Timestamp of the oldest event (null if empty) */
  oldestEvent: number | null;
  /** Timestamp of the newest event (null if empty) */
  newestEvent: number | null;
}

/**
 * Index file structure for quick metadata lookups
 */
interface StorageIndex {
  /** Number of events in the NDJSON file */
  eventCount: number;
  /** Oldest event timestamp */
  oldestTimestamp: number | null;
  /** Newest event timestamp */
  newestTimestamp: number | null;
  /** Set of unique task IDs */
  taskIds: string[];
}

// ============================================================================
// Default Configuration
// ============================================================================

const DEFAULT_PERSISTENCE_CONFIG: PersistenceConfig = {
  storagePath: '.claude-flow/guidance',
  maxEvents: 10_000,
  compactIntervalMs: 60 * 60 * 1000, // 1 hour
  enableWAL: true,
};

// Lock file stale threshold: 30 seconds
const LOCK_STALE_MS = 30_000;

// ============================================================================
// EventStore (Internal)
// ============================================================================

/**
 * Low-level NDJSON-based event storage.
 *
 * Handles file I/O, append-only writes, range reads, compaction,
 * and lock-based concurrent access prevention.
 */
export class EventStore {
  private readonly eventsPath: string;
  private readonly indexPath: string;
  private readonly lockPath: string;
  private readonly baseDir: string;
  private lockHolder: string | null = null;

  constructor(storagePath: string) {
    this.baseDir = storagePath;
    this.eventsPath = join(storagePath, 'events.ndjson');
    this.indexPath = join(storagePath, 'index.json');
    this.lockPath = join(storagePath, '.lock');
  }

  /**
   * Append a single event to the NDJSON file and update the index.
   */
  async append(event: RunEvent): Promise<void> {
    await this.ensureDirectory();
    const line = JSON.stringify(event) + '\n';
    await appendFile(this.eventsPath, line, 'utf-8');
    await this.updateIndex(event);
  }

  /**
   * Read and parse all events from storage.
   */
  async readAll(): Promise<RunEvent[]> {
    if (!existsSync(this.eventsPath)) {
      return [];
    }

    const content = await readFile(this.eventsPath, 'utf-8');
    return this.parseNdjson(content);
  }

  /**
   * Read events within a time range [startTime, endTime].
   */
  async readRange(startTime: number, endTime: number): Promise<RunEvent[]> {
    const all = await this.readAll();
    return all.filter(e => e.timestamp >= startTime && e.timestamp <= endTime);
  }

  /**
   * Compact the event store to keep at most `maxEvents` events.
   * Oldest events are evicted first. Rewrites the NDJSON file atomically.
   *
   * @returns The number of evicted events.
   */
  async compact(maxEvents: number): Promise<number> {
    const events = await this.readAll();

    if (events.length <= maxEvents) {
      return 0;
    }

    // Sort by timestamp ascending, keep the newest maxEvents
    events.sort((a, b) => a.timestamp - b.timestamp);
    const evicted = events.length - maxEvents;
    const kept = events.slice(evicted);

    // Atomic rewrite: write to temp file, then rename
    await this.ensureDirectory();
    const tempPath = join(this.baseDir, `events.tmp.${randomUUID()}.ndjson`);
    const content = kept.map(e => JSON.stringify(e)).join('\n') + (kept.length > 0 ? '\n' : '');
    await writeFile(tempPath, content, 'utf-8');
    await rename(tempPath, this.eventsPath);

    // Rebuild index from kept events
    await this.rebuildIndex(kept);

    return evicted;
  }

  /**
   * Atomically replace all events in storage with the given array.
   * Rewrites the NDJSON file and rebuilds the index.
   */
  async writeAll(events: RunEvent[]): Promise<void> {
    await this.ensureDirectory();
    const tempPath = join(this.baseDir, `events.tmp.${randomUUID()}.ndjson`);
    const content = events.map(e => JSON.stringify(e)).join('\n') + (events.length > 0 ? '\n' : '');
    await writeFile(tempPath, content, 'utf-8');
    await rename(tempPath, this.eventsPath);
    await this.rebuildIndex(events);
  }

  /**
   * Get storage statistics.
   */
  async getStats(): Promise<StorageStats> {
    const index = await this.readIndex();
    let storageSizeBytes = 0;

    if (existsSync(this.eventsPath)) {
      const fileStat = await stat(this.eventsPath);
      storageSizeBytes = fileStat.size;
    }

    if (existsSync(this.indexPath)) {
      const indexStat = await stat(this.indexPath);
      storageSizeBytes += indexStat.size;
    }

    return {
      eventCount: index.eventCount,
      storageSizeBytes,
      oldestEvent: index.oldestTimestamp,
      newestEvent: index.newestTimestamp,
    };
  }

  /**
   * Acquire a file-based lock for concurrent access prevention.
   * Throws if the lock is already held by another process.
   */
  async acquireLock(): Promise<void> {
    await this.ensureDirectory();

    // Check for stale locks
    if (existsSync(this.lockPath)) {
      try {
        const lockContent = await readFile(this.lockPath, 'utf-8');
        const lockData = JSON.parse(lockContent);
        const age = Date.now() - lockData.timestamp;

        if (age < LOCK_STALE_MS) {
          throw new Error(
            `Storage is locked by another process (holder: ${lockData.holder}, age: ${age}ms). ` +
            `Lock file: ${this.lockPath}`
          );
        }
        // Stale lock, remove it
        await unlink(this.lockPath);
      } catch (err) {
        if (err instanceof Error && err.message.startsWith('Storage is locked')) {
          throw err;
        }
        // Corrupted lock file, remove it
        try { await unlink(this.lockPath); } catch { /* ignore */ }
      }
    }

    const holder = randomUUID();
    const lockData = { holder, timestamp: Date.now(), pid: process.pid };
    await writeFile(this.lockPath, JSON.stringify(lockData), 'utf-8');
    this.lockHolder = holder;
  }

  /**
   * Release the file-based lock.
   */
  async releaseLock(): Promise<void> {
    if (existsSync(this.lockPath)) {
      try {
        const lockContent = await readFile(this.lockPath, 'utf-8');
        const lockData = JSON.parse(lockContent);

        // Only release if we own the lock
        if (this.lockHolder && lockData.holder === this.lockHolder) {
          await unlink(this.lockPath);
        }
      } catch {
        // Best-effort removal
        try { await unlink(this.lockPath); } catch { /* ignore */ }
      }
    }
    this.lockHolder = null;
  }

  /**
   * Remove all storage files (events, index, lock).
   */
  async destroy(): Promise<void> {
    for (const filePath of [this.eventsPath, this.indexPath, this.lockPath]) {
      if (existsSync(filePath)) {
        try { await unlink(filePath); } catch { /* ignore */ }
      }
    }
  }

  // ===== Private helpers =====

  /**
   * Ensure the storage directory exists.
   */
  private async ensureDirectory(): Promise<void> {
    if (!existsSync(this.baseDir)) {
      await mkdir(this.baseDir, { recursive: true });
    }
  }

  /**
   * Parse an NDJSON string into RunEvent array, skipping blank/invalid lines.
   */
  private parseNdjson(content: string): RunEvent[] {
    const events: RunEvent[] = [];
    const lines = content.split('\n');

    for (const line of lines) {
      const trimmed = line.trim();
      if (trimmed.length === 0) continue;

      try {
        events.push(JSON.parse(trimmed) as RunEvent);
      } catch {
        // Skip malformed lines
      }
    }

    return events;
  }

  /**
   * Read the index file, returning a default if it does not exist.
   */
  private async readIndex(): Promise<StorageIndex> {
    if (!existsSync(this.indexPath)) {
      return { eventCount: 0, oldestTimestamp: null, newestTimestamp: null, taskIds: [] };
    }

    try {
      const content = await readFile(this.indexPath, 'utf-8');
      return JSON.parse(content) as StorageIndex;
    } catch {
      return { eventCount: 0, oldestTimestamp: null, newestTimestamp: null, taskIds: [] };
    }
  }

  /**
   * Update the index with a new event.
   */
  private async updateIndex(event: RunEvent): Promise<void> {
    const index = await this.readIndex();

    index.eventCount++;
    if (index.oldestTimestamp === null || event.timestamp < index.oldestTimestamp) {
      index.oldestTimestamp = event.timestamp;
    }
    if (index.newestTimestamp === null || event.timestamp > index.newestTimestamp) {
      index.newestTimestamp = event.timestamp;
    }
    if (!index.taskIds.includes(event.taskId)) {
      index.taskIds.push(event.taskId);
    }

    await writeFile(this.indexPath, JSON.stringify(index, null, 2), 'utf-8');
  }

  /**
   * Rebuild the index from a given set of events.
   */
  private async rebuildIndex(events: RunEvent[]): Promise<void> {
    const taskIdSet = new Set<string>();
    let oldest: number | null = null;
    let newest: number | null = null;

    for (const event of events) {
      taskIdSet.add(event.taskId);
      if (oldest === null || event.timestamp < oldest) {
        oldest = event.timestamp;
      }
      if (newest === null || event.timestamp > newest) {
        newest = event.timestamp;
      }
    }

    const index: StorageIndex = {
      eventCount: events.length,
      oldestTimestamp: oldest,
      newestTimestamp: newest,
      taskIds: Array.from(taskIdSet),
    };

    await this.ensureDirectory();
    await writeFile(this.indexPath, JSON.stringify(index, null, 2), 'utf-8');
  }
}

// ============================================================================
// PersistentLedger
// ============================================================================

/**
 * A RunLedger subclass that persists events to NDJSON file storage.
 *
 * Extends the in-memory RunLedger with:
 * - Automatic persistence on logEvent()
 * - Load from storage on init via importEvents()
 * - Explicit save()/load() for bulk operations
 * - Compaction to enforce maxEvents limit
 * - Storage statistics
 * - Automatic periodic compaction via interval timer
 */
export class PersistentLedger extends RunLedger {
  private readonly config: PersistenceConfig;
  private readonly store: EventStore;
  private compactTimer: ReturnType<typeof setInterval> | null = null;
  private initialized = false;

  constructor(config?: Partial<PersistenceConfig>) {
    super();
    this.config = { ...DEFAULT_PERSISTENCE_CONFIG, ...config };
    this.store = new EventStore(this.config.storagePath);
  }

  /**
   * Initialize the persistent ledger: load existing events from storage
   * and start the compaction timer.
   */
  async init(): Promise<void> {
    if (this.initialized) return;

    await this.load();
    this.startCompactTimer();
    this.initialized = true;
  }

  /**
   * Override logEvent to also persist the event to storage.
   */
  override logEvent(event: RunEvent | Omit<RunEvent, 'eventId'>): RunEvent {
    const logged = super.logEvent(event);

    // Fire-and-forget persist. If enableWAL is true, we await in a microtask
    // to minimize the chance of data loss without blocking the caller.
    if (this.config.enableWAL) {
      // Use a void promise to avoid unhandled rejection
      void this.store.append(logged).catch(() => {
        // Silently swallow persistence errors to not break the caller.
        // In production you would log this.
      });
    }

    return logged;
  }

  /**
   * Override importEvents to also persist imported events to storage.
   */
  override importEvents(events: RunEvent[]): void {
    super.importEvents(events);

    // Persist each imported event
    void (async () => {
      for (const event of events) {
        try {
          await this.store.append(event);
        } catch {
          // Silently continue
        }
      }
    })();
  }

  /**
   * Flush all in-memory events to storage, replacing the storage contents.
   * This performs a full atomic rewrite of the NDJSON file.
   */
  async save(): Promise<void> {
    const events = this.exportEvents();

    await this.store.acquireLock();
    try {
      await this.store.writeAll(events);
    } finally {
      await this.store.releaseLock();
    }
  }

  /**
   * Restore events from storage into memory.
   * Clears the in-memory ledger first, then loads all stored events.
   */
  async load(): Promise<void> {
    const events = await this.store.readAll();
    this.clear();
    if (events.length > 0) {
      super.importEvents(events);
    }
  }

  /**
   * Compact the storage to keep at most maxEvents events.
   * Also updates the in-memory ledger to match.
   *
   * @returns The number of evicted events.
   */
  async compact(): Promise<number> {
    await this.store.acquireLock();
    try {
      const evicted = await this.store.compact(this.config.maxEvents);

      if (evicted > 0) {
        // Reload in-memory state from the compacted storage
        const events = await this.store.readAll();
        this.clear();
        if (events.length > 0) {
          super.importEvents(events);
        }
      }

      return evicted;
    } finally {
      await this.store.releaseLock();
    }
  }

  /**
   * Get storage statistics.
   */
  async getStorageStats(): Promise<StorageStats> {
    return this.store.getStats();
  }

  /**
   * Clean up resources (stop compaction timer, release locks, etc.).
   */
  async destroy(): Promise<void> {
    this.stopCompactTimer();
    await this.store.releaseLock();
  }

  /**
   * Get the underlying EventStore (for advanced use / testing).
   */
  getEventStore(): EventStore {
    return this.store;
  }

  // ===== Private =====

  private startCompactTimer(): void {
    if (this.config.compactIntervalMs > 0) {
      this.compactTimer = setInterval(() => {
        void this.compact().catch(() => { /* ignore timer errors */ });
      }, this.config.compactIntervalMs);

      // Unref the timer so it doesn't keep the process alive
      if (this.compactTimer && typeof this.compactTimer === 'object' && 'unref' in this.compactTimer) {
        this.compactTimer.unref();
      }
    }
  }

  private stopCompactTimer(): void {
    if (this.compactTimer !== null) {
      clearInterval(this.compactTimer);
      this.compactTimer = null;
    }
  }
}

