// ============================================================================
// Dynamic Import Helper
// ============================================================================

/** Resolved ruvbot module cache (null = not attempted, undefined = failed). */
let ruvbotModuleCache: Record<string, unknown> | null = null;

/**
 * Module specifiers kept in variables so TypeScript does not attempt
 * compile-time resolution of this optional peer dependency.
 */
const RUVBOT_MODULE = 'ruvbot';
const RUVBOT_CORE_MODULE = 'ruvbot/core';

/**
 * Attempt to dynamically import the ruvbot package.
 * Throws a descriptive error if the package is not installed.
 */
async function requireRuvBot(): Promise<Record<string, unknown>> {
  if (ruvbotModuleCache) return ruvbotModuleCache;

  try {
    const mod = await import(RUVBOT_MODULE) as Record<string, unknown>;
    ruvbotModuleCache = mod;
    return mod;
  } catch {
    throw new Error(
      'ruvbot is not installed. Install it with: npm install ruvbot@0.1.8\n' +
      'ruvbot is an optional peer dependency of @claude-flow/guidance.',
    );
  }
}

/**
 * Attempt to dynamically import ruvbot/core sub-export.
 */
async function requireRuvBotCore(): Promise<Record<string, unknown>> {
  try {
    return await import(RUVBOT_CORE_MODULE) as Record<string, unknown>;
  } catch {
    // Fall back to the main export
    return requireRuvBot();
  }
}

// ============================================================================
// AIDefenceGate
// ============================================================================

/**
 * Wraps ruvbot's 6-layer AIDefence as an enforcement gate compatible with the
 * guidance control plane's GateResult / GateDecision interface.
 *
 * Supports:
 * - Prompt injection detection
 * - Jailbreak detection
 * - PII detection
 * - Control character and homoglyph detection (via ruvbot internals)
 * - Configurable sensitivity / block threshold
 *
 * Evaluates both input (pre-processing) and output (post-processing) text.
 */
export class AIDefenceGate {
  private config: AIDefenceGateConfig;
  private guard: RuvBotAIDefenceGuard | null = null;
  private guardInitPromise: Promise<void> | null = null;

  constructor(config: Partial<AIDefenceGateConfig> = {}) {
    this.config = {
      detectPromptInjection: config.detectPromptInjection ?? true,
      detectJailbreak: config.detectJailbreak ?? true,
      detectPII: config.detectPII ?? true,
      blockThreshold: config.blockThreshold ?? 'medium',
    };
  }

  /**
   * Lazily initialize the underlying ruvbot AIDefence guard.
   * Safe to call multiple times; only the first call creates the guard.
   */
  private async ensureGuard(): Promise<RuvBotAIDefenceGuard> {
    if (this.guard) return this.guard;

    if (!this.guardInitPromise) {
      this.guardInitPromise = (async () => {
        const mod = await requireRuvBot();
        const createGuard = mod['createAIDefenceGuard'] as
          | ((config?: Record<string, unknown>) => RuvBotAIDefenceGuard)
          | undefined;

        if (typeof createGuard !== 'function') {
          throw new Error(
            'ruvbot does not export createAIDefenceGuard. ' +
            'Ensure ruvbot@0.1.8 or later is installed.',
          );
        }

        this.guard = createGuard({
          detectPromptInjection: this.config.detectPromptInjection,
          detectJailbreak: this.config.detectJailbreak,
          detectPII: this.config.detectPII,
        });
      })();
    }

    await this.guardInitPromise;
    return this.guard!;
  }

  /**
   * Evaluate input text for threats (pre-processing gate).
   *
   * Checks for prompt injection, jailbreak attempts, and PII based
   * on the configured sensitivity.
   */
  async evaluateInput(input: string): Promise<AIDefenceResult> {
    const start = performance.now();

    const guard = await this.ensureGuard();
    const raw = await guard.check(input);
    const latencyMs = performance.now() - start;

    const threats = this.normalizeThreats(raw.threats);

    return {
      safe: raw.safe,
      threats,
      sanitizedInput: raw.sanitizedInput,
      latencyMs,
    };
  }

  /**
   * Evaluate output text for threats (post-processing gate).
   *
   * Primarily checks for PII leakage and secret exposure in responses.
   */
  async evaluateOutput(output: string): Promise<AIDefenceResult> {
    const start = performance.now();

    const guard = await this.ensureGuard();
    const raw = await guard.check(output);
    const latencyMs = performance.now() - start;

    // For output evaluation, focus on PII / data leakage threats
    const threats = this.normalizeThreats(raw.threats).filter(
      t => t.type === 'pii' || t.type === 'control-chars',
    );

    return {
      safe: threats.length === 0,
      threats,
      sanitizedInput: raw.sanitizedInput,
      latencyMs,
    };
  }

  /**
   * Convert an AIDefenceResult into a GateResult compatible with the
   * guidance enforcement pipeline.
   *
   * Decision logic:
   * - If no threats: 'allow'
   * - If threats above block threshold: 'block'
   * - Otherwise: 'warn'
   */
  toGateResult(result: AIDefenceResult, context?: string): GateResult {
    if (result.safe && result.threats.length === 0) {
      return {
        decision: 'allow',
        gateName: 'ai-defence',
        reason: 'AIDefence check passed with no threats detected.',
        triggeredRules: [],
        metadata: { latencyMs: result.latencyMs },
      };
    }

    const blockingSeverities = BLOCK_SEVERITY_THRESHOLDS[this.config.blockThreshold];
    const blockingThreats = result.threats.filter(
      t => blockingSeverities.has(t.severity),
    );

    const decision: GateDecision = blockingThreats.length > 0 ? 'block' : 'warn';

    const threatSummary = result.threats
      .map(t => `${t.type} (${t.severity}): ${t.detail}`)
      .join('; ');

    return {
      decision,
      gateName: 'ai-defence',
      reason: `AIDefence detected ${result.threats.length} threat(s): ${threatSummary}`,
      triggeredRules: [],
      remediation: this.buildRemediation(result.threats),
      metadata: {
        threats: result.threats,
        blockThreshold: this.config.blockThreshold,
        latencyMs: result.latencyMs,
        context,
      },
    };
  }

  /**
   * Get the current configuration.
   */
  getConfig(): AIDefenceGateConfig {
    return { ...this.config };
  }

  /**
   * Update configuration. Resets the guard so the next evaluation
   * re-initializes with the new settings.
   */
  updateConfig(config: Partial<AIDefenceGateConfig>): void {
    this.config = { ...this.config, ...config };
    this.guard = null;
    this.guardInitPromise = null;
  }

  // ===== Private Helpers =====

  private normalizeThreats(
    raw: Array<{ type: string; severity: string; detail: string }>,
  ): AIDefenceThreat[] {
    return raw.map(t => ({
      type: THREAT_TYPE_MAP[t.type] ?? 'prompt-injection',
      severity: SEVERITY_MAP[t.severity] ?? 'medium',
      detail: t.detail,
    }));
  }

  private buildRemediation(threats: AIDefenceThreat[]): string {
    const parts: string[] = [];

    const hasInjection = threats.some(t => t.type === 'prompt-injection');
    const hasJailbreak = threats.some(t => t.type === 'jailbreak');
    const hasPII = threats.some(t => t.type === 'pii');

    if (hasInjection) {
      parts.push('1. Review input for prompt injection patterns and remove adversarial content.');
    }
    if (hasJailbreak) {
      parts.push('2. Input contains jailbreak attempt. Reject and log the attempt.');
    }
    if (hasPII) {
      parts.push('3. Redact or mask personally identifiable information before processing.');
    }
    if (parts.length === 0) {
      parts.push('Review flagged content and apply appropriate sanitization.');
    }

    return parts.join('\n');
  }
}

// ============================================================================
// RuvBotMemoryAdapter
// ============================================================================

/**
 * Wraps ruvbot's memory read/write operations with guidance control plane
 * governance. Every write passes through the MemoryWriteGate for authority
 * and coherence checks. All operations are logged to a proof chain.
 */
export class RuvBotMemoryAdapter {
  private readonly memoryGate: import('./memory-gate.js').MemoryWriteGate;
  private readonly coherenceScheduler: import('./coherence.js').CoherenceScheduler;
  private proofChain: import('./proof.js').ProofChain | null = null;
  private ruvbotMemory: RuvBotMemory | null = null;
  private operationLog: Array<{
    operation: 'read' | 'write' | 'delete';
    key: string;
    namespace: string;
    timestamp: number;
    decision?: WriteDecision;
  }> = [];

  constructor(
    memoryGate: import('./memory-gate.js').MemoryWriteGate,
    coherenceScheduler: import('./coherence.js').CoherenceScheduler,
  ) {
    this.memoryGate = memoryGate;
    this.coherenceScheduler = coherenceScheduler;
  }

  /**
   * Attach a ruvbot memory instance for proxied operations.
   */
  attachMemory(memory: RuvBotMemory): void {
    this.ruvbotMemory = memory;
  }

  /**
   * Attach a proof chain for operation logging.
   */
  attachProofChain(proofChain: import('./proof.js').ProofChain): void {
    this.proofChain = proofChain;
  }

  /**
   * Governed read: reads through ruvbot memory, logs to proof chain.
   */
  async read(
    key: string,
    namespace: string = 'default',
  ): Promise<unknown> {
    this.ensureMemoryAttached();

    const value = await this.ruvbotMemory!.read(key, namespace);

    this.operationLog.push({
      operation: 'read',
      key,
      namespace,
      timestamp: Date.now(),
    });

    return value;
  }

  /**
   * Governed write: runs through MemoryWriteGate, checks coherence,
   * logs to proof chain, then delegates to ruvbot memory.
   *
   * Returns the WriteDecision. If denied, the write is not performed.
   */
  async write(
    key: string,
    namespace: string,
    value: unknown,
    authority: MemoryAuthority,
    existingEntries?: MemoryEntry[],
  ): Promise<WriteDecision> {
    this.ensureMemoryAttached();

    // Step 1: Evaluate through MemoryWriteGate
    const decision = this.memoryGate.evaluateWrite(
      authority,
      key,
      namespace,
      value,
      existingEntries,
    );

    // Step 2: Log the operation
    this.operationLog.push({
      operation: 'write',
      key,
      namespace,
      timestamp: Date.now(),
      decision,
    });

    // Step 3: If denied, do not write
    if (!decision.allowed) {
      return decision;
    }

    // Step 4: Perform the write through ruvbot
    await this.ruvbotMemory!.write(key, value, namespace);

    return decision;
  }

  /**
   * Governed delete: checks authority, logs, then delegates.
   */
  async delete(
    key: string,
    namespace: string,
    authority: MemoryAuthority,
  ): Promise<{ allowed: boolean; reason: string }> {
    this.ensureMemoryAttached();

    // Authority must have delete permission
    if (!authority.canDelete) {
      const result = {
        allowed: false,
        reason: `Agent "${authority.agentId}" does not have delete permission.`,
      };

      this.operationLog.push({
        operation: 'delete',
        key,
        namespace,
        timestamp: Date.now(),
      });

      return result;
    }

    // Perform the delete if the underlying memory supports it
    if (typeof this.ruvbotMemory!.delete === 'function') {
      await this.ruvbotMemory!.delete(key, namespace);
    }

    this.operationLog.push({
      operation: 'delete',
      key,
      namespace,
      timestamp: Date.now(),
    });

    return { allowed: true, reason: 'Delete permitted and executed.' };
  }

  /**
   * Get the operation log for audit/proof purposes.
   */
  getOperationLog(): ReadonlyArray<{
    operation: 'read' | 'write' | 'delete';
    key: string;
    namespace: string;
    timestamp: number;
    decision?: WriteDecision;
  }> {
    return this.operationLog;
  }

  /**
   * Get the count of governed operations.
   */
  get operationCount(): number {
    return this.operationLog.length;
  }

  /**
   * Clear the operation log.
   */
  clearLog(): void {
    this.operationLog = [];
  }

  // ===== Private Helpers =====

  private ensureMemoryAttached(): void {
    if (!this.ruvbotMemory) {
      throw new Error(
        'No ruvbot memory instance attached. Call attachMemory() before ' +
        'performing memory operations.',
      );
    }
  }
}

// ============================================================================
// RuvBotGuidanceBridge
// ============================================================================

/**
 * Bridges a ruvbot instance with the @claude-flow/guidance control plane.
 *
 * Wires ruvbot event hooks to guidance enforcement and trust systems:
 *
 * - `message`        -> EnforcementGates (secrets, destructive ops) + AIDefence
 * - `agent:spawn`    -> ManifestValidator
 * - `session:create` -> ProofChain initialization
 * - `session:end`    -> ProofChain finalization and ledger persistence
 * - `ready`          -> Trust accumulator initialization
 * - `error`          -> Trust 'deny' outcome recording
 *
 * All gate outcomes are fed into the TrustAccumulator so that ruvbot agents
 * build (or lose) trust over time.
 */
export class RuvBotGuidanceBridge {
  private readonly config: RuvBotBridgeConfig;
  private ruvbot: RuvBotInstance | null = null;

  // Guidance components (injected)
  private gates: import('./gates.js').EnforcementGates | null = null;
  private manifestValidator: import('./manifest-validator.js').ManifestValidator | null = null;
  private trustSystem: import('./trust.js').TrustSystem | null = null;
  private aiDefenceGate: AIDefenceGate | null = null;
  private memoryAdapter: RuvBotMemoryAdapter | null = null;

  // Session proof chains keyed by sessionId
  private sessionChains: Map<string, import('./proof.js').ProofChain> = new Map();

  // Bound event handlers for cleanup
  private boundHandlers: Map<string, (...args: unknown[]) => void> = new Map();

  // Event log for diagnostics
  private eventLog: RuvBotEvent[] = [];
  private static readonly MAX_EVENT_LOG = 1000;

  constructor(config: Partial<RuvBotBridgeConfig> = {}) {
    this.config = {
      enableAIDefence: config.enableAIDefence ?? true,
      enableMemoryGovernance: config.enableMemoryGovernance ?? true,
      enableTrustTracking: config.enableTrustTracking ?? true,
      enableProofChain: config.enableProofChain ?? true,
    };
  }

  /**
   * Attach guidance control plane components.
   *
   * Accepts either a full GuidanceControlPlane instance (from which
   * sub-components are extracted) or individual components.
   */
  attachGuidance(components: {
    gates?: import('./gates.js').EnforcementGates;
    manifestValidator?: import('./manifest-validator.js').ManifestValidator;
    trustSystem?: import('./trust.js').TrustSystem;
    aiDefenceGate?: AIDefenceGate;
    memoryAdapter?: RuvBotMemoryAdapter;
  }): void {
    if (components.gates) this.gates = components.gates;
    if (components.manifestValidator) this.manifestValidator = components.manifestValidator;
    if (components.trustSystem) this.trustSystem = components.trustSystem;
    if (components.aiDefenceGate) this.aiDefenceGate = components.aiDefenceGate;
    if (components.memoryAdapter) this.memoryAdapter = components.memoryAdapter;
  }

  /**
   * Connect to a ruvbot instance and wire all event handlers.
   *
   * This is the primary entry point. Once called, the bridge will
   * intercept ruvbot events and route them through guidance gates.
   */
  connect(ruvbot: RuvBotInstance): void {
    if (this.ruvbot) {
      this.disconnect();
    }

    this.ruvbot = ruvbot;

    // Wire event handlers
    this.wireEvent('message', this.handleMessage.bind(this));
    this.wireEvent('agent:spawn', this.handleAgentSpawn.bind(this));
    this.wireEvent('session:create', this.handleSessionCreate.bind(this));
    this.wireEvent('session:end', this.handleSessionEnd.bind(this));
    this.wireEvent('ready', this.handleReady.bind(this));
    this.wireEvent('shutdown', this.handleShutdown.bind(this));
    this.wireEvent('error', this.handleError.bind(this));
    this.wireEvent('agent:stop', this.handleAgentStop.bind(this));
  }

  /**
   * Disconnect from the ruvbot instance, removing all event handlers.
   */
  disconnect(): void {
    if (!this.ruvbot) return;

    for (const [event, handler] of this.boundHandlers) {
      this.ruvbot.off(event, handler);
    }

    this.boundHandlers.clear();
    this.ruvbot = null;
  }

  /**
   * Evaluate a ruvbot AIDefence result and return a GateResult-compatible
   * decision. Can be called independently of event wiring.
   */
  async evaluateAIDefence(input: string): Promise<GateResult> {
    if (!this.aiDefenceGate) {
      throw new Error(
        'AIDefenceGate not attached. Call attachGuidance({ aiDefenceGate }) first.',
      );
    }

    const result = await this.aiDefenceGate.evaluateInput(input);
    return this.aiDefenceGate.toGateResult(result, 'manual-evaluation');
  }

  /**
   * Get the proof chain for a specific session.
   */
  getSessionProofChain(sessionId: string): import('./proof.js').ProofChain | undefined {
    return this.sessionChains.get(sessionId);
  }

  /**
   * Get all active session IDs.
   */
  getActiveSessionIds(): string[] {
    return [...this.sessionChains.keys()];
  }

  /**
   * Get the event log for diagnostics.
   */
  getEventLog(): ReadonlyArray<RuvBotEvent> {
    return this.eventLog;
  }

  /**
   * Get the current bridge configuration.
   */
  getConfig(): RuvBotBridgeConfig {
    return { ...this.config };
  }

  /**
   * Whether the bridge is currently connected to a ruvbot instance.
   */
  get connected(): boolean {
    return this.ruvbot !== null;
  }

  // ===== Event Handlers =====

  /**
   * Handle `message` events: run content through enforcement gates
   * and optionally through AIDefence.
   */
  private async handleMessage(...args: unknown[]): Promise<void> {
    const data = (args[0] ?? {}) as Record<string, unknown>;
    const content = String(data['content'] ?? data['text'] ?? '');
    const sessionId = String(data['sessionId'] ?? 'unknown');
    const agentId = String(data['agentId'] ?? 'unknown');

    this.logEvent('message', { sessionId, agentId, contentLength: content.length });

    const gateResults: GateResult[] = [];

    // Step 1: Run through EnforcementGates (secrets, destructive ops)
    if (this.gates) {
      const commandResults = this.gates.evaluateCommand(content);
      gateResults.push(...commandResults);
    }

    // Step 2: Run through AIDefence gate
    if (this.config.enableAIDefence && this.aiDefenceGate) {
      try {
        const defenceResult = await this.aiDefenceGate.evaluateInput(content);
        const gateResult = this.aiDefenceGate.toGateResult(defenceResult, `message:${sessionId}`);
        if (gateResult.decision !== 'allow') {
          gateResults.push(gateResult);
        }
      } catch {
        // AIDefence unavailable; log but do not block
      }
    }

    // Step 3: Feed outcomes into trust accumulator
    if (this.config.enableTrustTracking && this.trustSystem) {
      if (gateResults.length === 0) {
        this.trustSystem.recordOutcome(
          agentId,
          'allow',
          `Message passed all gates (session: ${sessionId})`,
        );
      } else {
        for (const result of gateResults) {
          const outcome = gateDecisionToTrustOutcome(result.decision);
          this.trustSystem.recordOutcome(
            agentId,
            outcome,
            `Gate "${result.gateName}" ${result.decision}: ${result.reason}`,
          );
        }
      }
    }
  }

  /**
   * Handle `agent:spawn` events: validate agent manifest.
   */
  private async handleAgentSpawn(...args: unknown[]): Promise<void> {
    const data = (args[0] ?? {}) as Record<string, unknown>;
    const agentId = String(data['agentId'] ?? data['id'] ?? 'unknown');
    const manifest = data['manifest'] as import('./manifest-validator.js').AgentCellManifest | undefined;

    this.logEvent('agent:spawn', { agentId, hasManifest: !!manifest });

    if (this.manifestValidator && manifest) {
      const validation = this.manifestValidator.validate(manifest);

      if (this.config.enableTrustTracking && this.trustSystem) {
        if (validation.admissionDecision === 'admit') {
          this.trustSystem.recordOutcome(
            agentId,
            'allow',
            `Agent manifest validated: admission=${validation.admissionDecision}, risk=${validation.riskScore}`,
          );
        } else {
          const outcome: GateOutcome = validation.admissionDecision === 'reject' ? 'deny' : 'warn';
          this.trustSystem.recordOutcome(
            agentId,
            outcome,
            `Agent manifest ${validation.admissionDecision}: risk=${validation.riskScore}, errors=${validation.errors.length}`,
          );
        }
      }
    }
  }

  /**
   * Handle `session:create` events: initialize a proof chain for the session.
   */
  private async handleSessionCreate(...args: unknown[]): Promise<void> {
    const data = (args[0] ?? {}) as Record<string, unknown>;
    const sessionId = String(data['sessionId'] ?? data['id'] ?? `session-${Date.now()}`);

    this.logEvent('session:create', { sessionId });

    if (this.config.enableProofChain) {
      if (!this.config.proofSigningKey) {
        throw new Error(
          'RuvBotBridgeConfig.proofSigningKey is required when enableProofChain is true',
        );
      }
      const { createProofChain } = await import('./proof.js');
      const chain = createProofChain({ signingKey: this.config.proofSigningKey });
      this.sessionChains.set(sessionId, chain);
    }
  }

  /**
   * Handle `session:end` events: finalize the proof chain and persist.
   */
  private async handleSessionEnd(...args: unknown[]): Promise<void> {
    const data = (args[0] ?? {}) as Record<string, unknown>;
    const sessionId = String(data['sessionId'] ?? data['id'] ?? 'unknown');

    this.logEvent('session:end', { sessionId });

    if (this.config.enableProofChain) {
      const chain = this.sessionChains.get(sessionId);
      if (chain) {
        // Export the finalized chain for external persistence
        const _exported = chain.export();
        // The caller can retrieve this via getSessionProofChain() before
        // the session is cleaned up, or listen for an event.

        // Clean up
        this.sessionChains.delete(sessionId);
      }
    }
  }

  /**
   * Handle `ready` events: log bridge activation.
   */
  private async handleReady(...args: unknown[]): Promise<void> {
    this.logEvent('ready', {});
  }

  /**
   * Handle `shutdown` events: clean up all session proof chains.
   */
  private async handleShutdown(...args: unknown[]): Promise<void> {
    this.logEvent('shutdown', {});
    this.sessionChains.clear();
  }

  /**
   * Handle `error` events: record a deny outcome in trust tracking.
   */
  private async handleError(...args: unknown[]): Promise<void> {
    const data = (args[0] ?? {}) as Record<string, unknown>;
    const agentId = String(data['agentId'] ?? 'unknown');
    const errorMessage = String(data['message'] ?? data['error'] ?? 'unknown error');

    this.logEvent('error', { agentId, error: errorMessage });

    if (this.config.enableTrustTracking && this.trustSystem) {
      this.trustSystem.recordOutcome(
        agentId,
        'deny',
        `Error event: ${errorMessage}`,
      );
    }
  }

  /**
   * Handle `agent:stop` events: record final trust snapshot.
   */
  private async handleAgentStop(...args: unknown[]): Promise<void> {
    const data = (args[0] ?? {}) as Record<string, unknown>;
    const agentId = String(data['agentId'] ?? data['id'] ?? 'unknown');

    this.logEvent('agent:stop', { agentId });
  }

  // ===== Private Helpers =====

  private wireEvent(event: string, handler: (...args: unknown[]) => void): void {
    this.boundHandlers.set(event, handler);
    this.ruvbot!.on(event, handler);
  }

  private logEvent(type: string, data: Record<string, unknown>): void {
    const event: RuvBotEvent = {
      type,
      timestamp: Date.now(),
      sessionId: data['sessionId'] as string | undefined,
      agentId: data['agentId'] as string | undefined,
      data,
    };

    this.eventLog.push(event);

    if (this.eventLog.length > RuvBotGuidanceBridge.MAX_EVENT_LOG) {
      this.eventLog = this.eventLog.slice(-RuvBotGuidanceBridge.MAX_EVENT_LOG);
    }
  }
}

// ============================================================================
// Helper Functions
// ============================================================================

/**
 * Map a GateDecision to a GateOutcome for trust accumulation.
 *
 * - 'allow' -> 'allow'
 * - 'block' -> 'deny'
 * - 'require-confirmation' -> 'warn'
 * - 'warn' -> 'warn'
 */
function gateDecisionToTrustOutcome(decision: GateDecision): GateOutcome {
  switch (decision) {
    case 'allow': return 'allow';
    case 'block': return 'deny';
    case 'warn': return 'warn';
    case 'require-confirmation': return 'warn';
    default: return 'warn';
  }
}

// ============================================================================
// Factory Functions
// ============================================================================

/**
 * Create a fully wired RuvBotGuidanceBridge.
 *
 * Connects the bridge to a ruvbot instance and attaches the guidance
 * control plane components. The bridge immediately begins intercepting
 * ruvbot events.
 *
 * @param ruvbotInstance - A ruvbot instance (from createRuvBot())
 * @param guidancePlane - A GuidanceControlPlane or individual components
 * @param config - Optional bridge configuration
 * @returns The connected RuvBotGuidanceBridge
 */
export function createRuvBotBridge(
  ruvbotInstance: RuvBotInstance,
  guidancePlane: {
    gates?: import('./gates.js').EnforcementGates;
    manifestValidator?: import('./manifest-validator.js').ManifestValidator;
    trustSystem?: import('./trust.js').TrustSystem;
    aiDefenceGate?: AIDefenceGate;
    memoryAdapter?: RuvBotMemoryAdapter;
  },
  config?: Partial<RuvBotBridgeConfig>,
): RuvBotGuidanceBridge {
  const bridge = new RuvBotGuidanceBridge(config);
  bridge.attachGuidance(guidancePlane);
  bridge.connect(ruvbotInstance);
  return bridge;
}

/**
 * Create an AIDefenceGate with optional configuration.
 *
 * The gate lazily initializes the underlying ruvbot AIDefence guard
 * on the first evaluation call.
 *
 * @param config - Optional gate configuration
 * @returns A new AIDefenceGate instance
 */
export function createAIDefenceGate(
  config?: Partial<AIDefenceGateConfig>,
): AIDefenceGate {
  return new AIDefenceGate(config);
}

/**
 * Create a RuvBotMemoryAdapter with governance components.
 *
 * The adapter wraps ruvbot memory operations with MemoryWriteGate authority
 * checks and CoherenceScheduler tracking.
 *
 * @param memoryGate - The MemoryWriteGate for authority/rate/contradiction checks
 * @param coherenceScheduler - The CoherenceScheduler for drift tracking
 * @returns A new RuvBotMemoryAdapter instance
 */
export function createRuvBotMemoryAdapter(
  memoryGate: import('./memory-gate.js').MemoryWriteGate,
  coherenceScheduler: import('./coherence.js').CoherenceScheduler,
): RuvBotMemoryAdapter {
  return new RuvBotMemoryAdapter(memoryGate, coherenceScheduler);
}

/**
 * Temporal Assertions and Validity Windows
 *
 * Bitemporal semantics for knowledge: distinguishes *assertion time* (when
 * something was recorded) from *validity time* (when the fact is/was/will be
 * true in the real world).
 *
 * The system tracks two independent timelines:
 * - Assertion time: when the assertion was recorded and when it was retracted
 * - Validity time: when the fact becomes true (validFrom) and stops being true
 *   (validUntil)
 *
 * Every assertion carries `validFrom`, `validUntil`, `assertedAt`, and
 * `supersededBy` fields. Status is computed dynamically from the current clock
 * and the assertion's lifecycle flags (retraction, supersession, expiration).
 *
 * TemporalStore:
 * - Creates assertions with explicit validity windows
 * - Retrieves assertions active at any point in time (past, present, future)
 * - Supports supersession chains (old fact replaced by new fact)
 * - Soft-delete via retraction (preserves full history)
 * - Conflict detection: finds multiple active assertions in the same namespace
 * - Export/import for persistence
 *
 * TemporalReasoner:
 * - High-level queries: whatWasTrue, whatIsTrue, whatWillBeTrue
 * - Change detection since a given timestamp
 * - Conflict detection at a point in time
 * - Forward projection of assertion validity
 *
 * @module @claude-flow/guidance/temporal
 */

import { randomUUID } from 'node:crypto';

// ============================================================================
// Types
// ============================================================================

/**
 * Computed lifecycle status of a temporal assertion.
 *
 * - future: the validity window has not yet opened (validFrom > now)
 * - active: the assertion is currently valid (validFrom <= now < validUntil)
 * - expired: the validity window has closed (validUntil <= now)
 * - superseded: replaced by a newer assertion
 * - retracted: explicitly withdrawn (soft-deleted, history preserved)
 */
export type TemporalStatus = 'future' | 'active' | 'expired' | 'superseded' | 'retracted';

/**
 * The temporal window describing when a fact is valid and when it was recorded.
 */
export interface ValidityWindow {
  /** Unix timestamp (ms) when the fact becomes true in the real world */
  validFrom: number;
  /** Unix timestamp (ms) when the fact stops being true, or null for indefinite */
  validUntil: number | null;
  /** Unix timestamp (ms) when the assertion was recorded in the system */
  assertedAt: number;
  /** Unix timestamp (ms) when the assertion was retracted, or null if still standing */
  retractedAt: number | null;
}

/**
 * A single temporal assertion: a claim with an explicit validity window,
 * supersession chain, confidence, and provenance metadata.
 */
export interface TemporalAssertion {
  /** Unique assertion identifier (UUID v4) */
  id: string;
  /** The claim being asserted, in natural language */
  claim: string;
  /** Namespace for grouping related assertions */
  namespace: string;
  /** The temporal validity window */
  window: ValidityWindow;
  /** Computed lifecycle status (derived from window + retraction + supersession) */
  status: TemporalStatus;
  /** ID of the assertion that replaced this one, or null */
  supersededBy: string | null;
  /** ID of the assertion that this one replaces, or null */
  supersedes: string | null;
  /** Confidence in the assertion (0.0 - 1.0) */
  confidence: number;
  /** Who or what made this assertion */
  source: string;
  /** Searchable tags */
  tags: string[];
  /** Arbitrary metadata */
  metadata: Record<string, unknown>;
}

/**
 * Query options for filtering temporal assertions.
 */
export interface TemporalQuery {
  /** Filter by namespace */
  namespace?: string;
  /** Return only assertions active at this point in time */
  pointInTime?: number;
  /** Filter by status (any match) */
  status?: TemporalStatus[];
  /** Filter by source */
  source?: string;
  /** Filter by tags (all must be present) */
  tags?: string[];
}

/**
 * Configuration for the TemporalStore.
 */
export interface TemporalConfig {
  /** Maximum number of assertions to store (default 100000) */
  maxAssertions: number;
  /** Interval (ms) for auto-expire status checks (default 60000) */
  autoExpireCheckIntervalMs: number;
}

/**
 * A full timeline for an assertion: its predecessors and successors in the
 * supersession chain.
 */
export interface TemporalTimeline {
  /** The assertion at the center of the timeline */
  assertion: TemporalAssertion;
  /** Assertions that were replaced leading up to this one (oldest first) */
  predecessors: TemporalAssertion[];
  /** Assertions that replaced this one (newest last) */
  successors: TemporalAssertion[];
}

/**
 * A detected change in the temporal store since a given timestamp.
 */
export interface TemporalChange {
  /** The assertion that changed */
  assertion: TemporalAssertion;
  /** The kind of change */
  changeType: 'asserted' | 'superseded' | 'retracted' | 'expired';
  /** When the change occurred (assertion time, retraction time, etc.) */
  changedAt: number;
}

/**
 * Optional parameters when creating a new assertion.
 */
export interface AssertOptions {
  /** Custom assertion ID (default: auto-generated UUID) */
  id?: string;
  /** Confidence in the assertion (0.0 - 1.0, default 1.0) */
  confidence?: number;
  /** Who or what is making this assertion (default 'system') */
  source?: string;
  /** Searchable tags */
  tags?: string[];
  /** Arbitrary metadata */
  metadata?: Record<string, unknown>;
}

/**
 * Serializable representation for export/import.
 */
export interface SerializedTemporalStore {
  /** All assertions */
  assertions: TemporalAssertion[];
  /** When the export was created */
  createdAt: string;
  /** Schema version */
  version: number;
}

// ============================================================================
// Default Configuration
// ============================================================================

const DEFAULT_TEMPORAL_CONFIG: TemporalConfig = {
  maxAssertions: 100_000,
  autoExpireCheckIntervalMs: 60_000,
};

const SERIALIZATION_VERSION = 1;

// ============================================================================
// TemporalStore
// ============================================================================

/**
 * In-memory store for temporal assertions with bitemporal semantics.
 *
 * Assertions are indexed by ID and support supersession chains, retraction,
 * temporal queries (what was active at time T), and conflict detection.
 * Status is computed dynamically from the assertion's window and lifecycle
 * flags; callers never set status directly.
 */
export class TemporalStore {
  private readonly config: TemporalConfig;
  private readonly assertions: Map<string, TemporalAssertion> = new Map();

  constructor(config: Partial<TemporalConfig> = {}) {
    this.config = { ...DEFAULT_TEMPORAL_CONFIG, ...config };
  }

  /**
   * Create a new temporal assertion.
   *
   * Records a claim with an explicit validity window. The assertion's status
   * is computed automatically from the window and the current time.
   *
   * @param claim - The fact being asserted
   * @param namespace - Grouping namespace
   * @param window - Validity window (validFrom and validUntil)
   * @param opts - Optional parameters (confidence, source, tags, metadata)
   * @returns The newly created TemporalAssertion
   */
  assert(
    claim: string,
    namespace: string,
    window: { validFrom: number; validUntil: number | null },
    opts: AssertOptions = {},
  ): TemporalAssertion {
    const now = Date.now();

    const assertion: TemporalAssertion = {
      id: opts.id ?? randomUUID(),
      claim,
      namespace,
      window: {
        validFrom: window.validFrom,
        validUntil: window.validUntil,
        assertedAt: now,
        retractedAt: null,
      },
      status: 'active', // placeholder; computed below
      supersededBy: null,
      supersedes: null,
      confidence: clamp(opts.confidence ?? 1.0, 0, 1),
      source: opts.source ?? 'system',
      tags: opts.tags ? [...opts.tags] : [],
      metadata: opts.metadata ? { ...opts.metadata } : {},
    };

    assertion.status = computeStatus(assertion, now);

    this.assertions.set(assertion.id, assertion);
    this.enforceCapacity();

    return assertion;
  }

  /**
   * Retrieve an assertion by ID.
   *
   * The returned assertion has its status recomputed against the current time.
   *
   * @param id - The assertion ID
   * @returns The assertion, or undefined if not found
   */
  get(id: string): TemporalAssertion | undefined {
    const assertion = this.assertions.get(id);
    if (!assertion) return undefined;

    assertion.status = computeStatus(assertion, Date.now());
    return assertion;
  }

  /**
   * Get all assertions that were active at a specific point in time.
   *
   * An assertion is considered "active at time T" if:
   * - Its validity window contains T (validFrom <= T and (validUntil is null or T < validUntil))
   * - It has not been retracted
   * - It has not been superseded
   *
   * @param pointInTime - The reference time (ms epoch)
   * @param namespace - Optional namespace filter
   * @returns Active assertions at the specified time
   */
  getActiveAt(pointInTime: number, namespace?: string): TemporalAssertion[] {
    const results: TemporalAssertion[] = [];

    for (const assertion of this.assertions.values()) {
      if (namespace !== undefined && assertion.namespace !== namespace) {
        continue;
      }

      const status = computeStatus(assertion, pointInTime);
      if (status === 'active') {
        // Update the stored status to reflect current time
        assertion.status = computeStatus(assertion, Date.now());
        results.push(assertion);
      }
    }

    return results.sort((a, b) => b.window.assertedAt - a.window.assertedAt);
  }

  /**
   * Get all assertions active right now.
   *
   * Convenience wrapper around `getActiveAt(Date.now())`.
   *
   * @param namespace - Optional namespace filter
   * @returns Currently active assertions
   */
  getCurrentTruth(namespace?: string): TemporalAssertion[] {
    return this.getActiveAt(Date.now(), namespace);
  }

  /**
   * Get the full history of a claim: all assertions (past and present) that
   * share the same claim text and namespace, regardless of status.
   *
   * Results are ordered by assertedAt ascending (oldest first), giving a
   * timeline of how the claim evolved.
   *
   * @param claim - The claim text to search for
   * @param namespace - The namespace to search in
   * @returns All matching assertions, oldest first
   */
  getHistory(claim: string, namespace: string): TemporalAssertion[] {
    const now = Date.now();
    const results: TemporalAssertion[] = [];

    for (const assertion of this.assertions.values()) {
      if (assertion.claim === claim && assertion.namespace === namespace) {
        assertion.status = computeStatus(assertion, now);
        results.push(assertion);
      }
    }

    return results.sort((a, b) => a.window.assertedAt - b.window.assertedAt);
  }

  /**
   * Query assertions with multiple optional filters.
   *
   * All specified filters are ANDed together. Results are ordered by
   * assertedAt descending (newest first).
   *
   * @param opts - Query filter options
   * @returns Matching assertions
   */
  query(opts: TemporalQuery = {}): TemporalAssertion[] {
    const now = Date.now();
    const results: TemporalAssertion[] = [];

    for (const assertion of this.assertions.values()) {
      assertion.status = computeStatus(assertion, now);

      if (opts.namespace !== undefined && assertion.namespace !== opts.namespace) {
        continue;
      }

      if (opts.pointInTime !== undefined) {
        const statusAtTime = computeStatus(assertion, opts.pointInTime);
        if (statusAtTime !== 'active') continue;
      }

      if (opts.status !== undefined && opts.status.length > 0) {
        if (!opts.status.includes(assertion.status)) continue;
      }

      if (opts.source !== undefined && assertion.source !== opts.source) {
        continue;
      }

      if (opts.tags !== undefined && opts.tags.length > 0) {
        const assertionTags = new Set(assertion.tags);
        if (!opts.tags.every(t => assertionTags.has(t))) continue;
      }

      results.push(assertion);
    }

    return results.sort((a, b) => b.window.assertedAt - a.window.assertedAt);
  }

  /**
   * Supersede an existing assertion with a new one.
   *
   * Marks the old assertion as superseded and creates a new assertion that
   * declares it replaces the old one. The supersession chain is bidirectional:
   * oldAssertion.supersededBy = newAssertion.id
   * newAssertion.supersedes = oldAssertion.id
   *
   * @param oldId - ID of the assertion to supersede
   * @param newClaim - The replacement claim text
   * @param newWindow - The validity window for the replacement
   * @param opts - Optional parameters for the new assertion
   * @returns The new assertion, or undefined if the old one was not found
   */
  supersede(
    oldId: string,
    newClaim: string,
    newWindow: { validFrom: number; validUntil: number | null },
    opts: AssertOptions = {},
  ): TemporalAssertion | undefined {
    const old = this.assertions.get(oldId);
    if (!old) return undefined;

    // Create the replacement assertion
    const replacement = this.assert(newClaim, old.namespace, newWindow, opts);

    // Link the chain
    replacement.supersedes = oldId;
    old.supersededBy = replacement.id;
    old.status = computeStatus(old, Date.now());

    return replacement;
  }

  /**
   * Retract an assertion (soft delete).
   *
   * The assertion is marked with a retractedAt timestamp and its status
   * becomes 'retracted'. The assertion remains in the store for historical
   * queries but is excluded from active truth queries.
   *
   * @param id - The assertion to retract
   * @param _reason - Optional reason for retraction (stored in metadata)
   * @returns The retracted assertion, or undefined if not found
   */
  retract(id: string, _reason?: string): TemporalAssertion | undefined {
    const assertion = this.assertions.get(id);
    if (!assertion) return undefined;

    assertion.window.retractedAt = Date.now();

    if (_reason !== undefined) {
      assertion.metadata.retractedReason = _reason;
    }

    assertion.status = computeStatus(assertion, Date.now());
    return assertion;
  }

  /**
   * Get the full supersession timeline for an assertion.
   *
   * Follows the supersedes/supersededBy chain in both directions to build
   * the complete lineage: all predecessors (oldest first) and all successors
   * (newest last). Handles cycles by tracking visited IDs.
   *
   * @param id - The assertion to build a timeline for
   * @returns The timeline, or undefined if not found
   */
  getTimeline(id: string): TemporalTimeline | undefined {
    const assertion = this.assertions.get(id);
    if (!assertion) return undefined;

    const now = Date.now();
    assertion.status = computeStatus(assertion, now);

    const visited = new Set<string>([id]);

    // Walk predecessors (what this assertion replaced)
    const predecessors: TemporalAssertion[] = [];
    let currentId = assertion.supersedes;
    while (currentId !== null) {
      if (visited.has(currentId)) break;
      visited.add(currentId);

      const pred = this.assertions.get(currentId);
      if (!pred) break;

      pred.status = computeStatus(pred, now);
      predecessors.unshift(pred); // oldest first
      currentId = pred.supersedes;
    }

    // Walk successors (what replaced this assertion)
    const successors: TemporalAssertion[] = [];
    currentId = assertion.supersededBy;
    while (currentId !== null) {
      if (visited.has(currentId)) break;
      visited.add(currentId);

      const succ = this.assertions.get(currentId);
      if (!succ) break;

      succ.status = computeStatus(succ, now);
      successors.push(succ); // newest last
      currentId = succ.supersededBy;
    }

    return { assertion, predecessors, successors };
  }

  /**
   * Detect conflicting assertions: multiple assertions active at the same
   * time in the same namespace.
   *
   * Returns groups of assertions that are simultaneously active, which may
   * indicate contradictions that need resolution.
   *
   * @param namespace - The namespace to check
   * @param pointInTime - The reference time (defaults to now)
   * @returns Array of assertions that are concurrently active (empty if no conflicts)
   */
  reconcile(namespace: string, pointInTime?: number): TemporalAssertion[] {
    const refTime = pointInTime ?? Date.now();
    const active = this.getActiveAt(refTime, namespace);

    // A single or zero active assertions means no conflict
    if (active.length <= 1) return [];

    return active;
  }

  /**
   * Export all assertions for persistence.
   *
   * @returns Serializable store representation
   */
  exportAssertions(): SerializedTemporalStore {
    const now = Date.now();
    const assertions: TemporalAssertion[] = [];

    for (const assertion of this.assertions.values()) {
      assertion.status = computeStatus(assertion, now);
      assertions.push({ ...assertion, metadata: { ...assertion.metadata } });
    }

    return {
      assertions,
      createdAt: new Date().toISOString(),
      version: SERIALIZATION_VERSION,
    };
  }

  /**
   * Import previously exported assertions, replacing all current contents.
   *
   * @param data - Serialized store data
   * @throws If the version is unsupported
   */
  importAssertions(data: SerializedTemporalStore): void {
    if (data.version !== SERIALIZATION_VERSION) {
      throw new Error(
        `Unsupported temporal store version: ${data.version} (expected ${SERIALIZATION_VERSION})`,
      );
    }

    this.assertions.clear();
    const now = Date.now();

    for (const assertion of data.assertions) {
      const imported: TemporalAssertion = {
        ...assertion,
        tags: [...assertion.tags],
        metadata: { ...assertion.metadata },
      };
      imported.status = computeStatus(imported, now);
      this.assertions.set(imported.id, imported);
    }
  }

  /**
   * Remove expired assertions whose validity ended before the given timestamp.
   *
   * Only assertions with status 'expired' and validUntil before the cutoff
   * are removed. Retracted and superseded assertions are preserved for
   * historical traceability.
   *
   * @param beforeTimestamp - Remove assertions that expired before this time
   * @returns Number of assertions pruned
   */
  pruneExpired(beforeTimestamp: number): number {
    let pruned = 0;
    const now = Date.now();

    for (const [id, assertion] of this.assertions) {
      assertion.status = computeStatus(assertion, now);

      if (
        assertion.status === 'expired' &&
        assertion.window.validUntil !== null &&
        assertion.window.validUntil < beforeTimestamp
      ) {
        this.assertions.delete(id);
        pruned++;
      }
    }

    return pruned;
  }

  /**
   * Get the number of stored assertions.
   */
  get size(): number {
    return this.assertions.size;
  }

  /**
   * Get the current configuration.
   */
  getConfig(): TemporalConfig {
    return { ...this.config };
  }

  /**
   * Remove all assertions from the store.
   */
  clear(): void {
    this.assertions.clear();
  }

  // ===== Private =====

  /**
   * Enforce the maximum assertion capacity by pruning the oldest expired
   * assertions first.
   */
  private enforceCapacity(): void {
    if (this.assertions.size <= this.config.maxAssertions) return;

    const now = Date.now();

    // Collect expired assertions sorted by validUntil ascending (oldest first)
    const expired: Array<{ id: string; validUntil: number }> = [];
    for (const [id, assertion] of this.assertions) {
      const status = computeStatus(assertion, now);
      if (status === 'expired' && assertion.window.validUntil !== null) {
        expired.push({ id, validUntil: assertion.window.validUntil });
      }
    }

    expired.sort((a, b) => a.validUntil - b.validUntil);

    // Remove oldest expired until under capacity
    let removed = 0;
    const excess = this.assertions.size - this.config.maxAssertions;

    for (const entry of expired) {
      if (removed >= excess) break;
      this.assertions.delete(entry.id);
      removed++;
    }

    // If still over capacity, remove oldest retracted
    if (this.assertions.size > this.config.maxAssertions) {
      const retracted: Array<{ id: string; retractedAt: number }> = [];
      for (const [id, assertion] of this.assertions) {
        if (assertion.window.retractedAt !== null) {
          retracted.push({ id, retractedAt: assertion.window.retractedAt });
        }
      }

      retracted.sort((a, b) => a.retractedAt - b.retractedAt);

      const stillExcess = this.assertions.size - this.config.maxAssertions;
      for (let i = 0; i < Math.min(stillExcess, retracted.length); i++) {
        this.assertions.delete(retracted[i].id);
      }
    }
  }
}

// ============================================================================
// TemporalReasoner
// ============================================================================

/**
 * High-level temporal reasoning over a TemporalStore.
 *
 * Provides semantic queries like "what was true at time T", "what will be
 * true at time T", change detection, conflict detection, and forward
 * projection of assertion validity.
 */
export class TemporalReasoner {
  private readonly store: TemporalStore;

  constructor(store: TemporalStore) {
    this.store = store;
  }

  /**
   * What was true at a past point in time?
   *
   * Returns all assertions that were active (valid, not retracted, not
   * superseded) at the specified historical moment.
   *
   * @param namespace - The namespace to query
   * @param pointInTime - The historical moment (ms epoch)
   * @returns Assertions that were active at that time
   */
  whatWasTrue(namespace: string, pointInTime: number): TemporalAssertion[] {
    return this.store.getActiveAt(pointInTime, namespace);
  }

  /**
   * What is true right now?
   *
   * Returns all currently active assertions in the given namespace.
   *
   * @param namespace - The namespace to query
   * @returns Currently active assertions
   */
  whatIsTrue(namespace: string): TemporalAssertion[] {
    return this.store.getCurrentTruth(namespace);
  }

  /**
   * What will be true at a future point in time?
   *
   * Returns assertions whose validity window includes the specified future
   * time and that have not been retracted or superseded.
   *
   * @param namespace - The namespace to query
   * @param futureTime - The future moment (ms epoch)
   * @returns Assertions that will be active at that time
   */
  whatWillBeTrue(namespace: string, futureTime: number): TemporalAssertion[] {
    return this.store.getActiveAt(futureTime, namespace);
  }

  /**
   * Detect changes in a namespace since a given timestamp.
   *
   * Returns a list of changes ordered by their change time, including:
   * - New assertions created after the timestamp
   * - Assertions superseded after the timestamp
   * - Assertions retracted after the timestamp
   * - Assertions that expired after the timestamp
   *
   * @param namespace - The namespace to check
   * @param sinceTimestamp - Only include changes after this time (ms epoch)
   * @returns List of detected changes
   */
  hasChanged(namespace: string, sinceTimestamp: number): TemporalChange[] {
    const changes: TemporalChange[] = [];
    const now = Date.now();
    const all = this.store.query({ namespace });

    for (const assertion of all) {
      // New assertion
      if (assertion.window.assertedAt > sinceTimestamp) {
        changes.push({
          assertion,
          changeType: 'asserted',
          changedAt: assertion.window.assertedAt,
        });
      }

      // Retracted
      if (
        assertion.window.retractedAt !== null &&
        assertion.window.retractedAt > sinceTimestamp
      ) {
        changes.push({
          assertion,
          changeType: 'retracted',
          changedAt: assertion.window.retractedAt,
        });
      }

      // Superseded: we infer the supersession time from the successor's
      // assertedAt, since the old assertion is marked superseded when the
      // new one is created.
      if (assertion.supersededBy !== null) {
        const successor = this.store.get(assertion.supersededBy);
        if (successor && successor.window.assertedAt > sinceTimestamp) {
          changes.push({
            assertion,
            changeType: 'superseded',
            changedAt: successor.window.assertedAt,
          });
        }
      }

      // Expired: the assertion expired between sinceTimestamp and now
      if (
        assertion.window.validUntil !== null &&
        assertion.window.validUntil > sinceTimestamp &&
        assertion.window.validUntil <= now &&
        assertion.window.retractedAt === null &&
        assertion.supersededBy === null
      ) {
        changes.push({
          assertion,
          changeType: 'expired',
          changedAt: assertion.window.validUntil,
        });
      }
    }

    return changes.sort((a, b) => a.changedAt - b.changedAt);
  }

  /**
   * Detect conflicting (contradictory) assertions active at the same time
   * in the same namespace.
   *
   * Returns all concurrently active assertions if there are two or more.
   * An empty array means no conflicts.
   *
   * @param namespace - The namespace to check
   * @param pointInTime - The reference time (defaults to now)
   * @returns Conflicting assertions, or empty if no conflicts
   */
  conflictsAt(namespace: string, pointInTime?: number): TemporalAssertion[] {
    return this.store.reconcile(namespace, pointInTime);
  }

  /**
   * Project an assertion forward: will it still be valid at a future time?
   *
   * Checks whether the assertion's validity window includes the future
   * timestamp and the assertion has not been retracted or superseded.
   *
   * @param assertionId - The assertion to project
   * @param futureTimestamp - The future time to check (ms epoch)
   * @returns true if the assertion will be active at the future time
   */
  projectForward(assertionId: string, futureTimestamp: number): boolean {
    const assertion = this.store.get(assertionId);
    if (!assertion) return false;

    const futureStatus = computeStatus(assertion, futureTimestamp);
    return futureStatus === 'active';
  }
}

// ============================================================================
// Factory Functions
// ============================================================================

/**
 * Create a TemporalStore with optional configuration.
 *
 * @param config - Partial configuration; unspecified values use defaults
 * @returns A fresh TemporalStore
 */
export function createTemporalStore(
  config?: Partial<TemporalConfig>,
): TemporalStore {
  return new TemporalStore(config);
}

/**
 * Create a TemporalReasoner backed by the given store.
 *
 * @param store - The TemporalStore to reason over
 * @returns A fresh TemporalReasoner
 */
export function createTemporalReasoner(
  store: TemporalStore,
): TemporalReasoner {
  return new TemporalReasoner(store);
}

// ============================================================================
// Helpers
// ============================================================================

/**
 * Compute the temporal status of an assertion at a given reference time.
 *
 * Priority order:
 * 1. retracted (retractedAt is set)
 * 2. superseded (supersededBy is set)
 * 3. expired (validUntil <= referenceTime)
 * 4. active (validFrom <= referenceTime and window is open)
 * 5. future (validFrom > referenceTime)
 *
 * @param assertion - The assertion to evaluate
 * @param referenceTime - The time to compute status against (ms epoch)
 * @returns The computed TemporalStatus
 */
function computeStatus(assertion: TemporalAssertion, referenceTime: number): TemporalStatus {
  // Retraction takes absolute priority
  if (assertion.window.retractedAt !== null) {
    return 'retracted';
  }

  // Supersession takes next priority
  if (assertion.supersededBy !== null) {
    return 'superseded';
  }

  // Check temporal position relative to validity window
  const { validFrom, validUntil } = assertion.window;

  if (validUntil !== null && referenceTime >= validUntil) {
    return 'expired';
  }

  if (referenceTime >= validFrom) {
    return 'active';
  }

  return 'future';
}

/**
 * Clamp a number to the range [min, max].
 */
function clamp(value: number, min: number, max: number): number {
  return Math.min(max, Math.max(min, value));
}

/**
 * Trust Score Accumulation System
 *
 * Builds trust gradients from gate outcomes over time. Sits alongside the
 * CoherenceScheduler (coherence.ts) but tracks a separate dimension:
 * accumulated trust from successful/failed gate evaluations.
 *
 * TrustAccumulator:
 * - Maintains a running trust score per agent (0.0 to 1.0)
 * - Accumulates trust from gate outcomes (allow, deny, warn)
 * - Applies exponential decay toward the initial value when idle
 * - Maps trust scores to privilege tiers (trusted, standard, probation, untrusted)
 *
 * TrustLedger:
 * - Records every trust score change with full context
 * - Supports export/import for persistence
 * - Querying by agent or threshold
 *
 * Trust-based rate limiting:
 * - Adjusts rate limits proportionally to accumulated trust
 *
 * @module @claude-flow/guidance/trust
 */

// ============================================================================
// Types
// ============================================================================

/**
 * Privilege tier derived from an agent's accumulated trust score.
 */
export type TrustTier = 'trusted' | 'standard' | 'probation' | 'untrusted';

/**
 * Gate decision outcomes that affect trust accumulation.
 */
export type GateOutcome = 'allow' | 'deny' | 'warn';

/**
 * Configuration for the TrustAccumulator.
 */
export interface TrustConfig {
  /** Starting trust score for new agents (0.0 - 1.0) */
  initialTrust: number;
  /** Trust increase on an 'allow' gate outcome */
  allowDelta: number;
  /** Trust decrease on a 'deny' gate outcome */
  denyDelta: number;
  /** Trust decrease on a 'warn' gate outcome */
  warnDelta: number;
  /** Exponential decay rate (0.0 - 1.0). Higher = faster decay toward initial */
  decayRate: number;
  /** Minimum elapsed time (ms) before decay is applied */
  decayIntervalMs: number;
}

/**
 * A single trust change record in the ledger.
 */
export interface TrustRecord {
  /** Agent whose trust changed */
  agentId: string;
  /** Trust score before the change */
  previousScore: number;
  /** Trust score after the change */
  newScore: number;
  /** The signed delta applied */
  delta: number;
  /** Human-readable reason for the change */
  reason: string;
  /** Unix timestamp (ms) of the change */
  timestamp: number;
  /** Gate decision that triggered this change, if any */
  gateDecision?: GateOutcome;
}

/**
 * Point-in-time snapshot of an agent's trust state.
 */
export interface TrustSnapshot {
  /** Agent identifier */
  agentId: string;
  /** Current trust score */
  score: number;
  /** Current privilege tier */
  tier: TrustTier;
  /** Total gate events processed for this agent */
  totalEvents: number;
  /** Timestamp of the most recent trust change */
  lastUpdated: number;
}

// ============================================================================
// Internal State
// ============================================================================

/**
 * Per-agent trust tracking state (internal).
 */
interface AgentTrustState {
  score: number;
  totalEvents: number;
  lastUpdated: number;
}

// ============================================================================
// Default Configuration
// ============================================================================

const DEFAULT_TRUST_CONFIG: TrustConfig = {
  initialTrust: 0.5,
  allowDelta: 0.01,
  denyDelta: -0.05,
  warnDelta: -0.02,
  decayRate: 0.01,
  decayIntervalMs: 60_000, // 1 minute
};

// ============================================================================
// Trust Tier Thresholds
// ============================================================================

const TIER_THRESHOLDS = {
  trusted: 0.8,
  standard: 0.5,
  probation: 0.3,
} as const;

// ============================================================================
// Rate Limit Multipliers
// ============================================================================

const RATE_LIMIT_MULTIPLIERS: Record<TrustTier, number> = {
  trusted: 2.0,
  standard: 1.0,
  probation: 0.5,
  untrusted: 0.1,
};

// ============================================================================
// Trust Accumulator
// ============================================================================

/**
 * Maintains running trust scores per agent, accumulates trust from gate
 * outcomes, applies time-based exponential decay, and maps scores to
 * privilege tiers.
 */
export class TrustAccumulator {
  private readonly config: TrustConfig;
  private readonly agents: Map<string, AgentTrustState> = new Map();

  constructor(config: Partial<TrustConfig> = {}) {
    this.config = { ...DEFAULT_TRUST_CONFIG, ...config };
  }

  /**
   * Record a gate outcome for an agent, adjusting their trust score.
   *
   * - 'allow' increases trust by `allowDelta`
   * - 'deny' decreases trust by `denyDelta` (negative value)
   * - 'warn' decreases trust by `warnDelta` (negative value)
   *
   * Before applying the delta, exponential decay is applied if enough
   * time has elapsed since the last update.
   *
   * Returns the trust record describing the change.
   */
  recordOutcome(
    agentId: string,
    outcome: GateOutcome,
    reason: string,
  ): TrustRecord {
    const state = this.getOrCreateState(agentId);
    const now = Date.now();

    // Apply decay before the outcome delta
    this.applyDecay(state, now);

    const previousScore = state.score;

    // Determine delta from outcome
    let delta: number;
    switch (outcome) {
      case 'allow':
        delta = this.config.allowDelta;
        break;
      case 'deny':
        delta = this.config.denyDelta;
        break;
      case 'warn':
        delta = this.config.warnDelta;
        break;
    }

    // Apply delta and clamp to [0, 1]
    state.score = clamp(state.score + delta, 0, 1);
    state.totalEvents++;
    state.lastUpdated = now;

    return {
      agentId,
      previousScore,
      newScore: state.score,
      delta,
      reason,
      timestamp: now,
      gateDecision: outcome,
    };
  }

  /**
   * Get the current trust score for an agent.
   * Returns the configured initial trust if the agent is unknown.
   */
  getScore(agentId: string): number {
    const state = this.agents.get(agentId);
    if (!state) return this.config.initialTrust;

    // Apply decay before reading (non-mutating copy for read)
    const now = Date.now();
    const elapsed = now - state.lastUpdated;
    if (elapsed >= this.config.decayIntervalMs) {
      this.applyDecay(state, now);
    }

    return state.score;
  }

  /**
   * Determine the privilege tier for an agent based on their trust score.
   *
   * - >= 0.8: 'trusted' (expanded privileges, higher rate limits)
   * - >= 0.5: 'standard' (normal operation)
   * - >= 0.3: 'probation' (restricted tools, lower rate limits)
   * - < 0.3: 'untrusted' (read-only, must earn trust back)
   */
  getTier(agentId: string): TrustTier {
    const score = this.getScore(agentId);
    return scoreToTier(score);
  }

  /**
   * Get a full snapshot of an agent's trust state.
   */
  getSnapshot(agentId: string): TrustSnapshot {
    const score = this.getScore(agentId);
    const state = this.agents.get(agentId);

    return {
      agentId,
      score,
      tier: scoreToTier(score),
      totalEvents: state?.totalEvents ?? 0,
      lastUpdated: state?.lastUpdated ?? 0,
    };
  }

  /**
   * Get snapshots for all tracked agents.
   */
  getAllSnapshots(): TrustSnapshot[] {
    const snapshots: TrustSnapshot[] = [];
    for (const agentId of this.agents.keys()) {
      snapshots.push(this.getSnapshot(agentId));
    }
    return snapshots;
  }

  /**
   * Get a trust-adjusted rate limit for an agent.
   *
   * Multipliers by tier:
   * - trusted: 2x base limit
   * - standard: 1x base limit
   * - probation: 0.5x base limit
   * - untrusted: 0.1x base limit
   */
  getTrustBasedRateLimit(agentId: string, baseLimit: number): number {
    const tier = this.getTier(agentId);
    return Math.floor(baseLimit * RATE_LIMIT_MULTIPLIERS[tier]);
  }

  /**
   * Manually set an agent's trust score (e.g., from persistence restore).
   * Clamps to [0, 1].
   */
  setScore(agentId: string, score: number): void {
    const state = this.getOrCreateState(agentId);
    state.score = clamp(score, 0, 1);
    state.lastUpdated = Date.now();
  }

  /**
   * Remove an agent from tracking entirely.
   */
  removeAgent(agentId: string): boolean {
    return this.agents.delete(agentId);
  }

  /**
   * Get the number of tracked agents.
   */
  get agentCount(): number {
    return this.agents.size;
  }

  /**
   * Get all tracked agent IDs.
   */
  getAgentIds(): string[] {
    return [...this.agents.keys()];
  }

  /**
   * Get the current configuration.
   */
  getConfig(): TrustConfig {
    return { ...this.config };
  }

  /**
   * Reset all tracked agents.
   */
  clear(): void {
    this.agents.clear();
  }

  // ===== Private =====

  private getOrCreateState(agentId: string): AgentTrustState {
    let state = this.agents.get(agentId);
    if (!state) {
      state = {
        score: this.config.initialTrust,
        totalEvents: 0,
        lastUpdated: Date.now(),
      };
      this.agents.set(agentId, state);
    }
    return state;
  }

  /**
   * Apply exponential decay toward the initial trust value.
   *
   * The decay formula moves the score toward `initialTrust` by a fraction
   * proportional to the number of decay intervals elapsed:
   *
   *   score = score + (initialTrust - score) * (1 - (1 - decayRate)^intervals)
   *
   * This ensures idle agents gradually return to the baseline.
   */
  private applyDecay(state: AgentTrustState, now: number): void {
    const elapsed = now - state.lastUpdated;
    if (elapsed < this.config.decayIntervalMs) return;

    const intervals = Math.floor(elapsed / this.config.decayIntervalMs);
    if (intervals <= 0) return;

    const retainFactor = Math.pow(1 - this.config.decayRate, intervals);
    const target = this.config.initialTrust;

    // Exponential interpolation toward target
    state.score = target + (state.score - target) * retainFactor;
    state.lastUpdated = now;
  }
}

// ============================================================================
// Trust Ledger
// ============================================================================

/**
 * Records all trust score changes with full context. Supports persistence
 * via export/import and querying by agent or threshold.
 */
export class TrustLedger {
  private records: TrustRecord[] = [];
  private static readonly MAX_RECORDS = 10_000;

  /**
   * Append a trust record to the ledger.
   */
  record(entry: TrustRecord): void {
    this.records.push(entry);

    // Evict oldest records when the ledger exceeds capacity
    if (this.records.length > TrustLedger.MAX_RECORDS) {
      this.records = this.records.slice(-TrustLedger.MAX_RECORDS);
    }
  }

  /**
   * Get the full trust history for a specific agent, ordered chronologically.
   */
  getHistoryForAgent(agentId: string): TrustRecord[] {
    return this.records.filter(r => r.agentId === agentId);
  }

  /**
   * Get all agents whose most recent score is below the given threshold.
   * Returns one record per agent (the most recent).
   */
  getAgentsBelowThreshold(threshold: number): TrustRecord[] {
    const latestByAgent = new Map<string, TrustRecord>();

    for (const record of this.records) {
      const existing = latestByAgent.get(record.agentId);
      if (!existing || record.timestamp > existing.timestamp) {
        latestByAgent.set(record.agentId, record);
      }
    }

    const result: TrustRecord[] = [];
    for (const record of latestByAgent.values()) {
      if (record.newScore < threshold) {
        result.push(record);
      }
    }

    return result;
  }

  /**
   * Get all agents whose most recent score is at or above the given threshold.
   * Returns one record per agent (the most recent).
   */
  getAgentsAboveThreshold(threshold: number): TrustRecord[] {
    const latestByAgent = new Map<string, TrustRecord>();

    for (const record of this.records) {
      const existing = latestByAgent.get(record.agentId);
      if (!existing || record.timestamp > existing.timestamp) {
        latestByAgent.set(record.agentId, record);
      }
    }

    const result: TrustRecord[] = [];
    for (const record of latestByAgent.values()) {
      if (record.newScore >= threshold) {
        result.push(record);
      }
    }

    return result;
  }

  /**
   * Get records within a time range.
   */
  getRecordsInRange(startMs: number, endMs: number): TrustRecord[] {
    return this.records.filter(
      r => r.timestamp >= startMs && r.timestamp <= endMs,
    );
  }

  /**
   * Get the most recent N records.
   */
  getRecentRecords(count: number): TrustRecord[] {
    return this.records.slice(-count);
  }

  /**
   * Get the total number of records.
   */
  get recordCount(): number {
    return this.records.length;
  }

  /**
   * Export all records for persistence.
   */
  exportRecords(): TrustRecord[] {
    return [...this.records];
  }

  /**
   * Import records from persistence. Appends to existing records.
   */
  importRecords(records: TrustRecord[]): void {
    this.records.push(...records);

    // Re-enforce capacity limit after import
    if (this.records.length > TrustLedger.MAX_RECORDS) {
      this.records = this.records.slice(-TrustLedger.MAX_RECORDS);
    }
  }

  /**
   * Clear all records.
   */
  clear(): void {
    this.records = [];
  }
}

// ============================================================================
// Integrated Trust System
// ============================================================================

/**
 * Combines TrustAccumulator and TrustLedger into a single coordinated
 * system. Gate outcomes are accumulated and automatically logged.
 */
export class TrustSystem {
  readonly accumulator: TrustAccumulator;
  readonly ledger: TrustLedger;

  constructor(config: Partial<TrustConfig> = {}) {
    this.accumulator = new TrustAccumulator(config);
    this.ledger = new TrustLedger();
  }

  /**
   * Record a gate outcome, update the accumulator, and log to the ledger.
   */
  recordOutcome(
    agentId: string,
    outcome: GateOutcome,
    reason: string,
  ): TrustRecord {
    const record = this.accumulator.recordOutcome(agentId, outcome, reason);
    this.ledger.record(record);
    return record;
  }

  /**
   * Get the current trust score for an agent.
   */
  getScore(agentId: string): number {
    return this.accumulator.getScore(agentId);
  }

  /**
   * Get the current privilege tier for an agent.
   */
  getTier(agentId: string): TrustTier {
    return this.accumulator.getTier(agentId);
  }

  /**
   * Get a trust-adjusted rate limit for an agent.
   */
  getTrustBasedRateLimit(agentId: string, baseLimit: number): number {
    return this.accumulator.getTrustBasedRateLimit(agentId, baseLimit);
  }

  /**
   * Get a full snapshot of an agent's trust state.
   */
  getSnapshot(agentId: string): TrustSnapshot {
    return this.accumulator.getSnapshot(agentId);
  }

  /**
   * Get snapshots for all tracked agents.
   */
  getAllSnapshots(): TrustSnapshot[] {
    return this.accumulator.getAllSnapshots();
  }
}

// ============================================================================
// Standalone Rate Limit Helper
// ============================================================================

/**
 * Compute a trust-adjusted rate limit from a score and base limit.
 *
 * This is a stateless utility for cases where you have a trust score
 * but no TrustAccumulator instance.
 *
 * Multipliers by tier:
 * - trusted (>= 0.8): 2x
 * - standard (>= 0.5): 1x
 * - probation (>= 0.3): 0.5x
 * - untrusted (< 0.3): 0.1x
 */
export function getTrustBasedRateLimit(score: number, baseLimit: number): number {
  const tier = scoreToTier(score);
  return Math.floor(baseLimit * RATE_LIMIT_MULTIPLIERS[tier]);
}

// ============================================================================
// Factory Functions
// ============================================================================

/**
 * Create a TrustAccumulator with optional configuration.
 */
export function createTrustAccumulator(
  config?: Partial<TrustConfig>,
): TrustAccumulator {
  return new TrustAccumulator(config);
}

/**
 * Create an empty TrustLedger.
 */
export function createTrustLedger(): TrustLedger {
  return new TrustLedger();
}

/**
 * Create a coordinated TrustSystem (accumulator + ledger).
 */
export function createTrustSystem(
  config?: Partial<TrustConfig>,
): TrustSystem {
  return new TrustSystem(config);
}

// ============================================================================
// Helpers
// ============================================================================

/**
 * Map a trust score to a privilege tier.
 */
function scoreToTier(score: number): TrustTier {
  if (score >= TIER_THRESHOLDS.trusted) return 'trusted';
  if (score >= TIER_THRESHOLDS.standard) return 'standard';
  if (score >= TIER_THRESHOLDS.probation) return 'probation';
  return 'untrusted';
}

/**
 * Clamp a number to the range [min, max].
 */
function clamp(value: number, min: number, max: number): number {
  return Math.min(max, Math.max(min, value));
}

/**
 * Truth Anchor System
 *
 * Immutable, externally-signed facts that anchor the system to reality
 * beyond tool outputs and internal memory.
 *
 * A Truth Anchor is a fact that:
 * - Is immutable once recorded (cannot be overwritten or decayed)
 * - Is externally signed (by a human, hardware sensor, or external authority)
 * - Supersedes any internal belief that contradicts it
 * - Can be referenced but never mutated
 * - Has a verifiable signature chain
 *
 * TruthAnchorStore:
 * - Creates and signs new truth anchors with HMAC-SHA256
 * - Append-only storage (anchors are never mutated after creation)
 * - Retrieval by ID, time range, kind, attester, or tags
 * - Signature verification for individual anchors or the full store
 * - Supersession chain: new anchors can declare they supersede old ones
 * - Export/import for persistence and transfer
 * - Max 50,000 anchors with LRU eviction of expired ones only
 *
 * TruthResolver:
 * - Resolves conflicts between internal beliefs and truth anchors
 * - Memory conflict resolution (truth anchor always wins)
 * - Decision conflict resolution (constrains proposed actions)
 * - Topic-based ground truth retrieval with fuzzy tag matching
 *
 * @module @claude-flow/guidance/truth-anchors
 */

import { createHmac, randomUUID } from 'node:crypto';

// ============================================================================
// Types
// ============================================================================

/**
 * The kind of external source that attested to a truth anchor.
 */
export type TruthSourceKind =
  | 'human-attestation'
  | 'hardware-signal'
  | 'regulatory-input'
  | 'external-observation'
  | 'signed-document'
  | 'consensus-result';

/**
 * An immutable, externally-signed fact anchored to the system.
 *
 * Once created, a TruthAnchor is never mutated. It can only be
 * superseded by a new anchor that references the old one.
 */
export interface TruthAnchor {
  /** Unique identifier (UUID v4) */
  id: string;
  /** The kind of external source that attested to this fact */
  kind: TruthSourceKind;
  /** The fact being asserted, in natural language */
  claim: string;
  /** Supporting data or evidence for the claim */
  evidence: string;
  /** Who or what signed this anchor (human ID, sensor ID, authority ID) */
  attesterId: string;
  /** HMAC-SHA256 signature over the canonical anchor content */
  signature: string;
  /** Unix timestamp (ms) when the anchor was created */
  timestamp: number;
  /** Unix timestamp (ms) when the fact became true */
  validFrom: number;
  /** Unix timestamp (ms) when the fact expires, or null for indefinite */
  validUntil: number | null;
  /** IDs of anchors that this anchor supersedes */
  supersedes: string[];
  /** Searchable tags for topic-based retrieval */
  tags: string[];
  /** Arbitrary metadata attached to the anchor */
  metadata: Record<string, unknown>;
}

/**
 * Configuration for the TruthAnchorStore.
 */
export interface TruthAnchorConfig {
  /** HMAC-SHA256 signing key */
  signingKey: string;
  /** Maximum number of anchors to retain (default 50,000) */
  maxAnchors: number;
}

/**
 * Parameters for creating a new truth anchor.
 */
export interface AnchorParams {
  kind: TruthSourceKind;
  claim: string;
  evidence: string;
  attesterId: string;
  validFrom?: number;
  validUntil?: number | null;
  supersedes?: string[];
  tags?: string[];
  metadata?: Record<string, unknown>;
}

/**
 * Query options for filtering truth anchors.
 */
export interface TruthAnchorQuery {
  /** Filter by source kind */
  kind?: TruthSourceKind;
  /** Filter by attester ID */
  attesterId?: string;
  /** Filter by tags (anchor must have at least one matching tag) */
  tags?: string[];
  /** Only return anchors valid at this timestamp */
  validAt?: number;
}

/**
 * Result of verifying all anchors in the store.
 */
export interface VerifyAllResult {
  /** Number of anchors with valid signatures */
  valid: number;
  /** IDs of anchors with invalid signatures */
  invalid: string[];
}

/**
 * Result of resolving a conflict between an internal belief and truth anchors.
 */
export interface ConflictResolution {
  /** Whether a truth anchor overrides the internal belief */
  truthWins: boolean;
  /** The truth anchor that overrides, if any */
  anchor?: TruthAnchor;
  /** Human-readable explanation of the resolution */
  reason: string;
}

// ============================================================================
// Default Configuration
// ============================================================================

const DEFAULT_CONFIG: TruthAnchorConfig = {
  signingKey: '',
  maxAnchors: 50_000,
};

// ============================================================================
// Signing Helpers
// ============================================================================

/**
 * Compute the canonical string representation of an anchor for signing.
 *
 * Deterministic ordering ensures the same anchor always produces
 * the same signature regardless of property insertion order.
 */
function canonicalize(anchor: Omit<TruthAnchor, 'signature'>): string {
  return [
    anchor.id,
    anchor.kind,
    anchor.claim,
    anchor.evidence,
    anchor.attesterId,
    String(anchor.timestamp),
    String(anchor.validFrom),
    String(anchor.validUntil ?? 'null'),
    anchor.supersedes.join(','),
    anchor.tags.join(','),
    JSON.stringify(anchor.metadata),
  ].join('|');
}

/**
 * Produce an HMAC-SHA256 signature for the given data using the provided key.
 */
function sign(data: string, key: string): string {
  return createHmac('sha256', key).update(data).digest('hex');
}

// ============================================================================
// Truth Anchor Store
// ============================================================================

/**
 * Append-only store for truth anchors.
 *
 * Anchors are immutable once created. The store provides signing,
 * verification, querying, supersession, and capacity management
 * with LRU eviction of expired anchors only.
 */
export class TruthAnchorStore {
  private readonly config: TruthAnchorConfig;
  private readonly anchors: TruthAnchor[] = [];
  private readonly indexById: Map<string, number> = new Map();

  constructor(config: Partial<TruthAnchorConfig> = {}) {
    this.config = { ...DEFAULT_CONFIG, ...config };

    if (!this.config.signingKey) {
      throw new Error(
        'TruthAnchorStore requires a signingKey in config. ' +
        'Anchors cannot be created without a signing key.',
      );
    }
  }

  /**
   * Create and sign a new truth anchor.
   *
   * The anchor is appended to the store and can never be mutated.
   * If the store exceeds capacity, expired anchors are evicted
   * starting from the oldest.
   */
  anchor(params: AnchorParams): TruthAnchor {
    const now = Date.now();

    const partial: Omit<TruthAnchor, 'signature'> = {
      id: randomUUID(),
      kind: params.kind,
      claim: params.claim,
      evidence: params.evidence,
      attesterId: params.attesterId,
      timestamp: now,
      validFrom: params.validFrom ?? now,
      validUntil: params.validUntil ?? null,
      supersedes: params.supersedes ?? [],
      tags: params.tags ?? [],
      metadata: params.metadata ?? {},
    };

    const signature = sign(canonicalize(partial), this.config.signingKey);

    const truthAnchor: TruthAnchor = {
      ...partial,
      signature,
    };

    // Append (never mutate existing entries)
    this.anchors.push(truthAnchor);
    this.indexById.set(truthAnchor.id, this.anchors.length - 1);

    // Enforce capacity by evicting expired anchors
    this.enforceCapacity(now);

    return truthAnchor;
  }

  /**
   * Retrieve a truth anchor by its ID.
   *
   * Returns undefined if the anchor does not exist.
   */
  get(id: string): TruthAnchor | undefined {
    const index = this.indexById.get(id);
    if (index === undefined) return undefined;
    return this.anchors[index];
  }

  /**
   * Get all anchors that are valid at the given timestamp.
   *
   * An anchor is active when:
   * - `validFrom <= timestamp`
   * - `validUntil` is null (indefinite) or `validUntil > timestamp`
   *
   * Defaults to the current time if no timestamp is provided.
   */
  getActive(timestamp?: number): TruthAnchor[] {
    const ts = timestamp ?? Date.now();
    return this.anchors.filter(a => isActive(a, ts));
  }

  /**
   * Query anchors with optional filters.
   *
   * All provided filters are ANDed together. An anchor must match
   * every specified filter to be included in the result.
   */
  query(opts: TruthAnchorQuery): TruthAnchor[] {
    return this.anchors.filter(a => {
      if (opts.kind !== undefined && a.kind !== opts.kind) return false;
      if (opts.attesterId !== undefined && a.attesterId !== opts.attesterId) return false;
      if (opts.tags !== undefined && opts.tags.length > 0) {
        const hasMatch = opts.tags.some(tag => a.tags.includes(tag));
        if (!hasMatch) return false;
      }
      if (opts.validAt !== undefined && !isActive(a, opts.validAt)) return false;
      return true;
    });
  }

  /**
   * Verify the HMAC-SHA256 signature of a single anchor.
   *
   * Recomputes the signature from the anchor's content and compares
   * it to the stored signature. Returns true if they match.
   */
  verify(id: string): boolean {
    const anchor = this.get(id);
    if (!anchor) return false;

    const { signature, ...rest } = anchor;
    const expected = sign(canonicalize(rest), this.config.signingKey);
    return timingSafeEqual(signature, expected);
  }

  /**
   * Verify all anchors in the store.
   *
   * Returns a summary with the count of valid anchors and the
   * IDs of any anchors whose signatures do not match.
   */
  verifyAll(): VerifyAllResult {
    let valid = 0;
    const invalid: string[] = [];

    for (const anchor of this.anchors) {
      const { signature, ...rest } = anchor;
      const expected = sign(canonicalize(rest), this.config.signingKey);

      if (timingSafeEqual(signature, expected)) {
        valid++;
      } else {
        invalid.push(anchor.id);
      }
    }

    return { valid, invalid };
  }

  /**
   * Create a new anchor that supersedes an existing one.
   *
   * The old anchor remains in the store (immutable) but the new
   * anchor's `supersedes` array includes the old anchor's ID.
   * This creates a verifiable supersession chain.
   *
   * Throws if the old anchor ID does not exist.
   */
  supersede(oldId: string, params: AnchorParams): TruthAnchor {
    const old = this.get(oldId);
    if (!old) {
      throw new Error(`Cannot supersede: anchor "${oldId}" not found`);
    }

    const supersedes = [...(params.supersedes ?? [])];
    if (!supersedes.includes(oldId)) {
      supersedes.push(oldId);
    }

    return this.anchor({
      ...params,
      supersedes,
    });
  }

  /**
   * Resolve a claim against an internal belief.
   *
   * Searches for active truth anchors whose claim matches the
   * provided claim text. If a matching truth anchor exists and
   * is currently valid, it wins over the internal belief.
   *
   * Returns the truth anchor if it exists, otherwise returns
   * undefined (meaning the internal belief stands).
   */
  resolve(
    claim: string,
    _internalBelief: string,
  ): TruthAnchor | undefined {
    const now = Date.now();
    const normalizedClaim = claim.toLowerCase().trim();

    // Find active anchors whose claim matches
    for (const anchor of this.anchors) {
      if (!isActive(anchor, now)) continue;
      if (anchor.claim.toLowerCase().trim() === normalizedClaim) {
        return anchor;
      }
    }

    return undefined;
  }

  /**
   * Export all anchors for persistence or transfer.
   *
   * Returns a shallow copy of the anchor array. The individual
   * anchor objects are returned as-is since they are immutable.
   */
  exportAnchors(): TruthAnchor[] {
    return [...this.anchors];
  }

  /**
   * Import anchors from an external source.
   *
   * Imported anchors are appended to the store. Duplicate IDs
   * (anchors already in the store) are silently skipped.
   * Capacity enforcement runs after import.
   */
  importAnchors(anchors: TruthAnchor[]): void {
    const now = Date.now();

    for (const anchor of anchors) {
      // Skip duplicates
      if (this.indexById.has(anchor.id)) continue;

      this.anchors.push(anchor);
      this.indexById.set(anchor.id, this.anchors.length - 1);
    }

    this.enforceCapacity(now);
  }

  /**
   * Get the total number of anchors in the store.
   */
  get size(): number {
    return this.anchors.length;
  }

  // ===== Private =====

  /**
   * Enforce the maximum anchor capacity.
   *
   * Only expired anchors are evicted, starting from the oldest.
   * If no expired anchors can be evicted and the store is still
   * over capacity, the oldest expired anchors are removed first.
   * Active (non-expired) anchors are never evicted.
   */
  private enforceCapacity(now: number): void {
    if (this.anchors.length <= this.config.maxAnchors) return;

    // Collect indices of expired anchors (oldest first, array is append-only)
    const expiredIndices: number[] = [];
    for (let i = 0; i < this.anchors.length; i++) {
      const a = this.anchors[i];
      if (a.validUntil !== null && a.validUntil <= now) {
        expiredIndices.push(i);
      }
    }

    // Determine how many we need to evict
    const excess = this.anchors.length - this.config.maxAnchors;
    const toEvict = Math.min(excess, expiredIndices.length);

    if (toEvict <= 0) return;

    // Build a set of indices to remove (oldest expired first)
    const removeSet = new Set(expiredIndices.slice(0, toEvict));

    // Rebuild the array and index, preserving order
    const surviving: TruthAnchor[] = [];
    this.indexById.clear();

    for (let i = 0; i < this.anchors.length; i++) {
      if (removeSet.has(i)) continue;
      this.indexById.set(this.anchors[i].id, surviving.length);
      surviving.push(this.anchors[i]);
    }

    // Replace contents (splice to preserve the same array reference)
    this.anchors.length = 0;
    for (const a of surviving) {
      this.anchors.push(a);
    }
  }
}

// ============================================================================
// Truth Resolver
// ============================================================================

/**
 * Resolves conflicts between internal system beliefs and externally
 * anchored truth.
 *
 * The fundamental principle: truth anchors always win. If a valid,
 * active truth anchor contradicts an internal belief, the anchor
 * takes precedence.
 */
export class TruthResolver {
  private readonly store: TruthAnchorStore;

  constructor(store: TruthAnchorStore) {
    this.store = store;
  }

  /**
   * Check if any active truth anchor contradicts a memory value.
   *
   * Searches by namespace and key as tags, and by the memory value
   * as a claim. If a truth anchor exists that covers the same topic,
   * it wins over the internal memory.
   */
  resolveMemoryConflict(
    memoryKey: string,
    memoryValue: string,
    namespace: string,
  ): ConflictResolution {
    const now = Date.now();
    const active = this.store.getActive(now);

    // Search for anchors tagged with the namespace or memory key
    const normalizedKey = memoryKey.toLowerCase().trim();
    const normalizedNs = namespace.toLowerCase().trim();
    const normalizedValue = memoryValue.toLowerCase().trim();

    for (const anchor of active) {
      const lowerTags = anchor.tags.map(t => t.toLowerCase());

      // Check if the anchor is relevant to this memory entry
      const tagMatch =
        lowerTags.includes(normalizedKey) ||
        lowerTags.includes(normalizedNs) ||
        lowerTags.includes(`${normalizedNs}:${normalizedKey}`);

      if (!tagMatch) continue;

      // Check if the anchor's claim contradicts the memory value
      const anchorClaim = anchor.claim.toLowerCase().trim();
      if (anchorClaim !== normalizedValue) {
        return {
          truthWins: true,
          anchor,
          reason:
            `Truth anchor "${anchor.id}" (${anchor.kind}) contradicts memory ` +
            `"${namespace}:${memoryKey}". Anchor claim: "${anchor.claim}" ` +
            `supersedes internal value: "${memoryValue}".`,
        };
      }
    }

    return {
      truthWins: false,
      reason:
        `No active truth anchor contradicts memory "${namespace}:${memoryKey}". ` +
        `Internal belief stands.`,
    };
  }

  /**
   * Check if any active truth anchor constrains a proposed action.
   *
   * Searches for anchors whose claims or tags relate to the proposed
   * action and its context. Returns a conflict resolution indicating
   * whether the action is constrained.
   */
  resolveDecisionConflict(
    proposedAction: string,
    context: Record<string, unknown>,
  ): ConflictResolution {
    const now = Date.now();
    const active = this.store.getActive(now);

    const normalizedAction = proposedAction.toLowerCase().trim();
    const contextKeys = Object.keys(context).map(k => k.toLowerCase());

    for (const anchor of active) {
      const lowerTags = anchor.tags.map(t => t.toLowerCase());
      const lowerClaim = anchor.claim.toLowerCase();

      // Check if the anchor is relevant: tags intersect with context keys
      // or the action text appears in the claim
      const tagOverlap = lowerTags.some(
        t => contextKeys.includes(t) || normalizedAction.includes(t),
      );
      const claimRelevance =
        lowerClaim.includes(normalizedAction) ||
        normalizedAction.includes(lowerClaim);

      if (!tagOverlap && !claimRelevance) continue;

      // The anchor is relevant -- it constrains this action
      return {
        truthWins: true,
        anchor,
        reason:
          `Truth anchor "${anchor.id}" (${anchor.kind}) constrains the ` +
          `proposed action "${proposedAction}". Anchor claim: "${anchor.claim}". ` +
          `Attested by: "${anchor.attesterId}".`,
      };
    }

    return {
      truthWins: false,
      reason:
        `No active truth anchor constrains the proposed action ` +
        `"${proposedAction}". Action may proceed.`,
    };
  }

  /**
   * Get all active truth anchors relevant to a topic.
   *
   * Uses fuzzy tag matching: a tag matches the topic if either
   * the tag contains the topic or the topic contains the tag
   * (case-insensitive). Also matches against the claim text.
   */
  getGroundTruth(topic: string): TruthAnchor[] {
    const now = Date.now();
    const active = this.store.getActive(now);
    const normalizedTopic = topic.toLowerCase().trim();

    return active.filter(anchor => {
      // Fuzzy tag match
      const tagMatch = anchor.tags.some(tag => {
        const lowerTag = tag.toLowerCase();
        return lowerTag.includes(normalizedTopic) || normalizedTopic.includes(lowerTag);
      });

      // Claim text match
      const claimMatch = anchor.claim.toLowerCase().includes(normalizedTopic);

      return tagMatch || claimMatch;
    });
  }
}

// ============================================================================
// Helpers
// ============================================================================

/**
 * Check whether a truth anchor is active at a given timestamp.
 */
function isActive(anchor: TruthAnchor, timestamp: number): boolean {
  if (anchor.validFrom > timestamp) return false;
  if (anchor.validUntil !== null && anchor.validUntil <= timestamp) return false;
  return true;
}

/**
 * Constant-time string comparison to prevent timing attacks on signatures.
 *
 * Compares two hex strings character by character, accumulating
 * differences without short-circuiting.
 */
function timingSafeEqual(a: string, b: string): boolean {
  if (a.length !== b.length) return false;

  let mismatch = 0;
  for (let i = 0; i < a.length; i++) {
    mismatch |= a.charCodeAt(i) ^ b.charCodeAt(i);
  }

  return mismatch === 0;
}

// ============================================================================
// Factory Functions
// ============================================================================

/**
 * Create a TruthAnchorStore with the given configuration.
 *
 * @param config - Must include `signingKey`. `maxAnchors` defaults to 50,000.
 */
export function createTruthAnchorStore(
  config?: Partial<TruthAnchorConfig>,
): TruthAnchorStore {
  return new TruthAnchorStore(config);
}

/**
 * Create a TruthResolver backed by the given store.
 */
export function createTruthResolver(store: TruthAnchorStore): TruthResolver {
  return new TruthResolver(store);
}

