describe('EconomicGovernor', () => {
  let governor: EconomicGovernor;

  beforeEach(() => {
    governor = new EconomicGovernor({
      tokenLimit: 10_000,
      toolCallLimit: 100,
      storageLimit: 1_000_000,
      timeLimit: 60_000, // 1 minute
      costPerToken: 0.00001,
      costPerToolCall: 0.001,
      costLimit: 1.0,
    });
  });

  describe('recordTokenUsage', () => {
    it('should accumulate token usage', () => {
      governor.recordTokenUsage(500);
      governor.recordTokenUsage(300);

      const usage = governor.getUsageSummary();
      expect(usage.tokens.used).toBe(800);
      expect(usage.tokens.limit).toBe(10_000);
      expect(usage.tokens.percentage).toBeCloseTo(8.0, 1);
    });
  });

  describe('recordToolCall', () => {
    it('should track tool calls', () => {
      governor.recordToolCall('Edit', 150);
      governor.recordToolCall('Read', 50);
      governor.recordToolCall('Bash', 1200);

      const usage = governor.getUsageSummary();
      expect(usage.toolCalls.used).toBe(3);
      expect(usage.toolCalls.limit).toBe(100);
      expect(usage.toolCalls.percentage).toBeCloseTo(3.0, 1);
    });
  });

  describe('recordStorageUsage', () => {
    it('should accumulate storage bytes', () => {
      governor.recordStorageUsage(50_000);
      governor.recordStorageUsage(25_000);

      const usage = governor.getUsageSummary();
      expect(usage.storage.usedBytes).toBe(75_000);
      expect(usage.storage.limitBytes).toBe(1_000_000);
      expect(usage.storage.percentage).toBeCloseTo(7.5, 1);
    });
  });

  describe('checkBudget', () => {
    it('should report within budget when usage is low', () => {
      governor.recordTokenUsage(100);
      governor.recordToolCall('Edit', 50);

      const result = governor.checkBudget();
      expect(result.withinBudget).toBe(true);
      expect(result.alerts).toHaveLength(0);
    });

    it('should emit NOTICE alert at 75% usage', () => {
      governor.recordTokenUsage(7_500); // 75% of 10,000

      const result = governor.checkBudget();
      expect(result.withinBudget).toBe(true);
      expect(result.alerts.some(a => a.includes('NOTICE') && a.includes('tokens'))).toBe(true);
    });

    it('should emit WARNING alert at 90% usage', () => {
      governor.recordTokenUsage(9_000); // 90%

      const result = governor.checkBudget();
      expect(result.withinBudget).toBe(true);
      expect(result.alerts.some(a => a.includes('WARNING') && a.includes('tokens'))).toBe(true);
    });

    it('should emit CRITICAL alert at 95% usage', () => {
      governor.recordTokenUsage(9_500); // 95%

      const result = governor.checkBudget();
      expect(result.withinBudget).toBe(true);
      expect(result.alerts.some(a => a.includes('CRITICAL') && a.includes('tokens'))).toBe(true);
    });

    it('should report budget exceeded at 100%', () => {
      governor.recordTokenUsage(10_001); // Over limit

      const result = governor.checkBudget();
      expect(result.withinBudget).toBe(false);
      expect(result.alerts.some(a => a.includes('BUDGET EXCEEDED') && a.includes('tokens'))).toBe(true);
    });

    it('should generate alerts for multiple dimensions simultaneously', () => {
      governor.recordTokenUsage(9_000); // 90% tokens
      for (let i = 0; i < 95; i++) {
        governor.recordToolCall('Edit', 10); // 95% tool calls
      }

      const result = governor.checkBudget();
      expect(result.alerts.length).toBeGreaterThanOrEqual(2);
    });
  });

  describe('budget alerts', () => {
    it('should include cost alerts when cost exceeds thresholds', () => {
      // costPerToken = 0.00001, costLimit = 1.0
      // Need 75,000 tokens for 75% cost threshold ($0.75)
      governor.recordTokenUsage(75_000);

      const result = governor.checkBudget();
      expect(result.alerts.some(a => a.includes('cost'))).toBe(true);
    });
  });

  describe('getCostEstimate', () => {
    it('should compute cost from token usage', () => {
      governor.recordTokenUsage(1_000); // 1000 * 0.00001 = $0.01

      const estimate = governor.getCostEstimate();
      expect(estimate.totalCost).toBeCloseTo(0.01, 5);
      expect(estimate.breakdown.tokens).toBeCloseTo(0.01, 5);
    });

    it('should compute cost from tool call usage', () => {
      governor.recordToolCall('Edit', 100); // 1 * 0.001 = $0.001

      const estimate = governor.getCostEstimate();
      expect(estimate.breakdown.toolCalls).toBeCloseTo(0.001, 5);
    });

    it('should sum token and tool call costs', () => {
      governor.recordTokenUsage(1_000); // $0.01
      governor.recordToolCall('Edit', 100); // $0.001

      const estimate = governor.getCostEstimate();
      expect(estimate.totalCost).toBeCloseTo(0.011, 5);
    });

    it('should report zero cost with no usage', () => {
      const estimate = governor.getCostEstimate();
      expect(estimate.totalCost).toBe(0);
      expect(estimate.breakdown.tokens).toBe(0);
      expect(estimate.breakdown.toolCalls).toBe(0);
    });
  });

  describe('estimateRemainingCapacity', () => {
    it('should show full capacity at start', () => {
      const remaining = governor.estimateRemainingCapacity();
      expect(remaining.tokensRemaining).toBe(10_000);
      expect(remaining.callsRemaining).toBe(100);
      expect(remaining.timeRemainingMs).toBeLessThanOrEqual(60_000);
      expect(remaining.timeRemainingMs).toBeGreaterThan(59_000);
    });

    it('should decrease remaining tokens after usage', () => {
      governor.recordTokenUsage(4_000);

      const remaining = governor.estimateRemainingCapacity();
      expect(remaining.tokensRemaining).toBe(6_000);
    });

    it('should decrease remaining calls after usage', () => {
      for (let i = 0; i < 30; i++) {
        governor.recordToolCall('Edit', 10);
      }

      const remaining = governor.estimateRemainingCapacity();
      expect(remaining.callsRemaining).toBe(70);
    });

    it('should not go below zero', () => {
      governor.recordTokenUsage(20_000); // way over limit

      const remaining = governor.estimateRemainingCapacity();
      expect(remaining.tokensRemaining).toBe(0);
    });
  });

  describe('resetPeriod', () => {
    it('should reset all counters', () => {
      governor.recordTokenUsage(5_000);
      governor.recordToolCall('Edit', 100);
      governor.recordStorageUsage(500_000);

      governor.resetPeriod();

      const usage = governor.getUsageSummary();
      expect(usage.tokens.used).toBe(0);
      expect(usage.toolCalls.used).toBe(0);
      expect(usage.storage.usedBytes).toBe(0);
    });

    it('should reset cost estimate to zero', () => {
      governor.recordTokenUsage(5_000);
      governor.recordToolCall('Edit', 100);

      governor.resetPeriod();

      const estimate = governor.getCostEstimate();
      expect(estimate.totalCost).toBe(0);
    });

    it('should reset time tracking', () => {
      governor.resetPeriod();

      const usage = governor.getUsageSummary();
      // Time should be near zero since we just reset
      expect(usage.time.usedMs).toBeLessThan(100);
    });

    it('should allow budget to pass again after reset', () => {
      governor.recordTokenUsage(10_001); // Over limit
      expect(governor.checkBudget().withinBudget).toBe(false);

      governor.resetPeriod();
      expect(governor.checkBudget().withinBudget).toBe(true);
    });
  });

  describe('factory function', () => {
    it('should create a governor via createEconomicGovernor', () => {
      const g = createEconomicGovernor({ tokenLimit: 50_000 });
      expect(g).toBeInstanceOf(EconomicGovernor);
    });

    it('should create a governor with defaults', () => {
      const g = createEconomicGovernor();
      expect(g).toBeInstanceOf(EconomicGovernor);

      // Default token limit is 1,000,000
      const usage = g.getUsageSummary();
      expect(usage.tokens.limit).toBe(1_000_000);
    });
  });

  describe('getUsageSummary', () => {
    it('should return complete usage breakdown', () => {
      governor.recordTokenUsage(2_000);
      governor.recordToolCall('Edit', 50);
      governor.recordStorageUsage(100_000);

      const usage = governor.getUsageSummary();

      expect(usage.tokens.used).toBe(2_000);
      expect(usage.tokens.limit).toBe(10_000);
      expect(usage.tokens.percentage).toBeCloseTo(20.0, 1);

      expect(usage.toolCalls.used).toBe(1);
      expect(usage.toolCalls.limit).toBe(100);
      expect(usage.toolCalls.percentage).toBeCloseTo(1.0, 1);

      expect(usage.storage.usedBytes).toBe(100_000);
      expect(usage.storage.limitBytes).toBe(1_000_000);
      expect(usage.storage.percentage).toBeCloseTo(10.0, 1);

      expect(usage.time.limitMs).toBe(60_000);
      expect(usage.time.usedMs).toBeGreaterThanOrEqual(0);

      expect(usage.cost.totalUsd).toBeGreaterThan(0);
      expect(usage.cost.limitUsd).toBe(1.0);
    });
  });
});

/**
 * Tests for the Guidance Compiler
 */
import { describe, it, expect, beforeEach } from 'vitest';
import { GuidanceCompiler } from '../src/compiler.js';

describe('GuidanceCompiler', () => {
  let compiler: GuidanceCompiler;

  beforeEach(() => {
    compiler = new GuidanceCompiler();
  });

  describe('compile', () => {
    it('should compile a basic guidance file into a policy bundle', () => {
      const content = `
# Safety Invariants

- [R001] Never commit hardcoded secrets (critical) @security verify:secrets-scan
- [R002] Always validate inputs at system boundaries @security
- [R003] Never force push to main or master (critical) @security [bash]

# Architecture

- [R010] Keep files under 500 lines @architecture
- [R011] Use typed interfaces for all public APIs @architecture

# Testing

- [R020] Write tests before implementation (TDD) @testing #testing
- [R021] Mock external dependencies in tests @testing
`;

      const bundle = compiler.compile(content);

      expect(bundle.constitution).toBeDefined();
      expect(bundle.shards).toBeDefined();
      expect(bundle.manifest).toBeDefined();

      // Constitution should have the safety rules
      expect(bundle.constitution.rules.length).toBeGreaterThan(0);

      // Manifest should list all rules
      expect(bundle.manifest.totalRules).toBeGreaterThan(0);
      expect(bundle.manifest.compiledAt).toBeGreaterThan(0);
    });

    it('should parse explicit rule IDs', () => {
      const content = `
# Rules
- [R001] Never expose API keys in code (critical) @security
- [R002] Always use parameterized queries @security
`;

      const bundle = compiler.compile(content);
      const ruleIds = bundle.manifest.rules.map(r => r.id);

      expect(ruleIds).toContain('R001');
      expect(ruleIds).toContain('R002');
    });

    it('should extract risk classes', () => {
      const content = `
# Rules
- [R001] Critical security rule (critical) @security
- [R002] High importance rule (high) @security
- [R003] Normal rule @general
`;

      const bundle = compiler.compile(content);
      const rules = bundle.manifest.rules;

      const r001 = rules.find(r => r.id === 'R001');
      expect(r001?.riskClass).toBe('critical');

      const r002 = rules.find(r => r.id === 'R002');
      expect(r002?.riskClass).toBe('high');

      const r003 = rules.find(r => r.id === 'R003');
      expect(r003?.riskClass).toBe('medium'); // default
    });

    it('should extract tool classes', () => {
      const content = `
# Rules
- [R001] Block dangerous bash commands [bash] @security
- [R002] Validate file edits [edit] @security
`;

      const bundle = compiler.compile(content);
      const allRules = [
        ...bundle.constitution.rules,
        ...bundle.shards.map(s => s.rule),
      ];

      const r001 = allRules.find(r => r.id === 'R001');
      expect(r001?.toolClasses).toContain('bash');

      const r002 = allRules.find(r => r.id === 'R002');
      expect(r002?.toolClasses).toContain('edit');
    });

    it('should extract verifiers', () => {
      const content = `
# Rules
- [R001] All tests must pass verify:tests-pass @testing
`;

      const bundle = compiler.compile(content);
      const r001 = bundle.manifest.rules.find(r => r.id === 'R001');
      expect(r001?.verifier).toBe('tests-pass');
    });

    it('should merge root and local files (local overrides)', () => {
      const root = `
# Rules
- [R001] Root rule version @security
- [R002] Only in root @general
`;

      const local = `
# Rules
- [R001] Local override version @security
- [R003] Only in local @testing
`;

      const bundle = compiler.compile(root, local);
      const allRules = [
        ...bundle.constitution.rules,
        ...bundle.shards.map(s => s.rule),
      ];

      // R001 should have local version
      const r001 = allRules.find(r => r.id === 'R001');
      expect(r001?.text).toContain('Local override version');

      // R002 should still exist from root
      const r002 = allRules.find(r => r.id === 'R002');
      expect(r002).toBeDefined();

      // R003 should exist from local
      const r003 = allRules.find(r => r.id === 'R003');
      expect(r003).toBeDefined();
    });

    it('should identify constitution sections', () => {
      const content = `
# Safety Invariants

- [R001] Never commit secrets (critical) @security

# Non-Negotiable Rules

- [R002] Always validate input (critical) @security

# Testing Guidelines

- [R010] Use TDD @testing
`;

      const bundle = compiler.compile(content);

      // Safety and non-negotiable sections should produce constitution rules
      expect(bundle.constitution.rules.length).toBeGreaterThan(0);
      expect(bundle.manifest.constitutionRules).toBeGreaterThan(0);
    });

    it('should generate a hash for the constitution', () => {
      const content = `
# Safety
- [R001] Rule one (critical) @security
`;

      const bundle = compiler.compile(content);
      expect(bundle.constitution.hash).toBeDefined();
      expect(bundle.constitution.hash.length).toBe(16);

      // Same content should produce same hash
      const bundle2 = compiler.compile(content);
      expect(bundle2.constitution.hash).toBe(bundle.constitution.hash);
    });
  });

  describe('parseGuidanceFile', () => {
    it('should handle empty content', () => {
      const rules = compiler.parseGuidanceFile('', 'root');
      expect(rules).toEqual([]);
    });

    it('should extract implicit rules from actionable bullet points', () => {
      const content = `
# Guidelines
- Must always run tests before committing
- Avoid using any type in TypeScript
- The sky is blue
`;

      const rules = compiler.parseGuidanceFile(content, 'root');

      // "Must always run tests" and "Avoid using any type" are actionable
      // "The sky is blue" is not actionable
      const actionable = rules.filter(r =>
        r.text.includes('tests') || r.text.includes('any type')
      );
      expect(actionable.length).toBeGreaterThan(0);
    });

    it('should infer intents from rule text', () => {
      const content = `
# Rules
- [R001] Fix the authentication bug @security
- [R002] Implement new feature @general
- [R003] Optimize database queries @performance
`;

      const rules = compiler.parseGuidanceFile(content, 'root');

      const r001 = rules.find(r => r.id === 'R001');
      expect(r001?.intents).toContain('security');

      const r003 = rules.find(r => r.id === 'R003');
      expect(r003?.intents).toContain('performance');
    });
  });
});

/**
 * Tests for the Agent Cell Conformance Kit
 *
 * Validates the MemoryClerkCell, SimulatedRuntime, and ConformanceRunner
 * against the canonical acceptance criteria for the guidance control plane.
 */
import { describe, it, expect, beforeEach } from 'vitest';
import {
  MemoryClerkCell,
  SimulatedRuntime,
  ConformanceRunner,
  createMemoryClerkCell,
  createConformanceRunner,
} from '../src/conformance-kit.js';
import type {
  TraceEvent,
  CellRunResult,
  CellRuntime,
  AgentCell,
  ConformanceTestResult,
  ReplayTestResult,
  SimulatedRuntimeConfig,
} from '../src/conformance-kit.js';
import { createMemoryWriteGate } from '../src/memory-gate.js';
import type { MemoryAuthority } from '../src/memory-gate.js';
import { createProofChain } from '../src/proof.js';
import { createLedger } from '../src/ledger.js';
import {
  createCoherenceScheduler,
  createEconomicGovernor,
} from '../src/coherence.js';

// ============================================================================
// Test Helpers
// ============================================================================

function makeAuthority(
  overrides: Partial<MemoryAuthority> = {},
): MemoryAuthority {
  return {
    agentId: 'test-clerk',
    role: 'worker',
    namespaces: ['clerk-workspace'],
    maxWritesPerMinute: 100,
    canDelete: false,
    canOverwrite: true,
    trustLevel: 0.8,
    ...overrides,
  };
}

function makeRuntimeConfig(
  overrides: Partial<SimulatedRuntimeConfig> = {},
): SimulatedRuntimeConfig {
  const authority = overrides.authority ?? makeAuthority();
  return {
    memoryGate: createMemoryWriteGate({
      authorities: [authority],
      enableContradictionTracking: false,
    }),
    proofChain: createProofChain({ signingKey: 'conformance-test-key' }),
    ledger: createLedger(),
    coherenceScheduler: createCoherenceScheduler(),
    economicGovernor: createEconomicGovernor({
      tokenLimit: 100_000,
      toolCallLimit: 1_000,
    }),
    authority,
    initialCoherenceScore: 0.9,
    ...overrides,
  };
}

function runDefaultCell(): {
  result: CellRunResult;
  runtime: SimulatedRuntime;
} {
  const config = makeRuntimeConfig();
  const runtime = new SimulatedRuntime(config);
  const cell = new MemoryClerkCell();
  const result = cell.run(runtime);
  return { result, runtime };
}

// ============================================================================
// MemoryClerkCell - Trace Structure
// ============================================================================

describe('MemoryClerkCell', () => {
  let result: CellRunResult;
  let runtime: SimulatedRuntime;

  beforeEach(() => {
    const out = runDefaultCell();
    result = out.result;
    runtime = out.runtime;
  });

  it('should complete with correct trace structure', () => {
    expect(result.cellId).toBeTruthy();
    expect(result.runId).toMatch(/^run-/);
    expect(result.traceEvents).toBeInstanceOf(Array);
    expect(result.traceEvents.length).toBeGreaterThan(0);

    // Every trace event must have required fields
    for (const event of result.traceEvents) {
      expect(typeof event.seq).toBe('number');
      expect(typeof event.ts).toBe('number');
      expect(typeof event.type).toBe('string');
      expect(typeof event.decision).toBe('string');
      expect(event.payload).toBeDefined();
      expect(event.budgetSnapshot).toBeDefined();
    }
  });

  it('should perform 20 reads, 1 inference, and 5 write attempts', () => {
    expect(result.memoryReads).toBe(20);
    expect(result.memoryWritesAttempted).toBe(5);

    // Count model_infer events in trace
    const inferenceEvents = result.traceEvents.filter(
      (e) => e.type === 'model_infer',
    );
    expect(inferenceEvents).toHaveLength(1);

    // Count memory_read events in trace
    const readEvents = result.traceEvents.filter(
      (e) => e.type === 'memory_read',
    );
    expect(readEvents).toHaveLength(20);

    // Count memory_write_proposed events in trace
    const writeProposals = result.traceEvents.filter(
      (e) => e.type === 'memory_write_proposed',
    );
    expect(writeProposals).toHaveLength(5);
  });

  it('should commit first 2 writes and block last 3 after coherence drop', () => {
    expect(result.memoryWritesCommitted).toBe(2);
    expect(result.memoryWritesBlocked).toBe(3);

    // Verify committed events in trace
    const committedEvents = result.traceEvents.filter(
      (e) => e.type === 'memory_write_committed',
    );
    expect(committedEvents).toHaveLength(2);

    // Verify blocked events in trace
    const blockedEvents = result.traceEvents.filter(
      (e) => e.type === 'memory_write_blocked',
    );
    expect(blockedEvents).toHaveLength(3);

    // All blocked events should cite coherence as the reason
    for (const event of blockedEvents) {
      expect(event.decision).toBe('blocked_coherence');
    }
  });

  it('should emit a proof envelope with a valid hash', () => {
    expect(result.proofEnvelopeHash).toBeDefined();
    expect(typeof result.proofEnvelopeHash).toBe('string');
    expect(result.proofEnvelopeHash).toHaveLength(64);
    expect(result.proofEnvelopeHash).toMatch(/^[0-9a-f]{64}$/);
  });

  it('should have sequential seq numbers in all trace events', () => {
    for (let i = 0; i < result.traceEvents.length; i++) {
      expect(result.traceEvents[i].seq).toBe(i);
    }
  });

  it('should have monotonically non-decreasing timestamps', () => {
    for (let i = 1; i < result.traceEvents.length; i++) {
      expect(result.traceEvents[i].ts).toBeGreaterThanOrEqual(
        result.traceEvents[i - 1].ts,
      );
    }
  });

  it('should track budget usage consistently', () => {
    expect(result.budgetUsage.tokens).toBeGreaterThan(0);
    expect(result.budgetUsage.toolCalls).toBeGreaterThan(0);

    // Each trace event budget snapshot should have non-negative values
    for (const event of result.traceEvents) {
      expect(event.budgetSnapshot.tokens).toBeGreaterThanOrEqual(0);
      expect(event.budgetSnapshot.toolCalls).toBeGreaterThanOrEqual(0);
      expect(event.budgetSnapshot.storageBytes).toBeGreaterThanOrEqual(0);
    }

    // Budget should be non-decreasing across events
    for (let i = 1; i < result.traceEvents.length; i++) {
      expect(
        result.traceEvents[i].budgetSnapshot.tokens,
      ).toBeGreaterThanOrEqual(
        result.traceEvents[i - 1].budgetSnapshot.tokens,
      );
      expect(
        result.traceEvents[i].budgetSnapshot.toolCalls,
      ).toBeGreaterThanOrEqual(
        result.traceEvents[i - 1].budgetSnapshot.toolCalls,
      );
    }
  });

  it('should record coherence history including the drop', () => {
    expect(result.coherenceHistory.length).toBeGreaterThan(0);

    // Should start healthy
    expect(result.coherenceHistory[0]).toBeGreaterThanOrEqual(0.7);

    // Should contain a drop below 0.3
    const minCoherence = Math.min(...result.coherenceHistory);
    expect(minCoherence).toBeLessThan(0.3);
  });

  it('should produce "restricted" outcome', () => {
    expect(result.outcome).toBe('restricted');
  });

  it('should have run_start as first event and run_end as last event', () => {
    expect(result.traceEvents[0].type).toBe('run_start');
    expect(
      result.traceEvents[result.traceEvents.length - 1].type,
    ).toBe('run_end');
  });

  it('should include a privilege_change event when coherence drops', () => {
    const privilegeChanges = result.traceEvents.filter(
      (e) => e.type === 'privilege_change',
    );
    expect(privilegeChanges.length).toBeGreaterThanOrEqual(1);

    // The privilege change should go from 'full' to 'suspended'
    const change = privilegeChanges[0];
    expect(change.payload.previousLevel).toBe('full');
    expect(change.payload.newLevel).toBe('suspended');
    expect(change.decision).toBe('full->suspended');
  });
});

// ============================================================================
// SimulatedRuntime - Isolation Tests
// ============================================================================

describe('SimulatedRuntime', () => {
  let runtime: SimulatedRuntime;

  beforeEach(() => {
    runtime = new SimulatedRuntime(makeRuntimeConfig());
  });

  it('should allow reads regardless of coherence level', () => {
    runtime.setCoherenceScore(0.1); // suspended
    const value = runtime.readMemory('any-key', 'clerk-workspace');
    expect(value).toBeNull(); // key does not exist, returns null
    expect(runtime.getMemoryReads()).toBe(1);
  });

  it('should block writes when coherence is below read-only threshold', () => {
    runtime.setCoherenceScore(0.2); // below 0.3 -> suspended
    const result = runtime.writeMemory('key', 'clerk-workspace', 'value');
    expect(result.allowed).toBe(false);
    expect(result.reason).toContain('suspended');
    expect(runtime.getMemoryWritesBlocked()).toBe(1);
    expect(runtime.getMemoryWritesCommitted()).toBe(0);
  });

  it('should allow writes when coherence is healthy', () => {
    const result = runtime.writeMemory('key', 'clerk-workspace', 'value');
    expect(result.allowed).toBe(true);
    expect(result.reason).toBe('Write committed');
    expect(runtime.getMemoryWritesCommitted()).toBe(1);
    expect(runtime.getMemoryWritesBlocked()).toBe(0);
  });

  it('should return simulated model response', () => {
    const response = runtime.invokeModel('test prompt');
    expect(response).toContain('[Simulated inference');
    expect(response).toContain('test prompt');
  });

  it('should emit privilege_change when score crosses threshold', () => {
    runtime.setCoherenceScore(0.2);

    const events = runtime.getTraceEvents();
    const changes = events.filter((e) => e.type === 'privilege_change');
    expect(changes).toHaveLength(1);
    expect(changes[0].payload.previousLevel).toBe('full');
    expect(changes[0].payload.newLevel).toBe('suspended');
  });

  it('should not emit privilege_change when score stays in same band', () => {
    runtime.setCoherenceScore(0.85); // still 'full'

    const events = runtime.getTraceEvents();
    const changes = events.filter((e) => e.type === 'privilege_change');
    expect(changes).toHaveLength(0);
  });

  it('should accumulate budget usage from reads and writes', () => {
    runtime.readMemory('k1', 'clerk-workspace');
    runtime.readMemory('k2', 'clerk-workspace');
    runtime.writeMemory('k3', 'clerk-workspace', { data: true });

    const usage = runtime.getBudgetUsage();
    expect(usage.toolCalls).toBeGreaterThan(0);
  });

  it('should emit custom trace events', () => {
    runtime.emitCustomTrace(
      'run_start',
      { cellId: 'test' },
      'started',
    );

    const events = runtime.getTraceEvents();
    expect(events).toHaveLength(1);
    expect(events[0].type).toBe('run_start');
    expect(events[0].decision).toBe('started');
    expect(events[0].seq).toBe(0);
  });

  it('should track memory operations for proof chain', () => {
    runtime.readMemory('k1', 'clerk-workspace');
    runtime.writeMemory('k2', 'clerk-workspace', 'value');

    const ops = runtime.getMemoryOps();
    expect(ops).toHaveLength(2);
    expect(ops[0].operation).toBe('read');
    expect(ops[1].operation).toBe('write');
  });
});

// ============================================================================
// Proof Envelope Validation
// ============================================================================

describe('Proof envelope', () => {
  it('should be emitted and verifiable', () => {
    const config = makeRuntimeConfig();
    const runtime = new SimulatedRuntime(config);
    const cell = new MemoryClerkCell();
    cell.run(runtime);

    // Proof chain should contain exactly one envelope
    expect(config.proofChain.getChainLength()).toBe(1);

    // Verify the chain is intact
    expect(config.proofChain.verifyChain()).toBe(true);

    // The tip envelope should be verifiable individually
    const tip = config.proofChain.getChainTip();
    expect(tip).toBeDefined();
    expect(config.proofChain.verify(tip!)).toBe(true);
  });

  it('should reference the correct agent and session', () => {
    const config = makeRuntimeConfig();
    const runtime = new SimulatedRuntime(config);
    const cell = new MemoryClerkCell('test-cell-id');
    const result = cell.run(runtime);

    const tip = config.proofChain.getChainTip()!;
    expect(tip.metadata.agentId).toBe('test-cell-id');
    expect(tip.metadata.sessionId).toBe(result.runId);
  });

  it('should include memory lineage entries', () => {
    const config = makeRuntimeConfig();
    const runtime = new SimulatedRuntime(config);
    const cell = new MemoryClerkCell();
    cell.run(runtime);

    const tip = config.proofChain.getChainTip()!;
    // Should have 20 reads + 2 committed writes = 22 memory operations
    expect(tip.memoryLineage.length).toBe(22);

    const reads = tip.memoryLineage.filter((l) => l.operation === 'read');
    const writes = tip.memoryLineage.filter(
      (l) => l.operation === 'write',
    );
    expect(reads).toHaveLength(20);
    expect(writes).toHaveLength(2);
  });
});

// ============================================================================
// Replay Test
// ============================================================================

describe('Replay test', () => {
  it('should produce identical decisions for the same trace', () => {
    const { result } = runDefaultCell();
    const runner = createConformanceRunner();
    const replay = runner.runReplayTest(result.traceEvents);

    expect(replay.identical).toBe(true);
    expect(replay.totalEvents).toBe(result.traceEvents.length);
    expect(replay.divergences).toHaveLength(0);
  });

  it('should detect divergences when trace decisions are altered', () => {
    const { result } = runDefaultCell();

    // Tamper with a coherence_check decision
    const tampered = result.traceEvents.map((e) => ({ ...e }));
    const coherenceEvent = tampered.find(
      (e) => e.type === 'coherence_check',
    );
    if (coherenceEvent) {
      coherenceEvent.decision = 'tampered_value';
    }

    const runner = createConformanceRunner();
    const replay = runner.runReplayTest(tampered);

    expect(replay.identical).toBe(false);
    expect(replay.divergences.length).toBeGreaterThan(0);
