    });

    it('should return the most restrictive decision', () => {
      const results = [
        { decision: 'warn' as const, gateName: 'a', reason: '', triggeredRules: [] },
        { decision: 'block' as const, gateName: 'b', reason: '', triggeredRules: [] },
