    store.assert('Current fact', 'test-ns', {
      validFrom: times.past1h,
      validUntil: times.future1h,
    });

    const pastTruth = reasoner.whatWasTrue('test-ns', times.past2h);

    expect(pastTruth).toHaveLength(1);
