      expect(accumulator.getScore('agent-1')).toBeGreaterThanOrEqual(0.0);
    });

    it('should handle multiple allows without exceeding 1.0', () => {
      for (let i = 0; i < 100; i++) {
        accumulator.recordOutcome('agent-1', 'allow', `allow ${i}`);
      }
