      ledger.record({
        agentId: 'agent-1',
        previousScore: 0.5,
        newScore: 0.6,
        delta: 0.1,
        reason: 'before',
        timestamp: 1000,
      });
      ledger.record({
        agentId: 'agent-2',
        previousScore: 0.5,
        newScore: 0.7,
